<script>
const MOODLE_SESSKEY=<?= json_encode(sesskey()) ?>;
const STG_LOCAL_KEY="stg_nk_0716_review_user_<?= (int)$USER->id ?>";
const HAS_FULL_REVIEW=true;
const IS_SITE_ADMIN=<?= is_siteadmin($USER) ? "true" : "false" ?>;
const LEADERBOARD_ENDPOINT=window.location.href.split("?")[0].split("#")[0];
const questions=[{"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Aplikasi", "question": "Sebuah kantor pelayanan pajak menghadapi peningkatan potensi risiko operasional pada proses validasi permohonan restitusi wajib pajak. Berdasarkan Surat Edaran Nomor SE-12/MK.1/2018, langkah aplikasi yang paling tepat dilakukan oleh kepala kantor adalah...", "options": ["Menghapus seluruh tahapan analisis profil risiko permohonan restitusi pajak guna mengejar target kecepatan layanan administratif dinas.", "Melakukan penolakan otomatis atas seluruh berkas restitusi yang diajukan oleh pelaku usaha demi mencegah kebocoran penerimaan kas negara.", "Memberdayakan Unit Kepatuhan Internal untuk memperkuat efektivitas tata kelola, manajemen risiko, serta pengendalian intern operasional.", "Mengalihkan seluruh tugas pengujian material restitusi kepada pihak konsultan swasta eksternal guna memangkas beban kerja pegawai negeri.", "Mengabaikan sistem pengendalian intern yang ada dan menyerahkan keputusan persetujuan sepenuhnya kepada pertimbangan staf pelaksana."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>SE-12/MK.1/2018 menegaskan kewajiban memberdayakan Unit Kepatuhan Internal (UKI) untuk meningkatkan efektivitas tata kelola, manajemen risiko, dan pengendalian intern pada setiap unit kerja.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pemberdayaan Unit Kepatuhan Internal (UKI) merupakan langkah konkret yang menjamin pengawasan lini kedua berjalan optimal dalam mengawal tata kelola unit kerja. Keberadaan UKI berfungsi mengidentifikasi titik rawan korupsi, menilai mitigasi risiko secara objektif, serta memastikan setiap tahapan operasional mematuhi prosedur yang sah tanpa menghambat kelancaran proses bisnis. Ketentuan regulasi menegaskan kewajiban pimpinan unit untuk memberdayakan UKI secara berkesinambungan guna memperkuat efektivitas tata kelola, manajemen risiko, dan pengendalian intern. Oleh karena itu, penguatan peran UKI pada opsi C merupakan tindakan penerapan manajemen risiko yang paling tepat dan akuntabel.</p><p>Jawaban yang sesuai adalah <strong>C. Memberdayakan Unit Kepatuhan Internal untuk memperkuat efektivitas tata kelola, manajemen risiko, serta pengendalian intern operasional.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menghapus analisis profil risiko melanggar asas kehati-hatian perbendaharaan negara.</li><li><strong>B</strong>: Keliru karena penolakan sepihak tanpa dasar pengujian melanggar hak wajib pajak serta kepastian hukum.</li><li><strong>D</strong>: Keliru karena pengalihan wewenang pengujian material kepada entitas swasta dilarang keras oleh hukum.</li><li><strong>E</strong>: Keliru karena peniadaan sistem pengendalian intern membuka peluang kecurangan jabatan yang merusak negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Analitis", "question": "Materi menguraikan arahan untuk membangun hubungan kemitraan yang konstruktif dengan Inspektorat Jenderal dalam pengawasan intern. Bagaimanakah analisis hubungan sinergis tersebut berkontribusi terhadap ketahanan organisasi kementerian?", "options": ["Kemitraan konstruktif memposisikan Itjen sebagai konsultan strategis yang mendeteksi deviasi secara objektif sebelum membesar.", "Kemitraan tersebut bertujuan mengamankan pimpinan unit kerja dari segala bentuk pemeriksaan hukum tindak pidana korupsi aparatur.", "Hubungan tersebut memungkinkan unit operasional membatasi akses data keuangan yang boleh diperiksa oleh auditor kementerian pusat.", "Sinergi tersebut dirancang untuk menggabungkan anggaran operasional pengawasan dengan anggaran belanja perjalanan dinas daerah.", "Hubungan kemitraan difokuskan untuk menghapus catatan temuan audit masa lalu agar laporan kinerja satker tampak sempurna selalu."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membangun kemitraan konstruktif dengan Inspektorat Jenderal merupakan instrumen strategis pengawasan intern untuk menjamin kepatuhan, tata tertib, dan penyelesaian masalah tata kelola secara dini.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Hubungan kemitraan konstruktif mengubah paradigma pengawasan dari sekadar mencari kesalahan menjadi kolaborasi perbaikan sistemik yang memperkuat ketahanan institusi. Ketika unit operasional memandang Inspektorat Jenderal sebagai mitra kerja yang solutif, informasi anomali dapat disampaikan secara terbuka tanpa rasa takut, sehingga tindakan korektif dapat segera dirumuskan sebelum berkembang menjadi skandal fatal. Arahan kebijakan menggariskan pentingnya kemitraan konstruktif antara pimpinan unit dan Itjen guna mengoptimalkan fungsi early warning system kementerian. Maka dari itu, penempatan Itjen sebagai konsultan strategis pada opsi A merefleksikan nilai sinergi pengawasan yang paling valid.</p><p>Jawaban yang sesuai adalah <strong>A. Kemitraan konstruktif memposisikan Itjen sebagai konsultan strategis yang mendeteksi deviasi secara objektif sebelum membesar.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena pengawasan intern tidak berfungsi sebagai sarana impunitas atau perlindungan pelaku kejahatan.</li><li><strong>C</strong>: Keliru karena pembatasan akses data justru melanggar independensi dan mandat resmi auditor negara.</li><li><strong>D</strong>: Keliru karena sinergi tata kelola tidak berkaitan dengan penggabungan mata anggaran perjalanan dinas.</li><li><strong>E</strong>: Keliru karena rekayasa penghapusan catatan temuan melanggar integritas akuntansi serta standar audit.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Aplikasi", "question": "Seorang pejabat administrator baru dilantik dan ingin memastikan seluruh jajarannya mematuhi ketentuan tata tertib serta kode etik. Berdasarkan panduan materi pada bagian himbauan, langkah awal yang harus diprioritaskan oleh pejabat tersebut adalah...", "options": ["Menetapkan denda finansial pribadi bagi staf yang terlambat menghadiri rapat koordinasi tanpa dasar hukum perundang-undangan.", "Membuat nota kesepahaman rahasia dengan pihak luar dinas guna membatasi pengaduan masyarakat atas kinerja pegawai kantor.", "Menutup saluran pengaduan internal (whistleblowing) demi menjaga citra baik unit kerja dari penilaian negatif pimpinan pusat.", "Menginternalisasi Nilai Kementerian Keuangan dan ketentuan penegakan disiplin kepada seluruh pegawai secara berkesinambungan.", "Memberikan kebebasan mutlak kepada pegawai senior untuk mengabaikan aturan jam kerja kantor demi menghargai masa bakti kerja."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Himbauan menegaskan perlunya menginternalisasi Nilai-Nilai Kementerian Keuangan dan ketentuan-ketentuan yang berhubungan dengan penegakan kode etik dan disiplin kepada seluruh pegawai di lingkungan kerjanya.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Internalisasi nilai dan kode etik secara konsisten merupakan fondasi primer dalam menanamkan kesadaran moral pegawai mengenai batas-batas kepatutan kedinasan. Pembinaan yang terencana membangun benteng integritas dari dalam diri pegawai, sehingga kepatuhan terhadap tata tertib lahir atas dasar tanggung jawab nurani, bukan semata-mata karena takut diawasi pimpinan. Dokumen materi secara jelas mewajibkan pimpinan unit untuk menginternalisasi nilai kementerian dan ketentuan penegakan disiplin kepada seluruh jajaran di lingkungannya. Oleh karenanya, pelaksanaan internalisasi nilai pada opsi D merupakan tindakan manajerial awal yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>D. Menginternalisasi Nilai Kementerian Keuangan dan ketentuan penegakan disiplin kepada seluruh pegawai secara berkesinambungan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pengenaan denda uang pribadi tanpa dasar hukum formal merupakan pungutan tidak sah.</li><li><strong>B</strong>: Keliru karena menghalangi saluran pengaduan publik mencederai akuntabilitas dan keterbukaan instansi.</li><li><strong>C</strong>: Keliru karena penutupan saluran whistleblowing merusak sistem pengendalian dan proteksi integritas.</li><li><strong>E</strong>: Keliru karena pemberian hak istimewa melanggar prinsip keadilan dan tata tertib kerja aparatur negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja menganggap bahwa koordinasi pengawasan dengan Inspektorat Jenderal hanyalah beban administratif yang memperlambat pekerjaan, sehingga satker memilih menutup akses informasi. Mengapa cara pandang satuan kerja tersebut KELIRU?", "options": ["Sikap satker tepat karena Inspektorat Jenderal bertugas memungut pajak daerah dari seluruh pegawai unit operasional kantor.", "Sikap satker keliru karena pengawasan intern Itjen berfungsi memitigasi risiko hukum dan menjamin tata tertib kinerja instansi.", "Sikap satker sangat bijaksana karena menjaga kerahasiaan operasional kantor dari campur tangan kementerian pusat negara.", "Sikap satker tepat karena kepatuhan etika sepenuhnya menjadi urusan pribadi masing-masing pegawai tanpa perlu audit resmi.", "Sikap satker dibenarkan karena anggaran pengawasan Itjen lebih baik dialihkan untuk tambahan penghasilan pegawai kantor."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Membangun kemitraan dengan Itjen dan menggiatkan penerapan nilai menjamin terpeliharanya tata tertib, mencegah pelanggaran hukum, serta mengamankan kelancaran tugas seluruh pegawai.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menutup akses terhadap pengawasan intern mencerminkan kesesatan pikir yang menempatkan fungsi kontrol sebagai musuh birokrasi, padahal audit merupakan pagar pengaman organisasi. Tanpa evaluasi objektif dari auditor internal, titik-titik lemah dalam pengelolaan anggaran dan pelayanan akan terabaikan hingga akhirnya meledak menjadi kasus hukum yang menjatuhkan reputasi kementerian. Penjelasan regulasi menegaskan bahwa kemitraan konstruktif dengan Inspektorat Jenderal mutlak diperlukan untuk mencegah pelanggaran disiplin dan menjamin kelancaran tugas kenegaraan. Oleh sebab itu, penolakan koordinasi pada skenario di atas merupakan kekeliruan fatal yang membahayakan akuntabilitas institusi.</p><p>Jawaban yang sesuai adalah <strong>B. Sikap satker keliru karena pengawasan intern Itjen berfungsi memitigasi risiko hukum dan menjamin tata tertib kinerja instansi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena Itjen mengemban mandat audit kepatuhan, bukan pemungutan pajak daerah pemerintah.</li><li><strong>C</strong>: Keliru karena menutup akses data dari auditor kementerian merupakan pelanggaran disiplin berat.</li><li><strong>D</strong>: Keliru karena integritas institusi menuntut mekanisme pengawasan formal, bukan sekadar ranah privat.</li><li><strong>E</strong>: Keliru karena pengalihan dana pengawasan menjadi bonus melanggar regulasi perbendaharaan negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Analitis", "question": "Uraian materi menegaskan bahwa penerapan nilai dan kode etik harus menjamin kelancaran pelaksanaan tugas seluruh pegawai tanpa terkecuali. Bagaimanakah korelasi logis antara prinsip 'tanpa terkecuali' dengan keberhasilan penegakan disiplin organisasi?", "options": ["Prinsip tanpa terkecuali mewajibkan seluruh pejabat struktural pensiun dini secara massal setiap terjadi pelanggaran staf.", "Prinsip tersebut menuntut agar setiap pegawai memeriksa barang bawaan pribadi rekan kerjanya setiap memasuki pintu kantor.", "Prinsip tersebut bermakna bahwa sanksi disiplin hanya diberlakukan jika perbuatan pegawai disiarkan oleh media televisi.", "Prinsip tersebut membatasi ruang dialog kedinasan antara staf bawahan dengan pimpinan unit dalam urusan operasional kerja.", "Prinsip tanpa terkecuali menegakkan keadilan hukum dan mencegah timbulnya kekebalan jabatan yang merusak moralitas kerja."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penerapan Nilai-Nilai Kementerian Keuangan dan kode etik menjamin terpeliharanya tata tertib dalam kelancaran pelaksanaan tugas dan fungsi seluruh pegawai tanpa terkecuali.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Efektivitas penegakan aturan dalam sebuah organisasi publik bertumpu pada asas kepastian hukum dan persamaan kedudukan di hadapan regulasi (equality before the rules). Ketika suatu instansi menerapkan standar ganda—di mana staf bawahan ditindak tegas sementara pejabat senior dibiarkan melanggar—wibawa hukum akan runtuh dan memicu krisis kepercayaan serta demotivasi massal. Penegasan materi bahwa aturan berlaku bagi seluruh pegawai tanpa terkecuali menjamin keadilan substantif yang mengikat moralitas seluruh korps aparatur. Karena itulah, opsi E memberikan analisis yang paling sahih mengenai pentingnya kesetaraan penegakan aturan demi menjaga marwah institusi.</p><p>Jawaban yang sesuai adalah <strong>E. Prinsip tanpa terkecuali menegakkan keadilan hukum dan mencegah timbulnya kekebalan jabatan yang merusak moralitas kerja.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penerapan prinsip keadilan tidak diwujudkan lewat pemberhentian massal nir-prosedural.</li><li><strong>B</strong>: Keliru karena penegakan etika tidak identik dengan tindakan penggeledahan fisik yang melanggar privasi.</li><li><strong>C</strong>: Keliru karena penegakan hukum wajib didasarkan pada fakta material, bukan viralitas pemberitaan publik.</li><li><strong>D</strong>: Keliru karena prinsip kesetaraan aturan justru memperkuat komunikasi kerja yang transparan dan sehat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Evaluatif", "question": "Seorang pimpinan satuan kerja berpendapat bahwa pengawasan etika dan kode etik hanya perlu diperketat bagi pegawai golongan rendah, sedangkan pejabat eselon tidak perlu diawasi. Mengapa cara pandang pimpinan tersebut KELIRU?", "options": ["Cara pandang tersebut keliru karena pejabat eselon memegang diskresi besar yang justru menuntut keteladanan integritas.", "Cara pandang tersebut sangat tepat karena pejabat struktural secara otomatis telah terbebas dari segala godaan materi.", "Cara pandang tersebut sangat efisien karena anggaran pengawasan dapat dialihkan untuk membiayai seminar luar negeri.", "Cara pandang tersebut dapat diterima sepanjang tidak ada laporan tertulis dari aparat penegak hukum kejaksaan agung.", "Cara pandang tersebut mencerminkan kearifan lokal yang mengutamakan penghormatan mutlak kepada status sosial atasan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penerapan nilai dan kode etik mengikat seluruh pegawai tanpa terkecuali. Pejabat memegang kewenangan strategis sehingga keteladanan pimpinan (tone at the top) menjadi kunci pencegahan pelanggaran.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Membebaskan pejabat struktural dari pengawasan merupakan kekeliruan fatal karena wewenang dan diskresi anggaran terbesar justru berada di tangan para pemegang jabatan puncak. Potensi risiko penyalahgunaan wewenang dan korupsi sistemik jauh lebih besar dampaknya apabila dilakukan oleh pimpinan dibandingkan dengan kekhilafan staf pelaksana. Dokumen ketentuan menegaskan bahwa penerapan nilai dan tata tertib berlaku wajib bagi seluruh jajaran kementerian tanpa terkecuali demi mencegah perbuatan melawan hukum. Dengan demikian, evaluasi kritis pada opsi A secara tepat membuktikan bahwa akuntabilitas pimpinan justru harus lebih tinggi karena mengemban amanah keteladanan.</p><p>Jawaban yang sesuai adalah <strong>A. Cara pandang tersebut keliru karena pejabat eselon memegang diskresi besar yang justru menuntut keteladanan integritas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena status jabatan struktural tidak pernah menjamin kekebalan alami dari godaan moral.</li><li><strong>C</strong>: Keliru karena pemangkasan fungsi kontrol demi perjalanan luar negeri melanggar etika tata kelola.</li><li><strong>D</strong>: Keliru karena pencegahan dini tidak boleh menunggu sampai terjadinya intervensi pidana kejaksaan.</li><li><strong>E</strong>: Keliru karena tatanan birokrasi modern menuntut akuntabilitas meritokrasi, bukan feodalisme jabatan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Analitis", "question": "Peraturan Menteri Keuangan Nomor 190/PMK.01/2018 diterbitkan dengan memperhatikan perubahan cepat pada teknologi, nilai etika, budaya, dan perilaku masyarakat. Bagaimanakah korelasi perubahan faktor-faktor tersebut dengan kebutuhan regulasi kode etik yang baru?", "options": ["Kemajuan teknologi mengharuskan kementerian menutup portal pelayanan digital dan kembali menggunakan formulir cetak kertas.", "Perubahan perilaku masyarakat menuntut kementerian memberikan wewenang kepada aparat untuk menetapkan tarif layanan sendiri.", "Transformasi digital menghadirkan saluran komunikasi baru yang membawa kerentanan etika seperti ujaran kebencian di internet.", "Perkembangan etika masyarakat menuntut agar aparatur kementerian dibebaskan dari kewajiban memakai pakaian dinas seragam.", "Perubahan budaya modern mewajibkan kementerian mengizinkan pegawai menerima gratifikasi berupa barang elektronik mewah."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Latar belakang terbitnya PMK 190/PMK.01/2018 adalah adanya perubahan teknologi, nilai etika, budaya, dan perilaku yang terjadi di masyarakat guna mencegah pelanggaran disiplin dan menjaga martabat PNS.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Lahirnya ruang digital dan media sosial telah mengaburkan batasan antara ranah privat dan ranah kedinasan, sehingga perilaku pegawai di dunia maya dapat langsung berdampak pada citra institusi. Pola interaksi digital yang tanpa batas memunculkan risiko etika baru, seperti penyebaran informasi rahasia, pelanggaran netralitas politik daring, hingga flexing gaya hidup yang mencederai keadilan sosial. Penjelasan latar belakang PMK 190/2018 mencatat perubahan teknologi dan perilaku masyarakat sebagai urgensi pembaruan regulasi kode perilaku aparatur negara. Oleh karenanya, opsi C menguraikan korelasi adaptif regulasi terhadap risiko teknologi secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Transformasi digital menghadirkan saluran komunikasi baru yang membawa kerentanan etika seperti ujaran kebencian di internet.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena modernisasi kementerian justru mendorong digitalisasi proses bisnis yang akuntabel.</li><li><strong>B</strong>: Keliru karena seluruh biaya pelayanan kementerian diatur secara ketat dalam regulasi penerimaan negara.</li><li><strong>D</strong>: Keliru karena disiplin berpakaian seragam tetap diwajibkan sebagai simbol profesionalisme birokrasi.</li><li><strong>E</strong>: Keliru karena penerimaan gratifikasi barang elektronik mewah merupakan tindak pidana suap yang dilarang.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan tujuan utama dari penetapan Peraturan Menteri Keuangan Nomor 190/PMK.01/2018 tentang Kode Etik dan Kode Perilaku Pegawai Negeri Sipil di lingkungan Kementerian Keuangan?", "options": ["Mencegah terjadinya pelanggaran disiplin aparatur sipil negara di lingkungan kementerian pengelola fiskal negara.", "Menjamin pemberian impunitas hukum pidana kepada pegawai kementerian yang terbukti melakukan penyalahgunaan wewenang.", "Menjaga harkat, martabat, dan kehormatan korps Pegawai Negeri Sipil dalam melaksanakan tugas kenegaraan dan sosial.", "Menyelaraskan perilaku kerja sehari-hari aparatur dengan nilai luhur yang telah ditetapkan oleh kementerian keuangan.", "Menyediakan pedoman perilaku yang adaptif terhadap dinamika transformasi teknologi dan pergeseran nilai masyarakat."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tujuan PMK 190/PMK.01/2018 adalah untuk mencegah pelanggaran disiplin pegawai Kementerian Keuangan, serta menjaga martabat dan kehormatan Pegawai Negeri Sipil di lingkungan Kementerian Keuangan sesuai Nilai-Nilai Kementerian Keuangan dan perundangan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kode etik dan kode perilaku dirancang sebagai panduan moral dan instrumen kepatuhan, bukan perisai kekebalan hukum untuk melindungi aparatur dari jerat tindak pidana korupsi. Tujuan sejati pembentukan regulasi perilaku adalah mencegah pelanggaran disiplin serta memelihara kehormatan dan martabat institusi di mata masyarakat pembayar pajak. Materi menegaskan bahwa PMK 190/2018 ditujukan untuk pencegahan pelanggaran disiplin dan penjagaan martabat PNS kementerian tanpa membuka ruang kompromi hukum. Maka dari itu, pernyataan tentang pemberian impunitas pidana pada opsi B merupakan klausa yang sama sekali bukan tujuan regulasi tersebut.</p><p>Jawaban yang sesuai adalah <strong>B. Menjamin pemberian impunitas hukum pidana kepada pegawai kementerian yang terbukti melakukan penyalahgunaan wewenang.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Tujuan sah yang tercantum secara eksplisit dalam materi regulasi mengenai pencegahan pelanggaran disiplin.</li><li><strong>C</strong>: Tujuan sah mengenai pemeliharaan martabat dan kehormatan korps aparatur negara sesuai regulasi.</li><li><strong>D</strong>: Tujuan sah mengenai penyelarasan tindakan harian dengan rumusan Nilai Kementerian Keuangan.</li><li><strong>E</strong>: Tujuan sah mengenai penyediaan pedoman etika yang adaptif menghadapi revolusi teknologi dan etika.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka program penegakan kepatuhan disiplin terpadu pada tingkat unit operasional yang mengintegrasikan peran kepemimpinan, Unit Kepatuhan Internal, dan Inspektorat Jenderal!", "options": ["Pimpinan memusatkan seluruh kewenangan -> UKI dibubarkan fungsinya -> Itjen dilarang memasuki area kantor pelayanan dinas.", "Pimpinan membiarkan pelanggaran kecil -> UKI merekayasa laporan audit -> Itjen menerbitkan sertifikat kepatuhan instansi.", "Pimpinan menghukum pegawai tanpa bukti -> UKI memungut denda uang tunai -> Itjen menghapus hak pensiun seluruh staf satker.", "Pimpinan menginternalisasi nilai -> UKI memitigasi risiko operasional -> Itjen mengawal pengawasan objektif berkelanjutan.", "Pimpinan menyerahkan pengawasan ke LSM luar -> UKI menjadi loket layanan -> Itjen mengelola pengadaan barang inventaris."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Integrasi pencegahan: pimpinan menginternalisasi nilai dan kode etik, Unit Kepatuhan Internal meningkatkan manajemen risiko dan pengendalian intern, serta membangun kemitraan konstruktif dengan Itjen dalam pengawasan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Sistem pengendalian terpadu memerlukan harmonisasi peran antar lini pertahanan organisasi guna memutus rantai peluang terjadinya penyimpangan moral. Pimpinan unit bertindak sebagai motor edukasi nilai dan penegak disiplin pertama, UKI mengawal pengendalian intern dan mendeteksi anomali proses secara melekat, sementara Inspektorat Jenderal memberikan pengawasan independen lini ketiga untuk perbaikan makro. Sintesis tiga pilar ini merealisasikan visi regulasi kementerian dalam mewujudkan tata kelola yang bersih dan bebas korupsi. Oleh sebab itu, kerangka kerja terpadu pada opsi D merupakan rancangan operasional yang paling akurat dan kokoh.</p><p>Jawaban yang sesuai adalah <strong>D. Pimpinan menginternalisasi nilai -> UKI memitigasi risiko operasional -> Itjen mengawal pengawasan objektif berkelanjutan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pembubaran UKI dan penolakan Itjen merusak sistem checks and balances institusi negara.</li><li><strong>B</strong>: Keliru karena rekayasa data dan pembiaran pelanggaran merupakan bentuk persekongkolan kejahatan dinas.</li><li><strong>C</strong>: Keliru karena penghukuman sewenang-wenang dan pungutan liar melanggar asas hukum dan hak asasi.</li><li><strong>E</strong>: Keliru karena menyerahkan kendali disiplin korps ke pihak luar merusak rantai komando birokrasi negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 35", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah sintesis manajerial mengenai bagaimana penguatan kode etik mampu menjaga martabat dan kehormatan institusi kementerian di tengah era keterbukaan informasi digital!", "options": ["Dengan menugaskan staf memanipulasi algoritma mesin pencari internet guna menyembunyikan berita penyelewengan dinas.", "Dengan melarang seluruh masyarakat mengajukan permohonan informasi publik melalui kanal Pejabat Pengelola Dokumentasi.", "Dengan menghapus seluruh saluran media sosial resmi kementerian agar aparatur terbebas dari tuntutan kritik publik.", "Dengan mewajibkan seluruh aparatur menandatangani surat pernyataan tidak akan pernah menggunakan komputer jinjing dinas.", "Dengan menanamkan integritas perilaku aparatur yang selaras perkataan dan perbuatan di dunia nyata maupun ruang siber."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 35", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 35</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penguatan kode etik bertujuan menjaga martabat dan kehormatan PNS di lingkungan Kementerian Keuangan dalam merespons perubahan teknologi, etika, dan perilaku masyarakat yang sangat cepat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Di tengah transparansi digital yang radikal, kehormatan dan martabat institusi pemerintah tidak lagi dapat dipertahankan melalui penyensoran informasi, melainkan melalui otentisitas integritas setiap aparaturnya. Ketika kode etik dihayati hingga ke alam bawah sadar, pegawai akan secara mandiri mengendalikan ucapan, tindakan, dan jejak digitalnya agar senantiasa mencerminkan kemuliaan tugas pelayan publik. Penjelasan materi membuktikan bahwa penyesuaian regulasi kode etik lahir untuk merespons dinamika teknologi demi membentengi martabat aparatur sipil negara. Maka dari itu, sintesis penanaman integritas terintegrasi pada opsi E merupakan strategi komunikasi dan perilaku yang paling unggul.</p><p>Jawaban yang sesuai adalah <strong>E. Dengan menanamkan integritas perilaku aparatur yang selaras perkataan dan perbuatan di dunia nyata maupun ruang siber.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena manipulasi informasi digital adalah pembodohan publik yang mencoreng martabat birokrasi.</li><li><strong>B</strong>: Keliru karena menghalangi permohonan informasi publik melanggar undang-undang keterbukaan informasi.</li><li><strong>C</strong>: Keliru karena menutup kanal komunikasi sosial mencerminkan sikap anti-kritik yang menolak modernitas.</li><li><strong>D</strong>: Keliru karena pelarangan perangkat komputer jinjing justru melumpuhkan efektivitas kerja era modern.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 35.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Aplikasi", "question": "Menjelang pemilihan kepala daerah serentak, seorang pejabat fungsional perbendaharaan menerima ajakan untuk menghadiri kampanye terbuka dari seorang figur pasangan calon kepala daerah. Berdasarkan kode etik nilai integritas, tindakan yang harus diambil oleh pejabat tersebut adalah...", "options": ["Menghadiri kampanye secara terang-terangan memakai seragam dinas demi menunjukkan keterbukaan birokrasi negara.", "Menolak ajakan tersebut dan bersikap netral demi mematuhi larangan keterlibatan politik praktis aparatur negara.", "Mengunggah foto bersama pasangan calon ke akun media sosial dinas kantor dengan membubuhkan tanda pagar kampanye.", "Menjadi pembicara tim sukses politik di luar jam dinas kerja kantor dengan dalih kebebasan menyatakan pendapat warga.", "Menyumbangkan sebagian dana anggaran operasional satuan kerja untuk mendanai logistik rapat akbar pasangan calon."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Integritas butir kelima mewajibkan pegawai bersikap netral dalam Pemilihan Calon Presiden/Wapres, Kepala Daerah/Wakil Kepala Daerah, serta Anggota Legislatif Pusat dan Daerah.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kewajiban menjaga netralitas politik merupakan asas fundamental bagi aparatur sipil negara guna menjamin pelayanan publik diselenggarakan secara adil, objektif, dan bebas dari diskriminasi partisan. Keterlibatan dalam kampanye politik praktis mencoreng wibawa kementerian dan membuka potensi benturan kepentingan dalam pengelolaan keuangan serta fasilitas negara. Ketentuan kode etik nilai integritas secara tegas memerintahkan pegawai bersikap netral dalam pemilihan umum eksekutif maupun legislatif di seluruh tingkatan. Oleh karena itu, sikap tegas menolak ajaran kampanye pada opsi B adalah penerapan kode etik yang paling sah dan wajib ditaati.</p><p>Jawaban yang sesuai adalah <strong>B. Menolak ajakan tersebut dan bersikap netral demi mematuhi larangan keterlibatan politik praktis aparatur negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menghadiri kampanye terbuka mengenakan atribut dinas merupakan pelanggaran netralitas berat.</li><li><strong>C</strong>: Keliru karena menyebarkan konten dukungan politik di media sosial melanggar prinsip kehati-hatian digital.</li><li><strong>D</strong>: Keliru karena menjadi tim sukses di luar jam kerja tetap dilarang oleh regulasi disiplin pegawai negeri sipil.</li><li><strong>E</strong>: Keliru karena penyalahgunaan anggaran keuangan negara untuk dana politik merupakan tindak pidana korupsi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Analitis", "question": "Dalam PMK Nomor 190/PMK.01/2018, integritas didefinisikan sebagai berpikir, berkata, berperilaku, dan bertindak dengan baik dan benar serta selalu memegang teguh kode etik dan moral. Bagaimanakah keterkaitan logis keempat ranah kepribadian tersebut dalam membentuk integritas utuh?", "options": ["Pikiran yang menyimpang tidak menjadi masalah bagi martabat instansi selama perkataan di forum publik terdengar manis.", "Tindakan fisik adalah satu-satunya indikator integritas, sedangkan keselarasan antara ucapan dan moralitas dapat diabaikan.", "Keempat ranah dapat dipisahkan secara parsial di mana pegawai boleh berkata bohong demi kelancaran negosiasi dinas.", "Integritas menuntut keselarasan mutlak dari hulu pikiran batin, ucapan verbal, hingga tindakan nyata yang bermoral.", "Perilaku sopan santun pegawai cukup ditunjukkan kepada atasan langsung, sementara kepada pemangku kepentingan bebas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Definisi Integritas dalam PMK 190/PMK.01/2018: seluruh pegawai harus berpikir, berkata, berperilaku, dan bertindak dengan baik dan benar serta selalu memegang teguh Kode Etik dan prinsip-prinsip moral.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Integritas hakiki bukanlah pencitraan lahiriah semata, melainkan kesatuan organik yang tidak terpisahkan antara apa yang diniatkan dalam kalbu, apa yang diucapkan di lisan, dan apa yang dikerjakan dalam tindakan nyata. Retaknya salah satu dimensi—misalnya berkata jujur namun bertindak korup di balik layar—merupakan bentuk kemunafikan moral yang meruntuhkan esensi integritas di hadapan hukum dan nurani. Rumusan regulasi secara presisi mengintegrasikan ranah kognitif (berpikir), verbal (berkata), afektif (berperilaku), dan konatif (bertindak) di bawah kompas kode etik dan moralitas luhur. Oleh sebab itu, opsi D menjelaskan filosofi keselarasan utuh integritas secara paling mendalam.</p><p>Jawaban yang sesuai adalah <strong>D. Integritas menuntut keselarasan mutlak dari hulu pikiran batin, ucapan verbal, hingga tindakan nyata yang bermoral.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kemunafikan verbal yang menutupi niat menyimpang bertentangan dengan esensi integritas.</li><li><strong>B</strong>: Keliru karena pemisahan tindakan fisik dari moralitas batin hanya melahirkan kepatuhan semu mekanistis.</li><li><strong>C</strong>: Keliru karena kebohongan dalam interaksi dinas mencederai asas kejujuran dan keterbukaan tata kelola publik.</li><li><strong>E</strong>: Keliru karena standar kesopanan kode etik berlaku setara kepada seluruh pihak tanpa perlakuan diskriminatif.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf pelaksana merencanakan liburan akhir tahun ke luar negeri untuk keperluan berwisata bersama keluarga besarnya. Berdasarkan rincian kode etik nilai integritas pada materi, prosedur administratif kedinasan yang wajib dipenuhi staf tersebut adalah...", "options": ["Mengajukan permohonan izin kepada pejabat yang berwenang setiap akan melakukan perjalanan luar negeri urusan pribadi.", "Berangkat secara diam-diam tanpa memberitahukan atasan demi menjaga kerahasiaan agenda liburan keluarga pribadi staf.", "Menggunakan paspor dinas diplomatik kenegaraan agar mendapatkan fasilitas bebas visa wisata di negara tujuan liburan.", "Membebankan seluruh biaya tiket pesawat dan penginapan hotel liburan ke dalam pos belanja perjalanan dinas kantor.", "Meminta bantuan agen perjalanan swasta rekanan kantor untuk memalsukan surat tugas dinas luar negeri palsu dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas butir kesembilan mewajibkan pegawai mengajukan permohonan izin setiap akan melakukan perjalanan ke luar negeri untuk kepentingan pribadi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kewajiban mengajukan izin resmi perjalanan ke luar negeri urusan pribadi merupakan mekanisme pengendalian internal untuk memastikan keamanan aparatur serta memitigasi potensi risiko benturan kepentingan lintas negara. Prosedur ini menjamin bahwa status kedinasan, ketersediaan pegawai dalam tanggap darurat dinas, serta kepatuhan hukum keimigrasian tetap terpantau secara akuntabel oleh pimpinan kementerian. Teks kode etik secara eksplisit menyatakan keharusan mengajukan permohonan izin setiap kali bepergian ke mancanegara untuk kepentingan privat. Dengan demikian, pengajuan izin resmi pada opsi A adalah prosedur wajib yang harus dieksekusi pegawai.</p><p>Jawaban yang sesuai adalah <strong>A. Mengajukan permohonan izin kepada pejabat yang berwenang setiap akan melakukan perjalanan luar negeri urusan pribadi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena bepergian ke luar negeri tanpa izin tertulis pimpinan merupakan pelanggaran disiplin formal.</li><li><strong>C</strong>: Keliru karena paspor dinas diplomatik hanya boleh dipergunakan untuk penugasan kenegaraan yang sah.</li><li><strong>D</strong>: Keliru karena membebankan biaya liburan pribadi pada pos belanja negara merupakan tindak pidana korupsi.</li><li><strong>E</strong>: Keliru karena pemalsuan surat penugasan dinas adalah kejahatan pemalsuan dokumen surat resmi kenegaraan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat pemeriksa pajak bersedia menghadiri jamuan makan malam pribadi di restoran mewah bersama kuasa hukum wajib pajak yang sedang diperiksa tanpa surat tugas resmi. Mengapa tindakan pejabat tersebut KELIRU?", "options": ["Tindakan pejabat sangat terpuji karena jamuan makan malam terbukti meningkatkan kepuasan mitra usaha wajib pajak.", "Tindakan pejabat dapat dibenarkan sepanjang kuasa hukum wajib pajak berjanji tidak akan memberitahukan ke media massa.", "Tindakan pejabat merupakan wujud nyata nilai sinergi kementerian dalam menjalin relasi akrab dengan dunia usaha daerah.", "Tindakan pejabat sangat efisien karena satker dapat menghemat anggaran jamuan tamu dinas pada tahun anggaran berjalan.", "Tindakan pejabat keliru karena melanggar larangan menemui pihak yang berpotensi menimbulkan konflik kepentingan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Integritas butir kesepuluh melarang keras pegawai menemui pihak yang berpotensi menimbulkan konflik kepentingan, kecuali karena penugasan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pertemuan informal tanpa surat penugasan resmi dengan pihak yang sedang diperiksa meruntuhkan independensi serta objektivitas pemeriksaan dan membuka pintu terjadinya suap serta negosiasi kewajiban perpajakan secara tidak sah. Hubungan privat di ruang tertutup antara aparat pemeriksa dan pihak berperkara secara nyata mencederai kepercayaan masyarakat serta merusak marwah kelembagaan pengelola fiskal negara. Ketentuan kode etik butir kesepuluh secara kategoris melarang pegawai menemui pihak yang berpotensi konflik kepentingan kecuali karena mandat penugasan sah. Oleh sebab itu, evaluasi pada opsi E secara tepat membuktikan terjadinya pelanggaran etik berat.</p><p>Jawaban yang sesuai adalah <strong>E. Tindakan pejabat keliru karena melanggar larangan menemui pihak yang berpotensi menimbulkan konflik kepentingan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kepuasan wajib pajak tidak boleh diraih melalui transaksi persekongkolan yang merugikan negara.</li><li><strong>B</strong>: Keliru karena kerahasiaan pelanggaran tidak menghapus status perbuatan melawan hukum dan kode etik.</li><li><strong>C</strong>: Keliru karena sinergi birokrasi berakar pada kemitraan profesional, bukan kolusi personal di restoran mewah.</li><li><strong>D</strong>: Keliru karena gratifikasi jamuan pihak berperkara adalah tindak pidana korupsi, bukan penghematan kantor.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Analitis", "question": "Berdasarkan rumusan nilai pada PMK Nomor 190/PMK.01/2018, manakah di antara pernyataan berikut yang secara akurat membedakan fokus utama antara nilai Profesionalisme dan nilai Sinergi?", "options": ["Profesionalisme berfokus pada kecepatan pelayanan tanpa akurasi data, sedangkan Sinergi berorientasi pada kepatuhan politik kekuasaan negara.", "Profesionalisme menuntut pegawai bekerja mandiri tanpa perlu berinteraksi, sedangkan Sinergi mengharuskan seluruh tugas dikerjakan massal.", "Profesionalisme menekankan penyelesaian tugas secara tuntas akurat berbasis kompetensi, sedangkan Sinergi fokus pada kemitraan produktif.", "Profesionalisme hanya berlaku bagi pejabat struktural kementerian, sedangkan Sinergi diwajibkan secara khusus untuk staf bawahan kantor.", "Profesionalisme mengutamakan keuntungan materiil pribadi pegawai, sedangkan Sinergi menekankan kepatuhan buta pada instruksi sepihak."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Profesionalisme berarti bekerja tuntas dan akurat berdasarkan kompetensi terbaik dan penuh tanggung jawab; Sinergi berarti berkomitmen membangun kerja sama internal produktif dan kemitraan harmonis untuk hasil berkualitas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Nilai Profesionalisme berfokus pada kualitas teknis individu pegawai dalam menyelesaikan mandat tugasnya secara presisi, akurat, dan bertanggung jawab berdasarkan keahlian kompetensinya. Sementara itu, nilai Sinergi berorientasi pada dinamika relasional antarunit dan para pemangku kepentingan guna menyatukan beragam potensi menjadi karya bersama yang berdaya guna tinggi bagi bangsa. Rumusan resmi PMK 190/2018 secara presisi menempatkan profesionalisme sebagai pilar kompetensi tuntas, dan sinergi sebagai pilar kemitraan harmonis yang produktif. Maka dari itu, opsi C menyajikan pembedaan substansi kedua nilai secara paling sahih.</p><p>Jawaban yang sesuai adalah <strong>C. Profesionalisme menekankan penyelesaian tugas secara tuntas akurat berbasis kompetensi, sedangkan Sinergi fokus pada kemitraan produktif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena profesionalisme menuntut akurasi presisi tinggi, dan sinergi berorientasi karya, bukan politik.</li><li><strong>B</strong>: Keliru karena profesionalisme birokrasi tidak membenarkan isolasi mandiri yang mengabaikan kerja sama tim.</li><li><strong>D</strong>: Keliru karena seluruh nilai kementerian mengikat seluruh jenjang hierarki pegawai tanpa pemilahan kasta.</li><li><strong>E</strong>: Keliru karena profesionalisme mengutamakan integritas dedikasi publik di atas keuntungan materiil sempit.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan perilaku yang mencerminkan pemenuhan Kode Etik dan Kode Perilaku Nilai Integritas sebagaimana diatur dalam PMK Nomor 190/PMK.01/2018?", "options": ["Menjaga citra, harkat, dan martabat Kementerian Keuangan di berbagai forum formal maupun informal di dalam dan luar negeri.", "Memanfaatkan akun media sosial dinas untuk mengkampanyekan figur calon presiden tertentu demi mengharapkan kenaikan jabatan.", "Berbicara dan bertindak secara jujur dan pantas sesuai dengan fakta dan kebenaran sesuai dengan ketentuan peraturan yang berlaku.", "Menjunjung tinggi norma yang berlaku dalam masyarakat serta Kode Etik dan Kode Perilaku profesi yang mengikat jabatan kedinasan.", "Menjadi teladan serta menegakkan Kode Etik dan Kode Perilaku di lingkungan kerja maupun dalam interaksi kehidupan bermasyarakat."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas meliputi: menjaga citra/harkat/martabat di dalam/luar negeri, junjung norma, netral pemilu/pilkada/pileg, bijak medsos, bicara/tindak jujur pantas, teladan, izin ke luar negeri, hindari konflik kepentingan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menggunakan fasilitas negara atau akun media sosial kedinasan untuk mendukung salah satu kontestan politik dalam pemilu merupakan pelanggaran berat terhadap asas netralitas aparatur sipil negara. Perilaku partisan tersebut merusak kepercayaan publik terhadap integritas pengelola keuangan negara dan melanggar sumpah jabatan serta regulasi disiplin kepegawaian. Butir-butir kode etik integritas secara tegas mewajibkan aparatur bersikap netral dalam pemilihan umum dan bijak dalam menggunakan media sosial. Dengan demikian, kampanye politik pada opsi B jelas merupakan perbuatan yang sama sekali bukan cerminan nilai integritas melainkan pelanggaran kode etik.</p><p>Jawaban yang sesuai adalah <strong>B. Memanfaatkan akun media sosial dinas untuk mengkampanyekan figur calon presiden tertentu demi mengharapkan kenaikan jabatan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Cerminan integritas sah yang tercantum pada butir pertama kode etik integritas dalam regulasi.</li><li><strong>C</strong>: Cerminan integritas sah mengenai kejujuran dan kepantasan berbicara sesuai butir ketujuh kode etik.</li><li><strong>D</strong>: Cerminan integritas sah mengenai penghormatan norma masyarakat dan profesi sesuai butir kedua.</li><li><strong>E</strong>: Cerminan integritas sah mengenai keteladanan penegakan kode etik sesuai butir kedelapan dalam aturan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat pembuat komitmen mengetahui bahwa sebuah perusahaan peserta tender pengadaan barang di kantornya dimiliki oleh adik kandungnya sendiri. Berdasarkan butir keempat nilai integritas, pertimbangan evaluatif yang paling tepat adalah...", "options": ["Memenangkan perusahaan adik kandung secara langsung guna menjaga keutuhan tali silaturahmi keluarga besar pejabat.", "Mengubah spesifikasi teknis tender secara rahasia agar hanya perusahaan adik kandung yang mampu memenuhi syarat lelang.", "Mendeklarasikan benturan kepentingan secara tertulis dan mengundurkan diri dari proses pengadaan barang tersebut.", "Meminta bagian komisi keuntungan sebesar sepuluh persen dari adik kandung atas kelulusan berkas administrasi lelang.", "Mengabaikan fakta hubungan kekeluargaan tersebut dan tetap menjadi ketua panitia penentu pemenang tender lelang."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Integritas butir keempat menegaskan kewajiban menghindari konflik kepentingan pribadi, kelompok, maupun golongan dalam setiap pengambilan keputusan kedinasan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keberadaan hubungan kekerabatan sedarah antara pejabat pembuat komitmen dan penyedia barang secara otomatis menciptakan situasi benturan kepentingan yang merusak objektivitas penilaian tender. Mengundurkan diri dan mengungkapkan potensi benturan kepentingan kepada atasan merupakan standar etika tertinggi yang memitigasi risiko hukum serta menjamin proses lelang diselenggarakan secara transparan dan adil bagi seluruh pelaku usaha. Landasan kode etik nilai integritas mewajibkan setiap pegawai menghindari konflik kepentingan pribadi maupun golongan tanpa pengecualian. Maka dari itu, deklarasi benturan kepentingan dan pengunduran diri pada opsi C adalah putusan etis yang paling akuntabel.</p><p>Jawaban yang sesuai adalah <strong>C. Mendeklarasikan benturan kepentingan secara tertulis dan mengundurkan diri dari proses pengadaan barang tersebut.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena memenangkan kerabat keluarga adalah praktik nepotisme yang melanggar hukum perbendaharaan.</li><li><strong>B</strong>: Keliru karena rekayasa spesifikasi lelang merupakan perbuatan melawan hukum yang merugikan keuangan negara.</li><li><strong>D</strong>: Keliru karena meminta komisi pengadaan barang adalah tindak pidana korupsi penerimaan gratifikasi suap.</li><li><strong>E</strong>: Keliru karena tetap memimpin lelang keluarga merupakan pembiaran benturan kepentingan yang fatal.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Analitis", "question": "Ketentuan butir pertama nilai integritas mewajibkan aparatur menjaga citra, harkat, dan martabat Kementerian Keuangan di forum formal maupun informal, baik di dalam maupun di luar negeri. Mengapa cakupan forum informal di luar negeri turut diatur secara mengikat?", "options": ["Karena kementerian menanggung seluruh biaya konsumsi pribadi pegawai selama berada di restoran luar negeri.", "Karena aparatur kementerian dibebaskan dari kewajiban mematuhi hukum pidana yang berlaku di negara tujuan kunjungan.", "Karena forum informal di luar negeri merupakan tempat yang sah untuk memperjualbelikan dokumen rahasia negara.", "Karena status aparatur sipil negara melekat pada diri pegawai, sehingga perilakunya merepresentasikan wibawa bangsa.", "Karena kementerian berencana mendirikan kantor perwakilan diplomatik di setiap kota metropolitan dunia internasional."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas butir pertama: menjaga citra, harkat, dan martabat Kementerian Keuangan di berbagai forum, baik formal maupun informal di dalam maupun di luar negeri.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Predikat sebagai aparatur sipil negara pengelola keuangan negara bukanlah identitas yang dapat dilepas pasang begitu jam kantor usai atau ketika pegawai melintasi perbatasan negara. Skandal moral atau tindakan tercela yang dilakukan seorang aparatur di forum informal internasional akan langsung diekspos oleh komunitas global dan meruntuhkan kredibilitas serta persepsi tata kelola Republik Indonesia di mata investor internasional. Ketentuan kode etik sengaja mencakup forum informal di mancanegara guna memastikan integritas perilaku melekat kuat sebagai karakter hidup pegawai. Oleh karena itu, opsi D menyajikan analisis logis mengenai representasi wibawa negara secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>D. Karena status aparatur sipil negara melekat pada diri pegawai, sehingga perilakunya merepresentasikan wibawa bangsa.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kementerian tidak menanggung beban konsumsi privat perjalanan non-kedinasan di luar negeri.</li><li><strong>B</strong>: Keliru karena pegawai negeri sipil tetap tunduk penuh pada hukum yang berlaku di wilayah negara setempat.</li><li><strong>C</strong>: Keliru karena pembocoran dan penjualan rahasia negara merupakan kejahatan pengkhianatan berat kenegaraan.</li><li><strong>E</strong>: Keliru karena pembukaan pos diplomatik merupakan wewenang eksklusif kementerian urusan luar negeri.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah panduan operasional etika bermedia sosial (social media policy) pada tingkat unit kerja yang menjabarkan butir keenam nilai integritas secara aplikatif!", "options": ["Panduan wajib memuat: verifikasi kebenaran info sebelum sebar, larangan ujaran kebencian, jaga rahasia, dan netralitas.", "Panduan harus mewajibkan seluruh staf membagikan seluruh draf rahasia nota dinas keuangan ke grup publik percakapan daring.", "Panduan mengizinkan pegawai menyebarkan gosip negatif pribadi pimpinan satker di internet sepanjang menggunakan akun samaran.", "Panduan melarang keras pegawai memiliki telepon seluler pintar dan memutus seluruh sambungan internet kantor secara permanen.", "Panduan mewajibkan pegawai memberikan komentar pujian berlebihan kepada seluruh akun partai politik peserta pemilu daerah."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas butir keenam mewajibkan pegawai menggunakan media sosial dengan bijak, tidak menyebarkan hoax, menjaga kerahasiaan dinas, serta memelihara netralitas politik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penggunaan media sosial secara bijak menuntut rumusan kebijakan operasional yang mampu memandu aparatur menyeimbangkan kebebasan berekspresi dengan kewajiban menjaga kerahasiaan dan martabat korps. Panduan etika siber yang komprehensif menggariskan kewajiban menyaring kebenaran informasi sebelum membagikannya, mengharamkan ujaran kebencian dan konten provokatif, menegakkan netralitas politik, serta membentengi data rahasia institusi dari kebocoran daring. Butir keenam kode etik integritas menempatkan kebijaksanaan bermedia sosial sebagai pilar etika kontemporer pegawai negeri sipil. Oleh karenanya, sintesis kebijakan media sosial pada opsi A adalah model aturan turunan yang paling solutif.</p><p>Jawaban yang sesuai adalah <strong>A. Panduan wajib memuat: verifikasi kebenaran info sebelum sebar, larangan ujaran kebencian, jaga rahasia, dan netralitas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena penyebaran draf dokumen keuangan rahasia ke ruang publik merupakan tindak pidana kejahatan siber.</li><li><strong>C</strong>: Keliru karena fitnah dan pencemaran nama baik dengan akun anonim melanggar hukum pidana informasi elektronik.</li><li><strong>D</strong>: Keliru karena pemutusan internet total mencerminkan ketakutan primitif yang melumpuhkan kinerja modern.</li><li><strong>E</strong>: Keliru karena memuji akun partai politik melanggar kewajiban netralitas mutlak aparatur sipil negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 36", "difficulty": "HOTS • Evaluatif", "question": "Seorang aparatur berpandangan bahwa sumpah jabatan Pegawai Negeri Sipil hanyalah seremonial pelantikan masa lalu yang tidak lagi mengikat secara hukum dalam pelaksanaan tugas sehari-hari. Mengapa cara pandang aparatur tersebut KELIRU?", "options": ["Cara pandang aparatur sangat benar karena sumpah jabatan tidak pernah dicatat dalam lembaran berita resmi negara.", "Cara pandang aparatur dapat diterima sepanjang pegawai bersangkutan berhasil mencapai seratus persen target sasaran kerja.", "Cara pandang aparatur merupakan bentuk pemikiran modern yang membebaskan birokrasi dari ikatan tradisi kuno institusi.", "Cara pandang aparatur sangat tepat karena etika jabatan sepenuhnya dapat digantikan oleh teknologi kecerdasan buatan.", "Cara pandang aparatur keliru karena sumpah jabatan adalah ikrar moral dan hukum suci yang mengikat sepanjang masa bakti."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 36", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 36</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas butir ketiga mewajibkan setiap pegawai untuk memegang teguh sumpah jabatan Pegawai Negeri Sipil sepanjang masa pengabdiannya kepada bangsa dan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Sumpah jabatan PNS bukanlah formalitas bibir belaka, melainkan perjanjian sakral di hadapan Tuhan Yang Maha Esa dan negara yang meletakkan dasar legitimasi moral serta tanggung jawab hukum bagi pemegang jabatan. Meremehkan sumpah jabatan membuka pintu bagi relativisme moral, di mana pegawai merasa bebas mengkompromikan integritas demi keuntungan materiil sesaat atau kenyamanan diri sendiri. Butir ketiga kode etik nilai integritas secara tegas mewajibkan setiap aparatur memegang teguh sumpah jabatannya dalam setiap tarikan nafas penugasan. Oleh sebab itu, evaluasi pada opsi E membuktikan bahwa sumpah jabatan merupakan pilar ikrar abadi yang wajib dipegang teguh.</p><p>Jawaban yang sesuai adalah <strong>E. Cara pandang aparatur keliru karena sumpah jabatan adalah ikrar moral dan hukum suci yang mengikat sepanjang masa bakti.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena berita acara sumpah jabatan merupakan dokumen hukum sah yang tersimpan dalam arsip negara.</li><li><strong>B</strong>: Keliru karena pencapaian target kinerja administratif tidak boleh melegitimasi pengingkaran ikrar moral jabatan.</li><li><strong>C</strong>: Keliru karena modernisasi birokrasi justru memperkuat kepatuhan moral atas janji pengabdian publik aparatur.</li><li><strong>D</strong>: Keliru karena kecerdasan buatan hanyalah alat bantu teknis, bukan pengganti nurani dan komitmen etika manusia.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 36.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Analitis", "question": "Kode etik nilai integritas memuat larangan tegas untuk tidak menunjukkan gaya hidup hedonisme sebagai bentuk empati kepada masyarakat dan sesama pegawai. Bagaimanakah landasan moral sosiologis yang mendasari larangan hedonisme tersebut?", "options": ["Kementerian Keuangan mengalami kebangkrutan likuiditas kas negara sehingga pegawai dilarang berbelanja barang primer.", "Pemerintah melarang kepemilikan aset properti dan kendaraan bermotor bagi seluruh warga negara Republik Indonesia.", "Pamer kemewahan aparatur melukai rasa keadilan publik pembayar pajak dan meruntuhkan legitimasi moral institusi fiskal.", "Aparatur kementerian diwajibkan menyumbangkan seluruh harta kekayaan warisan keluarga kepada kas perbendaharaan negara.", "Larangan pamer kekayaan bertujuan memaksa pegawai menyimpan seluruh uang tunai di dalam brankas besi rumah dinas."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas melarang menunjukkan gaya hidup hedonisme sebagai bentuk empati kepada masyarakat terutama kepada sesama pegawai, guna menjaga martabat dan kepercayaan publik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kementerian Keuangan mengemban amanah mengelola uang rakyat, memungut pajak, dan menjaga stabilitas fiskal negara, sehingga integritas moral aparaturnya selalu berada di bawah sorotan tajam publik. Pertunjukan gaya hidup hedonistik dan pamer kekayaan (flexing) oleh aparat pengelola dana publik mencederai hati rakyat yang sedang berjuang memenuhi kebutuhan hidup, sekaligus memicu kecurigaan atas asal-usul kekayaan yang tidak wajar. Rumusan kode etik secara eksplisit menegaskan bahwa larangan hedonisme merupakan wujud empati sosial kepada masyarakat pembayar pajak dan sesama rekan sejawat. Oleh karena itu, opsi C memberikan analisis sosiologis dan legitimasi moral yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Pamer kemewahan aparatur melukai rasa keadilan publik pembayar pajak dan meruntuhkan legitimasi moral institusi fiskal.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena larangan hedonisme berakar pada etika kepantasan sosial, bukan krisis kas negara.</li><li><strong>B</strong>: Keliru karena hukum negara menjamin hak kepemilikan aset yang diperoleh secara sah dan halal.</li><li><strong>D</strong>: Keliru karena kode etik tidak menuntut penyitaan hak waris pribadi aparatur yang sah menurut hukum.</li><li><strong>E</strong>: Keliru karena regulasi etika tidak mengatur tata cara penimbunan uang tunai di rumah pegawai.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Aplikasi", "question": "Ketika menyusun surat elektronik (e-mail) kedinasan untuk menjawab pertanyaan satuan kerja mitra kementerian, seorang staf pelaksana mengindahkan etika berkomunikasi profesional. Bentuk penerapan etika berkomunikasi surat elektronik yang paling tepat adalah...", "options": ["Menggunakan seluruh huruf kapital berukuran besar pada badan surat disertai kata-kata kemarahan atas kekeliruan mitra kerja.", "Menyisipkan materi promosi produk bisnis pribadi sampingan staf di bagian lampiran surat tanggapan kedinasan kantor.", "Mengabaikan salam pembuka dan salam penutup serta menuliskan pesan singkatan gaul yang sulit dipahami pihak penerima.", "Mengirimkan tanggapan surat elektronik dari akun pribadi komersial gratis tanpa mencantumkan identitas resmi instansi.", "Menggunakan bahasa formal yang santun, mencantumkan subjek yang jelas, serta menyajikan informasi akurat dan solutif."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme mewajibkan pegawai mengindahkan etika berkomunikasi dalam bercakap-cakap, bertelepon, menerima tamu, dan surat-menyurat termasuk surat elektronik (e-mail) serta media komunikasi lainnya.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Komunikasi tertulis resmi melalui surat elektronik merefleksikan standar profesionalisme dan wibawa kelembagaan kementerian di hadapan para mitra kerja. Penggunaan bahasa yang baku, lugas, dan santun, kejelasan judul subjek korespondensi, serta ketepatan materi jawaban memastikan pesan tersampaikan secara efektif tanpa menimbulkan salah tafsir atau ketersinggungan psikologis. Rincian kode etik nilai profesionalisme secara khusus mewajibkan pemenuhan etika korespondensi elektronik dan ragam media komunikasi kedinasan lainnya. Dengan demikian, penerapan etika komunikasi yang berbobot pada opsi E adalah wujud profesionalisme yang paling sempurna.</p><p>Jawaban yang sesuai adalah <strong>E. Menggunakan bahasa formal yang santun, mencantumkan subjek yang jelas, serta menyajikan informasi akurat dan solutif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penggunaan huruf kapital melambangkan bentakan kasar yang melanggar kesantunan dinas.</li><li><strong>B</strong>: Keliru karena menyisipkan promosi komersial privat menyalahgunakan sarana kedinasan resmi negara.</li><li><strong>C</strong>: Keliru karena ketiadaan salam dan pemakaian bahasa gaul merusak kesopanan komunikasi birokrasi.</li><li><strong>D</strong>: Keliru karena surat dinas resmi wajib dikirimkan melalui akun surel kedinasan terverifikasi negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan butir ketentuan Kode Etik dan Kode Perilaku Nilai Profesionalisme sebagaimana diuraikan dalam PMK Nomor 190/PMK.01/2018?", "options": ["Memakai tindik (piercing) di bagian hidung dan lidah bagi seluruh pegawai pria maupun wanita demi mengikuti tren mode.", "Mengutamakan kepentingan bangsa dan organisasi di atas kepentingan pribadi dalam setiap pelaksanaan tugas kenegaraan.", "Bekerja sesuai standar operasional prosedur dan kewenangan jabatan yang telah diatur secara sah dalam tata kelola organisasi.", "Berani mengakui kesalahan dan bertanggung jawab atas pelaksanaan tugas serta berupaya memperbaiki kekeliruan kerja.", "Menjaga kebersihan, keamanan, dan kenyamanan ruang kerja, termasuk tidak merokok di luar area merokok yang disediakan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme mencakup: utamakan kepentingan bangsa/organisasi, kerja sesuai SOP, tuntas akurat, jaga rahasia, disiplin waktu, akui kesalahan, etika komunikasi, seragam/sepatu, tidak tindik (kecuali wanita di daun telinga/alasan agama), larangan tato terbuka.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Standar kerapian dan etika berbusana kementerian melarang keras pegawai memakai tindik (piercing), dengan pengecualian tunggal pada daun telinga khusus bagi pegawai wanita atau atas dasar kewajiban agama yang sah. Pemakaian tindik di hidung, lidah, atau bagian tubuh lainnya bagi pegawai pria maupun wanita merusak citra profesional korps birokrasi negara yang menuntut wibawa kehormatan tinggi. PMK 190/2018 secara eksplisit mencantumkan larangan pemakaian tindik sebagai bagian dari disiplin penampilan kerja profesional. Oleh sebab itu, klausa pada opsi A jelas merupakan perbuatan yang dilarang dan bukan merupakan ketentuan kode etik profesionalisme.</p><p>Jawaban yang sesuai adalah <strong>A. Memakai tindik (piercing) di bagian hidung dan lidah bagi seluruh pegawai pria maupun wanita demi mengikuti tren mode.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Ketentuan sah mengenai pengutamaan kepentingan bangsa di atas kepentingan pribadi sesuai regulasi.</li><li><strong>C</strong>: Ketentuan sah mengenai kepatuhan terhadap SOP dan batas kewenangan jabatan dalam penugasan.</li><li><strong>D</strong>: Ketentuan sah mengenai kejujuran mengakui kesalahan dan kesiapan memikul tanggung jawab perbaikan.</li><li><strong>E</strong>: Ketentuan sah mengenai ketertiban ruang kerja dan kepatuhan terhadap area khusus merokok di kantor.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat pengawas kerap melontarkan kata-kata makian bernada menghina fisik dan melakukan perundungan (bullying) kepada pegawai baru di hadapan rekan kerja lainnya. Mengapa tindakan pejabat tersebut KELIRU?", "options": ["Tindakan pejabat sangat mendidik karena perundungan mental merupakan metode paling cepat melatih ketahanan staf.", "Tindakan pejabat dapat dibenarkan sepanjang pegawai baru tersebut tidak melaporkan peristiwa tersebut kepada polisi.", "Tindakan pejabat mencerminkan kepemimpinan tegas yang sah dalam menertibkan keterlambatan berkas administrasi kantor.", "Tindakan pejabat keliru karena melanggar larangan bertindak sewenang-wenang dan perundungan terhadap pegawai.", "Tindakan pejabat sangat tepat karena aparatur kementerian harus dibiasakan menghadapi tekanan psikologis berat."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Integritas melarang keras bertindak sewenang-wenang, melakukan perundungan (bullying) dan/atau pelecehan terhadap pegawai atau pihak lain baik di dalam maupun di luar lingkungan kerja.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Tindakan perundungan, makian, dan perendahan martabat fisik merupakan pelanggaran berat terhadap hak asasi manusia dan kode etik integritas yang menghancurkan kesehatan mental pegawai. Sikap toksik tersebut mematikan motivasi kerja, menciptakan iklim ketakutan yang menghambat inovasi, serta mencoreng kehormatan korps aparatur sipil negara secara keseluruhan. Teks regulasi secara lugas melarang pegawai bertindak sewenang-wenang atau melakukan perundungan baik di dalam maupun di luar kantor. Maka dari itu, penilaian kritis pada opsi D secara tepat menegaskan bahwa perilaku pejabat tersebut adalah kekeliruan fatal yang mencederai etika integritas.</p><p>Jawaban yang sesuai adalah <strong>D. Tindakan pejabat keliru karena melanggar larangan bertindak sewenang-wenang dan perundungan terhadap pegawai.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena perundungan psikologis bukanlah metode pendidikan melainkan kekerasan jabatan terlarang.</li><li><strong>B</strong>: Keliru karena ketiadaan laporan kepolisian tidak menggugurkan status pelanggaran kode etik disiplin.</li><li><strong>C</strong>: Keliru karena ketegasan kepemimpinan wajib berlandaskan etika kesopanan, bukan penghinaan fisik verbal.</li><li><strong>E</strong>: Keliru karena pembiasaan mental profesional harus dibangun lewat pembinaan bermartabat, bukan makian.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf pelaksana menyadari terdapat kekeliruan rumus kalkulasi pada lembar kerja analisis penetapan tarif bea masuk yang telah ditandatanganinya. Berdasarkan kode etik nilai profesionalisme, tindakan aplikasi yang paling tepat dilakukan staf tersebut adalah...", "options": ["Menghancurkan seluruh berkas dokumen fisik dan arsip digital komputer agar jejak kekeliruan tidak ditemukan atasan.", "Berani mengakui kesalahan, melaporkannya kepada atasan langsung, dan segera membetulkan penetapan sesuai tarif sah.", "Menyalahkan staf magang junior di depan forum rapat seolah-olah kekeliruan tersebut sepenuhnya dibuat oleh junior.", "Membiarkan kekeliruan tersebut berlanjut demi menjaga gengsi pribadi dan menghindari penurunan nilai sasaran kinerja.", "Meminta uang tutup mulut kepada pihak importir agar kekeliruan penetapan tarif tidak dibocorkan kepada inspektorat."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme butir kedelapan mewajibkan pegawai: berani mengakui kesalahan dan bertanggung jawab atas pelaksanaan tugasnya.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keberanian mengakui kekhilafan dan mengambil langkah korektif seketika merupakan ciri keluhuran budi aparatur yang berjiwa profesional sejati. Menutupi kekeliruan kalkulasi penetapan tarif keuangan negara justru memperparah dampak kerugian penerimaan kas negara serta melipatgandakan sanksi pelanggaran hukum di kemudian hari. Dokumen kode etik profesionalisme secara tegas mengamanatkan aparatur untuk berani mengakui kesalahan dan bertanggung jawab penuh menuntaskan perbaikan tugasnya. Oleh sebab itu, tindakan pelaporan jujur dan pembetulan tarif pada opsi B adalah aplikasi kode etik profesionalisme yang paling ksatria.</p><p>Jawaban yang sesuai adalah <strong>B. Berani mengakui kesalahan, melaporkannya kepada atasan langsung, dan segera membetulkan penetapan sesuai tarif sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pemusnahan barang bukti berkas resmi negara merupakan tindak pidana kejahatan arsip.</li><li><strong>C</strong>: Keliru karena melempar kesalahan kepada pihak lain mencerminkan sikap pengecut yang nir-integritas.</li><li><strong>D</strong>: Keliru karena membiarkan kesalahan demi gengsi pribadi mengorbankan akuntabilitas keuangan negara.</li><li><strong>E</strong>: Keliru karena meminta suap uang tutup mulut adalah pemerasan dan korupsi jabatan tingkat tinggi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Evaluatif", "question": "Seorang pegawai pria datang ke kantor pelayanan dengan mengenakan anting tindik di kedua telinganya dengan alasan mengekspresikan seni kebebasan generasi muda. Bagaimanakah evaluasi kepatuhan perilaku pegawai tersebut menurut standar kode etik profesionalisme?", "options": ["Perilaku pegawai melanggar kode etik karena pria dilarang memakai tindik dalam standar kerapian dinas kementerian.", "Perilaku pegawai sangat terpuji karena seni kebebasan berekspresi menduduki derajat hukum tertinggi di kementerian.", "Perilaku pegawai dapat dibenarkan sepanjang anting tindik yang dikenakan terbuat dari bahan logam mulia emas murni.", "Perilaku pegawai sangat sesuai dengan modernisasi birokrasi yang membebaskan aparatur dari seluruh norma kesopanan.", "Perilaku pegawai merupakan bentuk hak asasi mutlak yang tidak boleh diatur sama sekali oleh peraturan menteri."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme mengatur larangan memakai tindik (piercing), kecuali penggunaan di daun telinga khusus untuk pegawai perempuan atau karena alasan keagamaan yang sah.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Birokrasi pelayanan publik menuntut disiplin penampilan yang mencerminkan kerapian, kesopanan, dan wibawa kenegaraan yang dapat diterima oleh seluruh lapisan masyarakat luas. Regulasi etika berbusana kementerian secara eksplisit melarang penggunaan tindik, dengan pengecualian yang dibatasi hanya pada daun telinga untuk pegawai perempuan atau demi alasan keyakinan agama resmi. Pelanggaran terhadap standar berpenampilan oleh pegawai pria tersebut mencederai citra korps aparatur sipil negara dan melanggar kode perilaku profesionalisme. Maka dari itu, penilaian pada opsi A secara tepat menegaskan bahwa tindakan tersebut merupakan pelanggaran aturan kedinasan.</p><p>Jawaban yang sesuai adalah <strong>A. Perilaku pegawai melanggar kode etik karena pria dilarang memakai tindik dalam standar kerapian dinas kementerian.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena ekspresi kebebasan seni aparatur dibatasi oleh kepatutan norma seragam dinas kenegaraan.</li><li><strong>C</strong>: Keliru karena bahan logam anting tidak mengubah substansi larangan penggunaan tindik bagi pegawai pria.</li><li><strong>D</strong>: Keliru karena modernisasi birokrasi menuntut ketertiban perilaku, bukan anarki penghapusan etika norma.</li><li><strong>E</strong>: Keliru karena PNS secara sukarela terikat pada aturan disiplin dinas saat dilantik menjadi aparatur negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Analitis", "question": "Kode etik nilai profesionalisme butir keenam mewajibkan pegawai menjaga informasi dan data Kementerian Keuangan yang bersifat rahasia. Mengapa pengamanan data rahasia diposisikan sebagai pilar profesionalisme yang sangat krusial?", "options": ["Agar kementerian dapat menjual basis data wajib pajak kepada lembaga perbankan swasta dengan harga tinggi.", "Agar seluruh data anggaran negara dapat dirahasiakan sepenuhnya dari pemeriksaan Badan Pemeriksa Keuangan.", "Agar pegawai memiliki hak monopoli mutlak atas kepemilikan data fiskal untuk dipergunakan saat pensiun dinas.", "Agar pimpinan satuan kerja dapat menggunakan data rahasia tersebut untuk mengancam pihak swasta yang kritis.", "Karena kebocoran data fiskal dan wajib pajak membahayakan stabilitas perekonomian dan merusak kepercayaan publik."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Profesionalisme butir keenam mewajibkan pegawai: menjaga informasi dan data Kementerian Keuangan yang bersifat rahasia demi mengamankan kepentingan negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Data keuangan negara, catatan perpajakan pelaku usaha, perbendaharaan, serta kepabeanan merupakan aset strategis kenegaraan yang menyangkut kedaulatan moneter, stabilitas pasar finansial, dan hak privasi warga negara. Kebocoran informasi fiskal rahasia dapat memicu kepanikan pasar modal, persaingan usaha tidak sehat, hingga penyalahgunaan oleh pihak yang berniat jahat untuk merugikan perekonomian nasional. Ketentuan kode etik profesionalisme menempatkan kewajiban menjaga kerahasiaan data sebagai benteng kehormatan aparatur sipil negara. Oleh karenanya, opsi E memberikan analisis mendalam mengenai dampak kebocoran data terhadap stabilitas ekonomi secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>E. Karena kebocoran data fiskal dan wajib pajak membahayakan stabilitas perekonomian dan merusak kepercayaan publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena komersialisasi basis data rahasia warga negara merupakan kejahatan perbankan dan korupsi.</li><li><strong>B</strong>: Keliru karena BPK memegang mandat konstitusional untuk memeriksa seluruh laporan keuangan negara.</li><li><strong>C</strong>: Keliru karena data fiskal adalah milik negara Republik Indonesia, bukan hak milik pribadi aparatur sipil.</li><li><strong>D</strong>: Keliru karena pemanfaatan data rahasia untuk intimidasi merupakan bentuk pemerasan jabatan yang haram.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Evaluatif", "question": "Seorang aparatur bersikukuh merokok di dalam ruang kerja pelayanan terpadu dengan alasan ruangan berpendingin udara miliknya membutuhkan kehangatan asap tembakau. Mengapa tindakan aparatur tersebut KELIRU?", "options": ["Tindakan aparatur sangat tepat karena asap rokok terbukti menyegarkan udara ruang kerja pelayanan bagi warga.", "Tindakan aparatur sangat efisien karena satker tidak perlu lagi mengalokasikan area khusus merokok di luar gedung.", "Tindakan aparatur keliru karena melanggar kewajiban menjaga kenyamanan dan larangan merokok di luar area resmi.", "Tindakan aparatur dapat diterima sepanjang abu rokok dibuang ke dalam map berkas arsip wajib pajak yang tebal.", "Tindakan aparatur merupakan hak istimewa pegawai senior yang tidak dapat diintervensi oleh peraturan menteri."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme mewajibkan menjaga kebersihan, keamanan, dan kenyamanan ruang kerja, termasuk tidak merokok di luar area merokok yang telah disediakan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Merokok di dalam ruang pelayanan tertutup melanggar hak hidup sehat rekan kerja dan masyarakat pengguna layanan serta menghadirkan bahaya kebakaran gedung perkantoran pemerintah. Sikap mementingkan kenyamanan pribadi di atas keselamatan umum merusak citra profesional birokrasi dan melanggar ketentuan tata tertib ruang kerja yang sehat dan bermartabat. PMK 190/2018 secara kategoris memerintahkan aparatur mematuhi larangan merokok di luar area khusus merokok demi menjaga kebersihan, keamanan, dan kenyamanan lingkungan kerja. Maka dari itu, penilaian pada opsi C secara tepat membuktikan bahwa perbuatan tersebut adalah pelanggaran kode etik.</p><p>Jawaban yang sesuai adalah <strong>C. Tindakan aparatur keliru karena melanggar kewajiban menjaga kenyamanan dan larangan merokok di luar area resmi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena asap rokok mengandung racun berbahaya yang mengancam kesehatan saluran pernapasan.</li><li><strong>B</strong>: Keliru karena penyediaan area khusus merokok bertujuan melokalisasi polusi asap dari ruang kerja umum.</li><li><strong>D</strong>: Keliru karena membuang puntung rokok ke tumpukan berkas arsip memicu bahaya kebakaran gedung kantor.</li><li><strong>E</strong>: Keliru karena senioritas masa kerja tidak memberikan kekebalan hukum dari kewajiban tata tertib dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka manajerial penanganan kritik dan saran publik yang konstruktif pada unit pelayanan agar pegawai tidak merespons secara negatif atau berlebihan!", "options": ["Petugas loket memaki warga yang memberi kritik -> akun medsos warga diretas -> berkas layanan warga ditolak selamanya.", "Penerimaan santun masukan -> telaah objektif SOP -> tindakan perbaikan layanan -> apresiasi atas partisipasi publik.", "Membuat laporan kepolisian atas seluruh kritik warga -> menutup loket pelayanan langsung -> menghapus kotak aduan.", "Mengharuskan warga membayar uang jaminan aduan tunai sebelum diizinkan menuliskan lembar kritik layanan kantor.", "Menyerahkan seluruh tindak lanjut keluhan warga kepada juru bicara calo layanan yang beroperasi di sekitar kantor."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Profesionalisme melarang pegawai merespon kritik dan saran dengan negatif secara berlebihan, serta mewajibkan penyelesaian tugas sesuai SOP dan etika komunikasi santun.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kritik dan saran dari pemangku kepentingan merupakan bahan bakar utama bagi penyempurnaan kualitas tata kelola pelayanan publik secara berkesinambungan. Merespons keluhan publik dengan defensif, emosional, atau marah justru membuktikan ketidakmatangan mental dan merusak legitimasi profesional aparatur negara. Alur penanganan yang sehat menuntut penyambutan masukan dengan santun, analisis objektif terhadap kelemahan prosedur, perbaikan nyata pada sistem pelayanan, serta ucapan terima kasih atas kepedulian masyarakat. Oleh karenanya, sintesis alur perbaikan pada opsi B merupakan model respons profesional yang paling unggul.</p><p>Jawaban yang sesuai adalah <strong>B. Penerimaan santun masukan -> telaah objektif SOP -> tindakan perbaikan layanan -> apresiasi atas partisipasi publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menyerang balik warga pengkritik merupakan arogansi birokrasi liar yang melanggar hukum.</li><li><strong>C</strong>: Keliru karena kriminalisasi kritik publik melanggar hak asasi partisipasi warga negara dalam birokrasi.</li><li><strong>D</strong>: Keliru karena pengenaan tarif uang jaminan aduan merupakan pungutan liar yang membatasi hak masyarakat.</li><li><strong>E</strong>: Keliru karena melibatkan calo dalam penanganan komplain mencederai integritas institusi pemerintahan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 37", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah program edukasi internal pencegahan gaya hidup hedonisme di lingkungan satuan kerja yang selaras dengan mandat kode etik integritas!", "options": ["Mewajibkan pegawai mengenakan perhiasan berlian tiruan saat menghadiri apel bendera rutin setiap senin pagi.", "Menyelenggarakan lomba pamer mobil sport termahal antarpegawai di halaman depan kantor dinas pelayanan publik.", "Melarang seluruh staf memiliki tabungan perbankan dan mewajibkan konsumsi makanan cepat saji setiap hari kerja.", "Sosialisasi kesederhanaan hidup, teladan pimpinan, panduan bijak medsos, dan pengawasan profil kekayaan LHKPN.", "Menyita seluruh pakaian bermerek milik keluarga pegawai untuk dibakar di depan pintu gerbang utama kantor."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 37", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 37</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Integritas melarang gaya hidup hedonisme sebagai bentuk empati kepada masyarakat dan sesama pegawai; membutuhkan pembudayaan kesederhanaan, keteladanan pimpinan, dan pelaporan LHKPN.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penanggulangan perilaku hedonisme memerlukan intervensi menyeluruh yang memadukan pembinaan moral, pengawasan administratif, dan keteladanan nyata dari para pejabat pimpinan. Program terpadu yang memadukan kampanye kesederhanaan sebagai kehormatan korps, keteladanan gaya hidup hemat dari pimpinan puncak, edukasi etika digital dalam bermedia sosial, serta validasi kepatuhan pelaporan harta kekayaan (LHKPN/LHKASN) akan membentuk ekosistem budaya kerja yang sehat dan berempati pada rakyat. Sintesis program komprehensif pada opsi D secara tepat mengoperasionalkan mandat larangan hedonisme PMK 190/2018 menjadi aksi nyata institusi.</p><p>Jawaban yang sesuai adalah <strong>D. Sosialisasi kesederhanaan hidup, teladan pimpinan, panduan bijak medsos, dan pengawasan profil kekayaan LHKPN.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena mempromosikan perhiasan mencerminkan obsesi visual kemewahan yang bertolak belakang.</li><li><strong>B</strong>: Keliru karena perlombaan kendaraan mewah memicu kecemburuan sosial dan menabrak etika integritas.</li><li><strong>C</strong>: Keliru karena pelarangan tabungan perbankan melanggar hak pengelolaan keuangan keluarga yang sah.</li><li><strong>E</strong>: Keliru karena pembakaran pakaian pribadi keluarga melanggar hukum perdata dan merusak harta benda sah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 37.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Aplikasi", "question": "Ketika rapat koordinasi pembahasan draf perbendaharaan sedang berlangsung alot di ruang sidang, waktu salat fardu telah tiba. Berdasarkan kode etik nilai sinergi, tindakan pemimpin rapat yang paling tepat adalah...", "options": ["Melanjutkan rapat tanpa henti hingga larut malam demi menguji ketahanan fisik dan dedikasi spiritual bawahan.", "Melarang seluruh peserta meninggalkan ruangan dan mengancam pemotongan tunjangan kinerja bagi yang protes.", "Menyuruh peserta rapat melakukan ibadah di bawah meja kerja masing-masing tanpa menghentikan pemaparan draf.", "Menskors rapat sementara untuk memberikan kesempatan bagi pegawai menunaikan ibadah sesuai ketentuan etika.", "Membatalkan seluruh hasil kesepakatan rapat kerja karena waktu pelaksanaan bertabrakan dengan waktu ibadah."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Sinergi mewajibkan pegawai: memberikan kesempatan untuk menunaikan ibadah ketika rapat kerja atau tugas kedinasan sedang berlangsung.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penghormatan terhadap hak spiritual aparatur untuk menunaikan ibadah tepat waktu merupakan wujud kepekaan moral dan kepedulian humanis yang merekatkan sinergi antar-insan kementerian. Menskors sementara agenda rapat kedinasan memberi ruang kesegaran rohani bagi para pegawai tanpa mengorbankan kualitas substansi pembahasan kinerja yang sedang dibahas bersama. Butir ketentuan kode etik sinergi secara eksplisit memerintahkan pimpinan dan rekan kerja memberikan kesempatan beribadah ketika rapat kedinasan berlangsung. Oleh sebab itu, tindakan menskors rapat pada opsi D merupakan aplikasi etika sinergi yang paling tepat dan bermartabat.</p><p>Jawaban yang sesuai adalah <strong>D. Menskors rapat sementara untuk memberikan kesempatan bagi pegawai menunaikan ibadah sesuai ketentuan etika.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena memaksakan rapat tanpa henti melanggar hak ibadah dan menurunkan fokus konsentrasi.</li><li><strong>B</strong>: Keliru karena ancaman pemotongan tunjangan atas pelaksanaan ibadah merupakan kesewenang-wenangan.</li><li><strong>C</strong>: Keliru karena membiarkan ibadah di bawah meja kerja mencederai kesucian dan kekhusyukan ritual agama.</li><li><strong>E</strong>: Keliru karena penundaan waktu sementara tidak perlu direspons dengan pembatalan seluruh hasil rapat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Analitis", "question": "Materi mencantumkan larangan bagi pegawai untuk tidak bertato di bagian tubuh yang terbuka. Bagaimanakah analisis logis mengenai keterkaitan larangan tato terbuka dengan etika penampilan aparatur sipil negara?", "options": ["Larangan bertato bertujuan membatasi hak pegawai dalam menjalani pengobatan medis bedah plastik di klinik resmi.", "Tato di bagian terbuka dinilai berpotensi menurunkan citra formal, wibawa kelembagaan, dan kenyamanan publik.", "Kementerian Keuangan mewajibkan seluruh aparatur menghapus seluruh tanda lahir alami sejak masa sekolah.", "Tato di bagian tubuh terbuka dilarang karena tinta pewarna dapat mengotori lembaran berkas arsip resmi dinas.", "Larangan bertato diterapkan agar seluruh pegawai dapat menghemat anggaran perawatan tubuh bulanan keluarga."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode etik penampilan melarang pegawai bertato di bagian tubuh yang terbuka guna menjaga standar kesopanan, citra aparatur, dan wibawa kehormatan institusi kementerian di hadapan publik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Aparatur sipil negara merupakan representasi langsung dari kewibawaan negara yang bertugas melayani seluruh lapisan masyarakat majemuk dengan latar belakang budaya yang beragam. Penampilan tubuh yang dihiasi rajah tato di area terbuka (seperti wajah, leher, atau lengan depan) dapat memicu persepsi negatif dan rasa canggung bagi sebagian pemangku kepentingan dalam interaksi pelayanan kedinasan. Regulasi kerapian dan etika penampilan kementerian secara tegas menetapkan larangan bertato di bagian tubuh terbuka demi memelihara marwah dan citra formal aparatur pemerintah. Oleh karena itu, opsi B menjelaskan landasan sosiologis penjagaan wibawa publik secara paling akurat.</p><p>Jawaban yang sesuai adalah <strong>B. Tato di bagian terbuka dinilai berpotensi menurunkan citra formal, wibawa kelembagaan, dan kenyamanan publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena larangan tato tidak berkaitan dengan tindakan medis bedah rekonstruksi kesehatan.</li><li><strong>C</strong>: Keliru karena tanda lahir alami bukanlah tato buatan dan tidak pernah dilarang oleh aturan kedinasan.</li><li><strong>D</strong>: Keliru karena tinta tato yang telah meresap pada lapisan kulit tidak akan melunturi dokumen dinas.</li><li><strong>E</strong>: Keliru karena rasionalitas aturan berfokus pada etika kepantasan visual, bukan penghematan privat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Evaluatif", "question": "Seorang staf pelaksana menyebarkan pesan berantai melalui grup komunikasi pegawai yang berisi tuduhan palsu bahwa unit kerja lain memanipulasi data penerimaan negara. Mengapa tindakan staf tersebut KELIRU?", "options": ["Tindakan staf sangat tepat karena fitnah terbukti mempercepat koordinasi penyelesaian masalah perbendaharaan.", "Tindakan staf sangat bijak karena berita bohong merupakan sarana paling efektif melatih daya kritis pimpinan.", "Tindakan staf dapat dibenarkan sepanjang pesan tersebut dibubuhi kata peringatan agar pembaca berhati-hati.", "Tindakan staf merupakan inovasi komunikasi modern yang sah untuk menguji kekompakan korps aparatur negara dinas.", "Tindakan staf keliru karena menyebarkan informasi tak terbukti yang menimbulkan rasa kebencian dan permusuhan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Sinergi melarang keras menyebarkan informasi yang tidak dapat dibuktikan kebenarannya, menimbulkan rasa kebencian dan/atau permusuhan antarsesama.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penyebaran desas-desus yang tidak terverifikasi (hoaks) antarunit kerja meracuni iklim kerja, menghancurkan rasa saling percaya, dan menyulut konflik horizontal yang melumpuhkan sinergi institusi. Memfitnah rekan kerja atau satuan kerja lain tanpa bukti kebenaran merupakan pelanggaran berat terhadap etika komunikasi dan asas tabayun (verifikasi fakta) dalam birokrasi pemerintahan. Ketentuan kode etik nilai sinergi secara kategoris melarang penyebaran informasi yang tidak dapat dibuktikan kebenarannya serta memicu permusuhan. Maka dari itu, evaluasi pada opsi E membuktikan secara tepat bahwa perbuatan tersebut adalah pelanggaran kode etik yang merusak tatanan organisasi.</p><p>Jawaban yang sesuai adalah <strong>E. Tindakan staf keliru karena menyebarkan informasi tak terbukti yang menimbulkan rasa kebencian dan permusuhan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena fitnah dan tuduhan palsu justru merusak tatanan koordinasi kerja dan memicu konflik.</li><li><strong>B</strong>: Keliru karena berita bohong bukanlah instrumen pengasah nalar kritis melainkan racun komunikasi publik.</li><li><strong>C</strong>: Keliru karena penambahan kata peringatan tidak menghapus unsur perbuatan menyebarkan konten palsu.</li><li><strong>D</strong>: Keliru karena inovasi aparatur diarahkan pada perbaikan kinerja, bukan penyebaran permusuhan internal.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf kantor pelayanan hendak menerima kunjungan kerabat keluarga yang datang dari luar kota untuk keperluan urusan keluarga mendesak. Berdasarkan kode etik nilai pelayanan, tata cara yang wajib dipatuhi staf tersebut adalah...", "options": ["Menerima tamu di luar jam kerja atau pada jam kerja dengan seizin atasan dan tidak mengganggu layanan dinas.", "Mengajak seluruh anggota keluarga masuk ke ruang brankas arsip rahasia agar leluasa bercakap-cakap santai.", "Menutup loket pelayanan publik selama tiga jam kerja penuh demi menemani keluarga berbelanja di pasar swalayan.", "Meminta rekan kerja menggantikan seluruh tugas pokoknya tanpa melapor atau meminta izin resmi kepada atasan.", "Menggunakan kendaraan dinas operasional kantor untuk mengantar kerabat berwisata keliling kota selama jam dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Pelayanan mengatur bahwa pegawai menerima pihak lain yang tidak terkait dengan pekerjaan di luar jam kerja atau pada jam kerja dengan seizin atasan dan/atau sepanjang tidak mengganggu pekerjaan atau layanan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengaturan penerimaan tamu pribadi selama hari kerja bertujuan menjaga agar waktu kerja kedinasan tetap dimanfaatkan secara optimal bagi pemenuhan hak pelayanan publik. Memberitahukan dan meminta izin kepada atasan langsung menjamin adanya akuntabilitas kehadiran pegawai serta mencegah terganggunya antrean masyarakat di loket pelayanan. Ketentuan rincian kode etik nilai pelayanan secara gamblang memperbolehkan penerimaan pihak non-kedinasan hanya di luar jam dinas atau dengan izin atasan tanpa mengganggu pekerjaan. Dengan demikian, kepatuhan prosedur pada opsi A merupakan penerapan aturan yang paling tepat dan profesional.</p><p>Jawaban yang sesuai adalah <strong>A. Menerima tamu di luar jam kerja atau pada jam kerja dengan seizin atasan dan tidak mengganggu layanan dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena membawa pihak luar ke ruang arsip rahasia melanggar prosedur keamanan data dan fisik kantor.</li><li><strong>C</strong>: Keliru karena penutupan loket sepihak demi urusan pribadi menelantarkan hak warga pengguna layanan.</li><li><strong>D</strong>: Keliru karena pelimpahan tugas kepada rekan tanpa izin atasan melanggar tata tertib pembagian kerja.</li><li><strong>E</strong>: Keliru karena pemanfaatan mobil dinas kantor untuk rekreasi pribadi merupakan penyalahgunaan fasilitas negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Analitis", "question": "Kode etik nilai sinergi mewajibkan pegawai menghormati perbedaan ras, suku, agama, jenis kelamin, serta kondisi kecacatan (disabilitas). Mengapa penegakan prinsip inklusivitas tersebut menjadi fondasi utama sinergi kementerian?", "options": ["Agar kementerian dapat membatasi penerimaan pegawai baru hanya dari kelompok etnis mayoritas di ibu kota.", "Agar kementerian dapat membubarkan seluruh organisasi keagamaan resmi yang telah berbadan hukum sah negara.", "Karena pengakuan atas kesetaraan martabat memupuk rasa saling percaya dan memberdayakan seluruh potensi SDM.", "Karena kementerian berencana menghapus kewajiban kompetensi teknis dalam penempatan jabatan struktural kantor.", "Agar pegawai penyandang disabilitas dibebaskan secara permanen dari seluruh bentuk penilaian kinerja dinas."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Sinergi mewajibkan: mengakui persamaan derajat, hak, dan kewajiban setiap manusia, mengembangkan tenggang rasa, serta menghormati perbedaan latar belakang dan kondisi kecacatan demi keutuhan bangsa.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kolaborasi produktif hanya dapat tumbuh subur di dalam ekosistem kerja yang bebas dari prasangka diskriminatif, stereotip suku, prasangka gender, dan perlakuan merendahkan terhadap penyandang disabilitas. Ketika setiap aparatur merasa diakui harkat kemanusiaannya dan dihargai kontribusinya secara adil, tercipta rasa memiliki (sense of belonging) yang kuat yang menyatukan beragam kompetensi menjadi energi sinergi yang dahsyat bagi negara. Penegasan butir kode etik sinergi menempatkan penghargaan atas perbedaan dan persamaan hak asasi sebagai pilar keutuhan korps. Oleh karenanya, opsi C memberikan analisis mendalam mengenai penguatan potensi SDM melalui kesetaraan martabat.</p><p>Jawaban yang sesuai adalah <strong>C. Karena pengakuan atas kesetaraan martabat memupuk rasa saling percaya dan memberdayakan seluruh potensi SDM.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena diskriminasi etnis bertentangan secara frontal dengan asas kebinekaan dan keadilan hukum.</li><li><strong>B</strong>: Keliru karena kode etik menjunjung tinggi kebebasan beragama yang dijamin oleh konstitusi kenegaraan.</li><li><strong>D</strong>: Keliru karena meritokrasi kompetensi teknis tetap menjadi pilar utama pembinaan karier aparatur.</li><li><strong>E</strong>: Keliru karena pegawai penyandang disabilitas tetap diberdayakan dan dinilai kinerjanya secara adil pantas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Evaluatif", "question": "Seorang petugas loket pelayanan bea cukai mendahulukan penyelesaian dokumen importir yang berasal dari daerah asalnya sendiri, sementara importir lain dibiarkan menunggu lama. Mengapa tindakan petugas loket tersebut KELIRU?", "options": ["Tindakan petugas sangat mulia karena tolong-menolong sesama kedaerahan menduduki derajat di atas aturan menteri.", "Tindakan petugas keliru karena melanggar kewajiban tidak membeda-bedakan dan bersikap adil dalam pelayanan.", "Tindakan petugas dapat dibenarkan sepanjang importir daerah asal bersedia membayar biaya loket sukarela tunai.", "Tindakan petugas sangat bijak dalam rangka mempercepat penyelesaian target antrean pelayanan harian kantor.", "Tindakan petugas mencerminkan kearifan lokal primordial yang wajib dilestarikan dalam birokrasi pemerintahan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Pelayanan butir keenam menegaskan kewajiban pegawai untuk: tidak membeda-bedakan dan bersikap adil dalam memberikan pelayanan kepada seluruh pemangku kepentingan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pelayanan publik diselenggarakan dengan memegang teguh asas non-diskriminasi, kepastian hukum, dan persamaan perlakuan bagi setiap warga negara tanpa memandang asal daerah, suku, maupun hubungan personal. Memberikan perlakuan istimewa kepada kelompok kedaerahan tertentu (primordialisme sempit) merupakan pelanggaran berat terhadap etika pelayanan yang merusak prinsip keadilan dan profesionalisme aparatur. Ketentuan kode etik nilai pelayanan secara mutlak melarang pembedaan perlakuan dan mewajibkan aparatur bersikap adil kepada seluruh pengguna layanan. Maka dari itu, penilaian pada opsi B membuktikan secara tegas bahwa diskriminasi tersebut adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>B. Tindakan petugas keliru karena melanggar kewajiban tidak membeda-bedakan dan bersikap adil dalam pelayanan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena solidaritas etnis primordial tidak boleh melanggar hukum keadilan pelayanan publik.</li><li><strong>C</strong>: Keliru karena penerimaan biaya sukarela di loket merupakan tindak pidana korupsi pungutan liar.</li><li><strong>D</strong>: Keliru karena diskriminasi antrean merugikan pengguna layanan lain dan merusak kepastian waktu.</li><li><strong>E</strong>: Keliru karena birokrasi negara modern berlandaskan meritokrasi dan keadilan hukum universal, bukan primordialisme.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan perilaku yang mencerminkan pemenuhan Kode Etik dan Kode Perilaku Nilai Sinergi menurut PMK Nomor 190/PMK.01/2018?", "options": ["Bersikap kooperatif dengan unit kerja lain yang terkait dalam pelaksanaan tugas guna mencapai target instansi dinas.", "Menjaga komitmen terhadap keputusan bersama dan konsisten dalam pelaksanaan implementasi di lingkungan kerja.", "Bersedia untuk berbagi solusi, informasi, dan data sesuai kewenangan untuk menyelesaikan masalah kedinasan.", "Menyembunyikan informasi penting penugasan agar unit kerja mitra mengalami kegagalan kinerja di hadapan menteri.", "Menghargai masukan, pendapat, dan gagasan orang lain serta mengembangkan sikap tenggang rasa antarsesama."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Sinergi meliputi: akui persamaan derajat, hormati perbedaan, jaga persatuan, kooperatif lintas unit, hargai masukan, komitmen keputusan bersama, berbagi solusi/data, beri izin ibadah, izin atasan, tidak sebar hoax/kebencian.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menyembunyikan informasi kedinasan dengan maksud menjatuhkan kinerja unit kerja lain merupakan cerminan ego sektoral toksik dan persaingan tidak sehat yang menghancurkan sendi-sendi keutuhan organisasi. Sikap sabotase terselubung ini bertolak belakang secara diametral dengan semangat sinergi yang menuntut keterbukaan komunikasi dan kesediaan berbagi solusi demi kepentingan kebaikan bangsa. Butir-butir kode etik sinergi secara konsisten mendorong kerja sama kooperatif dan pertukaran data resmi yang solutif. Oleh sebab itu, tindakan menyembunyikan data pada opsi D jelas merupakan perbuatan tercela yang bukan merupakan cerminan nilai sinergi.</p><p>Jawaban yang sesuai adalah <strong>D. Menyembunyikan informasi penting penugasan agar unit kerja mitra mengalami kegagalan kinerja di hadapan menteri.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Cerminan sinergi sah mengenai sikap kooperatif lintas unit yang tercantum secara eksplisit dalam aturan.</li><li><strong>B</strong>: Cerminan sinergi sah mengenai komitmen menjaga dan mengeksekusi keputusan bersama dalam tugas.</li><li><strong>C</strong>: Cerminan sinergi sah mengenai kesediaan berbagi solusi dan informasi sesuai batas wewenang dinas.</li><li><strong>E</strong>: Cerminan sinergi sah mengenai keterbukaan menghargai masukan dan memelihara tenggang rasa korps.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Aplikasi", "question": "Sebuah satuan kerja perbendaharaan daerah membutuhkan data rekonsiliasi transfer kas dari kantor pajak setempat guna menuntaskan laporan realisasi anggaran. Bentuk penerapan kode etik nilai sinergi yang paling tepat dari pihak kantor pajak adalah...", "options": ["Menolak memberikan data sebelum kantor perbendaharaan membayar komisi jasa penarikan basis data perpajakan.", "Menghapus seluruh berkas rekonsiliasi kas agar kantor perbendaharaan mendapat teguran keras dari menteri pusat.", "Memberikan data palsu yang belum diuji kebenarannya demi mempercepat penutupan berkas permintaan kerja harian.", "Membiarkan surat permohonan data tanpa tindak lanjut selama berbulan-bulan tanpa adanya kejelasan informasi.", "Bersedia berbagi data rekonsiliasi yang akurat sesuai kewenangan kedinasan guna menuntaskan masalah laporan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Sinergi butir ketujuh mewajibkan pegawai: bersedia untuk berbagi solusi, informasi, dan/atau data sesuai kewenangan untuk menyelesaikan masalah yang terkait dengan pekerjaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pertukaran data yang valid dan cepat antarunit kerja merupakan kunci utama dalam mewujudkan penyusunan laporan keuangan pemerintah yang andal, akuntabel, dan transparan. Sikap kooperatif dalam berbagi informasi kedinasan yang sah memangkas hambatan birokrasi serta mempercepat penyelesaian kendala teknis pengelolaan fiskal negara. Panduan kode etik sinergi butir ketujuh mewajibkan setiap pegawai untuk bersedia berbagi solusi dan data sesuai batas kewenangan demi kepentingan penyelesaian tugas organisasi. Maka dari itu, penyediaan data rekonsiliasi yang akurat pada opsi E adalah perwujudan sinergi yang paling tepat dan profesional.</p><p>Jawaban yang sesuai adalah <strong>E. Bersedia berbagi data rekonsiliasi yang akurat sesuai kewenangan kedinasan guna menuntaskan masalah laporan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pertukaran data antarunit resmi negara bebas biaya dan pungutan komisi apa pun.</li><li><strong>B</strong>: Keliru karena pemusnahan berkas rekonsiliasi merupakan sabotase kejahatan jabatan yang merugikan negara.</li><li><strong>C</strong>: Keliru karena penyerahan data palsu melanggar asas akurasi profesionalisme dan memalsukan laporan negara.</li><li><strong>D</strong>: Keliru karena membiarkan permohonan data tanpa kejelasan mencerminkan inersia birokrasi yang kontraproduktif.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka tata kelola loket pelayanan publik terpadu yang menjamin keadilan akses bagi kelompok rentan dan penyandang disabilitas sesuai nilai pelayanan!", "options": ["Membangun loket pelayanan khusus di lantai empat gedung tanpa lift agar kelompok rentan berolahraga fisik.", "Mewajibkan warga disabilitas membawa surat rekomendasi politik sebelum diizinkan memasuki lobi kantor dinas.", "Menyediakan jalur landai, loket prioritas, petugas pemandu khusus, serta modul informasi braille dan visual.", "Mengalihkan seluruh permohonan kelompok rentan kepada calo jasa perantara swasta berbayar di luar gedung kantor.", "Menolak permohonan layanan kelompok rentan karena dianggap memperlambat catatan waktu rata-rata loket kantor."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Pelayanan mewajibkan pelayanan yang ramah, santun, adil, peduli, dan tidak membeda-bedakan, termasuk memperhatikan kebutuhan kelompok rentan dan disabilitas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keadilan substantif dalam pelayanan publik menuntut adanya tindakan afirmatif (affirmative action) berupa penyediaan sarana dan prasarana yang memudahkan kelompok rentan mengakses hak-hak administratifnya secara setara. Fasilitas ramah disabilitas—seperti jalur pemandu (guiding block), ramp landai, loket khusus tanpa tangga, penerjemah bahasa isyarat, serta informasi braille—menghapus diskriminasi fisik dan membuktikan ketulusan aparatur dalam melayani sepenuh hati. Rumusan kode etik pelayanan secara tegas melarang diskriminasi dan mengamanatkan perlakuan adil kepada seluruh lapisan masyarakat. Oleh sebab itu, rancangan aksesibilitas terpadu pada opsi C merupakan sintesis keadilan layanan yang paling paripurna.</p><p>Jawaban yang sesuai adalah <strong>C. Menyediakan jalur landai, loket prioritas, petugas pemandu khusus, serta modul informasi braille dan visual.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menempatkan loket di lantai tinggi tanpa lift adalah bentuk diskriminasi fisik kejam.</li><li><strong>B</strong>: Keliru karena persyaratan surat rekomendasi partai politik melanggar asas kemudahan akses publik.</li><li><strong>D</strong>: Keliru karena melempar pengguna layanan kepada calo komersial mencederai integritas institusi negara.</li><li><strong>E</strong>: Keliru karena penolakan kelompok rentan demi mengejar metrik waktu merupakan pelanggaran hak asasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 38", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah mekanisme penegakan komitmen terhadap keputusan bersama dalam tim lintas unit agar implementasi kebijakan kementerian tidak mengalami deviasi!", "options": ["Penyusunan matriks aksi bersama, penetapan penanggung jawab, jadwal terukur, dan evaluasi berkala lintas unit.", "Memberikan kebebasan kepada setiap unit untuk mengubah keputusan rapat secara sepihak tanpa perlu berkoordinasi.", "Menyembunyikan risalah rapat kesepakatan dari pimpinan satker agar tidak ada pihak yang dapat menagih komitmen.", "Menjatuhkan sanksi kurungan fisik di ruang bawah tanah kantor kepada perwakilan unit yang terlambat lima menit.", "Menyerahkan seluruh pelaksanaan keputusan bersama kepada pihak ketiga swasta tanpa adanya pengawasan internal."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 38", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 38</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Sinergi butir keenam mewajibkan pegawai: menjaga komitmen terhadap keputusan bersama dan implementasinya secara disiplin dan akuntabel.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Sebuah kesepakatan bersama dalam birokrasi pemerintahan akan menjadi dokumen mati tanpa adanya instrumen operasionalisasi yang mengikat seluruh pihak untuk melaksanakannya secara konsisten. Pembentukan matriks rencana aksi yang transparan, penetapan pembagian peran (pic) yang jelas, indikator keluaran yang terukur, serta mekanisme pemantauan berkala menjamin setiap butir keputusan bersama dapat dieksekusi tanpa deviasi. Butir keenam kode etik sinergi menempatkan komitmen terhadap keputusan bersama sebagai fondasi integritas tim kerja kementerian. Maka dari itu, sintesis kerangka kerja manajerial pada opsi A adalah model tata kelola eksekusi yang paling efektif.</p><p>Jawaban yang sesuai adalah <strong>A. Penyusunan matriks aksi bersama, penetapan penanggung jawab, jadwal terukur, dan evaluasi berkala lintas unit.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena pengubahan sepihak merusak kesepakatan kolektif dan menciptakan kekacauan operasional.</li><li><strong>C</strong>: Keliru karena penyembunyian risalah keputusan melanggar prinsip transparansi tata kelola birokrasi.</li><li><strong>D</strong>: Keliru karena hukuman kurungan fisik ilegal melanggar hak asasi dan keluar dari regulasi disiplin dinas.</li><li><strong>E</strong>: Keliru karena penyerahan wewenang kepada swasta tanpa kontrol mengabaikan mandat akuntabilitas publik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 38.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Analitis", "question": "KMK Nomor 429/KMK.01/2022 membedakan secara tegas antara Sikap Dasar dan Perilaku Efektif bagi pegawai. Manakah di antara pernyataan berikut yang secara akurat menganalisis pembedaan karakteristik utama kedua konsep tersebut?", "options": ["Sikap Dasar bersifat dapat diamati secara langsung, sedangkan Perilaku Efektif tersimpan dalam alam bawah sadar.", "Sikap Dasar hanya diwajibkan bagi pejabat eselon satu, sedangkan Perilaku Efektif hanya berlaku untuk staf honorer.", "Sikap Dasar merupakan kecenderungan afektif yang tak tampak langsung, sedangkan Perilaku Efektif adalah gaya kerja teramati.", "Sikap Dasar berfokus pada penguasaan teknologi peladen, sedangkan Perilaku Efektif berfokus pada pakaian seragam dinas.", "Sikap Dasar bersifat sementara selama masa percobaan, sedangkan Perilaku Efektif otomatis gugur setelah lulus CPNS."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sikap Dasar adalah pikiran, perasaan, kecenderungan afektif yang tidak langsung terlihat namun harus dimiliki; Perilaku Efektif adalah sekumpulan perilaku/gaya kerja yang berasal dari Sikap Dasar, bersifat secara langsung terlihat (observable).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Hubungan antara Sikap Dasar dan Perilaku Efektif merupakan manifestasi dari hukum psikologi perilaku organisasi, di mana keyakinan internal (internal mindset) menjadi fondasi penentu tindakan lahiriah yang teramati di lingkungan kerja. Sikap Dasar bersemayam di ranah afektif dan kognitif berupa pola pikir, komitmen batin, serta kecondongan nurani yang tidak tampak langsung di mata publik namun mengarahkan integritas pegawai. Sebaliknya, Perilaku Efektif merupakan kristalisasi gaya kerja konkrit yang dapat diobservasi, diukur kecepatannya, dan dinilai dampaknya terhadap produktivitas birokrasi. Penjelasan materi KMK 429/2022 secara gamblang membedakan sifat laten tak tampak dari Sikap Dasar dengan sifat teramati langsung dari Perilaku Efektif. Oleh sebab itu, opsi C memberikan analisis komparatif yang paling presisi.</p><p>Jawaban yang sesuai adalah <strong>C. Sikap Dasar merupakan kecenderungan afektif yang tak tampak langsung, sedangkan Perilaku Efektif adalah gaya kerja teramati.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena karakteristiknya terbalik; Sikap Dasar yang tidak tampak langsung dan Perilaku Efektif yang teramati.</li><li><strong>B</strong>: Keliru karena kedua konsep budaya mengikat seluruh aparatur kementerian tanpa pembedaan golongan pangkat.</li><li><strong>D</strong>: Keliru karena kedua konsep berakar pada nilai BerAKHLAK dan Kemenkeu, bukan semata perangkat keras IT.</li><li><strong>E</strong>: Keliru karena pembudayaan nilai bersifat permanen sepanjang masa pengabdian aparatur sipil negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf muda pada seksi pengelolaan data mengusulkan pembuatan skrip otomasi komputer untuk memangkas waktu penginputan berkas harian dari 4 jam menjadi 15 menit. Berdasarkan kode etik nilai kesempurnaan, respons pimpinan yang paling tepat adalah...", "options": ["Memberikan sanksi teguran tertulis kepada staf karena berani lancang mengubah cara kerja manual tradisi kantor.", "Menghapus akun komputer staf tersebut agar tidak dapat lagi bereksperimen dengan bahasa pemrograman digital.", "Mengancam akan memindahkan staf ke unit terpencil karena ide otomasi dianggap membahayakan posisi pegawai lain kantor.", "Melaporkan staf ke Unit Kepatuhan Internal atas tuduhan merusak keharmonisan prosedur administrasi lama dinas.", "Mendukung dan tidak menghalangi upaya inovasi tersebut sepanjang tidak bertentangan dengan peraturan perundangan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Kesempurnaan mewajibkan: tidak menghalangi kreativitas/gagasan/pendapat yang bernilai tambah bagi kemajuan organisasi; dan tidak menghalangi upaya inovasi yang tidak bertentangan dengan peraturan perundang-undangan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Inovasi digital yang sah dan terbukti memangkas waktu kerja secara signifikan merupakan wujud nyata nilai Kesempurnaan dalam mengejar efisiensi dan efektivitas tata kelola birokrasi modern. Mematikan inisiatif inovasi bawahan mencerminkan kepemimpinan feodal yang kontraproduktif dan melanggar kode perilaku kementerian yang mewajibkan pimpinan memfasilitasi gagasan bernilai tambah. Rumusan kode etik kesempurnaan secara eksplisit memerintahkan agar pimpinan dan rekan kerja tidak menghalangi inovasi dan kreativitas yang bernilai positif bagi kemajuan instansi. Dengan demikian, pemberian dukungan terbuka pada opsi E adalah aplikasi kode etik kesempurnaan yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>E. Mendukung dan tidak menghalangi upaya inovasi tersebut sepanjang tidak bertentangan dengan peraturan perundangan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penjatuhan sanksi atas inovasi efisien membunuh kreativitas dan melanggar kode etik.</li><li><strong>B</strong>: Keliru karena pemblokiran akun komputer staf berprestasi merupakan tindakan represif yang tidak etis.</li><li><strong>C</strong>: Keliru karena ancaman mutasi atas inisiatif efisiensi melanggar prinsip meritokrasi dan pembinaan SDM.</li><li><strong>D</strong>: Keliru karena UKI mengawal integritas dari korupsi, bukan instrumen pemberangus inovasi teknologi positif.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Analitis", "question": "Penerbitan Keputusan Menteri Keuangan Nomor 429/KMK.01/2022 didasarkan pada penyelarasan Core Values ASN BerAKHLAK dan Nilai-Nilai Kementerian Keuangan. Bagaimanakah korelasi strategis penyelarasan kedua kerangka nilai tersebut bagi aparatur fiskal?", "options": ["Penyelarasan tersebut bermakna bahwa seluruh Nilai Kementerian Keuangan dihapus dan digantikan peraturan daerah.", "Penyelarasan tersebut memperkuat standar perilaku ASN nasional sekaligus merawat keunggulan nilai historis Kemenkeu.", "Penyelarasan tersebut bertujuan mempermudah pegawai kementerian untuk berpindah profesi menjadi politisi partai.", "Penyelarasan tersebut membatasi ruang kolaborasi kementerian dengan kementerian koordinator bidang perekonomian.", "Penyelarasan tersebut mewajibkan seluruh instansi kementerian membubarkan sistem akuntansi berbasis akrual negara dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>KMK 429/KMK.01/2022 menyelaraskan Core Values ASN BerAKHLAK dan Nilai-Nilai Kementerian Keuangan guna mendorong terciptanya budaya Kemenkeu Satu yang kolaboratif, produktif, dan inovatif beretika.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Harmonisasi antara nilai BerAKHLAK sebagai standar perilaku ASN berskala nasional dengan Nilai-Nilai Kementerian Keuangan menjamin adanya kesatuan gerak korps birokrasi Republik Indonesia tanpa melunturkan identitas keunggulan budaya fiskal yang telah teruji. Langkah penyelarasan ini memadukan keluhuran nilai kementerian (Integritas, Profesionalisme, Sinergi, Pelayanan, Kesempurnaan) ke dalam matriks kompetensi nasional demi membangun ekosistem Kemenkeu Satu yang adaptif dan berdaya saing global. Dokumen KMK 429/2022 menegaskan bahwa integrasi nilai ini menjadi pedoman pembentukan pola pikir dan kebiasaan kerja baru seluruh jajaran pegawai. Maka dari itu, opsi B menyajikan analisis korelasi strategis penguatan budaya secara paling utuh.</p><p>Jawaban yang sesuai adalah <strong>B. Penyelarasan tersebut memperkuat standar perilaku ASN nasional sekaligus merawat keunggulan nilai historis Kemenkeu.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena Nilai Kemenkeu tidak dihapus melainkan diperkuat dan diselaraskan dengan nilai BerAKHLAK.</li><li><strong>C</strong>: Keliru karena pembudayaan nilai aparatur berfokus pada profesionalisme publik, bukan karier politik praktis.</li><li><strong>D</strong>: Keliru karena penyelarasan budaya justru memperluas jalinan kolaborasi lintas kementerian di Indonesia.</li><li><strong>E</strong>: Keliru karena penguatan budaya etika tidak berkaitan dengan pembubaran standar akuntansi akrual negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Evaluatif", "question": "Seorang kepala seksi melarang bawahannya menyampaikan ide penyempurnaan alur pelayanan daring dalam forum evaluasi berkala dengan alasan staf junior tidak berhak memberi masukan. Mengapa tindakan kepala seksi tersebut KELIRU?", "options": ["Tindakan kepala seksi keliru karena melanggar kode etik untuk tidak menghalangi kreativitas bernilai tambah.", "Tindakan kepala seksi sangat tepat karena staf junior diwajibkan hanya menjalankan instruksi tanpa boleh berpikir.", "Tindakan kepala seksi dapat dibenarkan sepanjang kepala seksi bersangkutan berjanji akan mengambil alih ide junior.", "Tindakan kepala seksi mencerminkan ketertiban birokrasi yang sah dalam menjaga jarak kasta sosial di ruang kantor.", "Tindakan kepala seksi sangat bijaksana demi menghemat waktu rapat agar pegawai dapat segera pulang ke rumah."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Kesempurnaan melarang menghalangi kreativitas/gagasan/pendapat yang bernilai tambah bagi kemajuan organisasi, serta mewajibkan keterbukaan terhadap usulan perbaikan dari seluruh lini.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pemberangusan ide staf bawahan semata-mata karena faktor junioritas membuktikan arogansi birokrasi feodal yang merugikan kepentingan kemajuan organisasi. Inovasi tata kelola sering kali lahir dari staf garis depan yang paling memahami kendala riil di lapangan, sehingga menutup ruang gagasan mereka sama dengan mematikan potensi perbaikan mutu pelayanan publik. Teks kode etik nilai kesempurnaan secara gamblang melarang sikap menghalangi pendapat dan ide kreatif yang memberi nilai tambah bagi instansi. Oleh karena itu, evaluasi pada opsi A secara tepat menegaskan bahwa pembungkaman ide tersebut merupakan pelanggaran terhadap kode perilaku kementerian.</p><p>Jawaban yang sesuai adalah <strong>A. Tindakan kepala seksi keliru karena melanggar kode etik untuk tidak menghalangi kreativitas bernilai tambah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena birokrasi modern menuntut partisipasi nalar aktif dari seluruh aparatur, bukan kepatuhan buta.</li><li><strong>C</strong>: Keliru karena plagiarisme gagasan staf oleh atasan merupakan pelanggaran etika kejujuran intelektual.</li><li><strong>D</strong>: Keliru karena diskriminasi kasta senioritas melanggar prinsip keadilan dan budaya kerja kemitraan setara.</li><li><strong>E</strong>: Keliru karena efisiensi waktu rapat tidak boleh dijadikan alasan menolak perbaikan prosedur layanan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Aplikasi", "question": "Dalam rangka mengimplementasikan butir pertama kode etik kesempurnaan mengenai keimanan dan ketakwaan terhadap Tuhan Yang Maha Esa di lingkungan kerja, tindakan aplikasi yang paling tepat bagi seorang aparatur adalah...", "options": ["Memaksa seluruh rekan kerja yang berbeda keyakinan untuk mengikuti ritual peribadatan agama yang dianutnya.", "Menghakimi status keimanan rekan kerja secara terbuka di media sosial saat terjadi perbedaan pendapat kedinasan.", "Mengabaikan tugas pelayanan kepada masyarakat demi menghabiskan seluruh jam kerja dinas di tempat ibadah kantor.", "Menjadikan nilai-nilai ketuhanan sebagai benteng nurani dalam menolak gratifikasi dan menjaga kejujuran tugas.", "Menggunakan dana kas kecil operasional kantor untuk membiayai perjalanan wisata ziarah kelompok sendiri."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Kode Etik Nilai Kesempurnaan mewajibkan: berupaya menjaga dan melakukan implementasi atas keimanan dan ketakwaan terhadap Tuhan Yang Maha Esa dalam setiap aspek pengabdian kedinasan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penghayatan keimanan dan ketakwaan yang sejati di lingkungan birokrasi pemerintahan tecermin pada integritas moral yang kokoh, rasa takut berbuat curang, serta keikhlasan melayani rakyat demi mencari rida Tuhan YME. Menjadikan nilai religiositas sebagai benteng batin menjauhkan pegawai dari godaan suap, pungutan liar, dan penyalahgunaan wewenang jabatan dalam interaksi pelayanan sehari-hari. Dokumen kode etik menempatkan implementasi keimanan dan ketakwaan sebagai fondasi luhur pembimbing seluruh tindakan kedinasan aparatur negara. Oleh karenanya, penguatan benteng integritas nurani pada opsi D merupakan aplikasi keimanan yang paling tepat dan luhur.</p><p>Jawaban yang sesuai adalah <strong>D. Menjadikan nilai-nilai ketuhanan sebagai benteng nurani dalam menolak gratifikasi dan menjaga kejujuran tugas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pemaksaan keyakinan beragama melanggar hak asasi kemerdekaan beribadah konstitusional.</li><li><strong>B</strong>: Keliru karena mencela keimanan orang lain mencederai toleransi dan merusak etika kesopanan korps.</li><li><strong>C</strong>: Keliru karena menelantarkan tugas dinas demi ibadah pribadi melanggar amanah kewajiban profesionalisme.</li><li><strong>E</strong>: Keliru karena pemanfaatan uang kas kantor untuk ziarah privat merupakan tindak pidana korupsi penyelewengan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Analitis", "question": "KMK Nomor 429/KMK.01/2022 mengarahkan terwujudnya budaya 'Kementerian Keuangan Satu' (Kemenkeu Satu). Bagaimanakah analisis esensi Kemenkeu Satu dalam meruntuhkan ego sektoral antar-unit eselon satu?", "options": ["Kemenkeu Satu mewajibkan penggabungan seluruh gedung kantor pelayanan menjadi satu gedung raksasa tunggal instansi.", "Kemenkeu Satu menyatukan visi, data, dan gerak langkah lintas unit guna mengeliminasi sekat silo birokrasi.", "Kemenkeu Satu mengharuskan seluruh pegawai kementerian memiliki nama keluarga dan marga yang seragam sama.", "Kemenkeu Satu dirancang untuk membubarkan fungsi kepabeanan dan menggabungkannya ke dinas pasar daerah.", "Kemenkeu Satu membatasi pertukaran informasi keuangan hanya melalui surat kabar harian umum nasional cetak."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya Kementerian Keuangan Satu (Kemenkeu Satu) ditujukan untuk memberikan pedoman dan mendorong pola pikir, sikap, perilaku, serta kebiasaan kolaboratif, produktif, dan inovatif lintas unit dengan menjunjung etika dan integritas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Budaya Kemenkeu Satu dirumuskan sebagai antitesis terhadap mentalitas silo (silo mentality) yang selama bertahun-tahun mengotak-ngotakkan unit kerja eselon satu dalam batas kewenangan yang sempit dan saling bersaing. Melalui doktrin Kemenkeu Satu, seluruh aparatur disadarkan bahwa mereka adalah satu kesatuan keluarga besar pengelola fiskal negara yang mengabdi pada tujuan akhir yang sama: menjaga kedaulatan dan kemakmuran ekonomi Indonesia. Landasan KMK 429/2022 menegaskan bahwa budaya Kemenkeu Satu menuntut ekosistem kerja yang kolaboratif, terbuka, dan berbagi sumber daya untuk hasil terbaik. Oleh sebab itu, opsi B menyajikan analisis esensi peruntuhan sekat silo secara paling komprehensif.</p><p>Jawaban yang sesuai adalah <strong>B. Kemenkeu Satu menyatukan visi, data, dan gerak langkah lintas unit guna mengeliminasi sekat silo birokrasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena Kemenkeu Satu berakar pada kesatuan nilai dan koordinasi sistem, bukan penyatuan fisik gedung.</li><li><strong>C</strong>: Keliru karena penyatuan budaya tidak berkaitan dengan nama marga atau latar belakang biologis pegawai.</li><li><strong>D</strong>: Keliru karena fungsi kepabeanan tetap berjalan kokoh di bawah mandat undang-undang kementerian keuangan.</li><li><strong>E</strong>: Keliru karena modernisasi Kemenkeu Satu justru mendorong integrasi pertukaran data melalui platform digital.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja berambisi mengejar target penerimaan instansi setinggi-tingginya sehingga membiarkan pegawai melakukan intimidasi dan pemerasan kepada pelaku usaha wajib pajak. Mengapa pendekatan satuan kerja tersebut KELIRU?", "options": ["Pendekatan satker sangat tepat karena pencapaian target penerimaan kas negara berada di atas seluruh norma etika.", "Pendekatan satker sangat bijak karena intimidasi merupakan teknik negosiasi bisnis paling ilmiah di era modern.", "Pendekatan satker dapat dibenarkan sepanjang uang hasil pemerasan disetorkan langsung ke rekening kas negara.", "Pendekatan satker keliru karena penguatan budaya mewajibkan ekosistem produktif tetap menjunjung tinggi etika.", "Pendekatan satker merupakan bentuk loyalitas tanpa batas aparatur sipil negara yang patut diapresiasi pimpinan."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>KMK 429/KMK.01/2022 menegaskan bahwa tujuan penguatan budaya adalah mendorong terciptanya ekosistem dan lingkungan kerja yang kolaboratif, produktif, dan inovatif dengan tetap menjunjung tinggi etika dan integritas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Produktivitas dan pencapaian target kinerja institusi pemerintahan tidak pernah boleh diraih dengan cara-cara kotor yang menghalalkan segala cara dan menabrak norma hukum serta etika kemanusiaan. Praktik pemerasan dan intimidasi kepada masyarakat pembayar pajak merusak iklim investasi nasional, mencederai rasa keadilan, serta menghancurkan legitimasi moral negara. Regulasi penguatan budaya kementerian secara tegas menetapkan batasan mutlak bahwa pencapaian kinerja produktif harus selalu berada dalam koridor penegakan etika dan integritas luhur. Oleh karenanya, evaluasi pada opsi D secara tepat membuktikan bahwa mengorbankan etika demi target adalah kekeliruan moral yang berat.</p><p>Jawaban yang sesuai adalah <strong>D. Pendekatan satker keliru karena penguatan budaya mewajibkan ekosistem produktif tetap menjunjung tinggi etika.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena target keuangan negara tidak melegitimasi pelanggaran hukum pidana dan kezaliman jabatan.</li><li><strong>B</strong>: Keliru karena intimidasi birokrasi adalah tindak pidana pemerasan, bukan metodologi bisnis ilmiah.</li><li><strong>C</strong>: Keliru karena uang hasil pemerasan tetap berstatus uang haram kejahatan jabatan yang merusak sistem.</li><li><strong>E</strong>: Keliru karena loyalitas buta aparatur yang melanggar hukum merupakan bentuk persekongkolan kejahatan dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan tujuan utama dari terbitnya Keputusan Menteri Keuangan Nomor 429/KMK.01/2022 tentang Penguatan Budaya di lingkungan Kementerian Keuangan?", "options": ["Memberikan pedoman dan mendorong terciptanya pola pikir, sikap, dan kebiasaan dalam budaya Kemenkeu Satu.", "Mendorong terciptanya ekosistem kerja yang kolaboratif, produktif, dan inovatif dengan menjunjung integritas.", "Memberikan kewenangan kepada pimpinan unit kerja untuk memungut pajak daerah tanpa dasar undang-undang sah.", "Menyelaraskan perilaku kerja pegawai dengan nilai-nilai luhur Core Values Aparatur Sipil Negara BerAKHLAK.", "Mendukung efektivitas dan produktivitas pegawai dalam tatanan sistem kerja baru yang adaptif dan dinamis."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tujuan KMK 429/2022: (1) pedoman pola pikir/kebiasaan budaya Kemenkeu Satu selaras BerAKHLAK dan Nilai Kemenkeu; (2) dorong ekosistem kolaboratif, produktif, inovatif dengan tetap junjung tinggi etika dan integritas; (3) dukung sistem kerja baru.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keputusan Menteri Keuangan Nomor 429/KMK.01/2022 berfokus pada ranah tata kelola budaya organisasi, transformasi pola pikir pegawai, dan internalisasi kode perilaku, bukan mengenai penetapan wewenang pemungutan pajak daerah. Wewenang perpajakan diatur secara ketat dalam undang-undang perpajakan nasional dan undang-undang hubungan keuangan pusat dan daerah. Teks KMK 429/2022 secara presisi menggariskan tujuan pembudayaan sikap dasar dan perilaku efektif guna memperkuat ekosistem kolaboratif beretika. Maka dari itu, pemberian kewenangan pemungutan pajak daerah pada opsi C jelas bukan merupakan tujuan dari penerbitan regulasi penguatan budaya tersebut.</p><p>Jawaban yang sesuai adalah <strong>C. Memberikan kewenangan kepada pimpinan unit kerja untuk memungut pajak daerah tanpa dasar undang-undang sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Tujuan sah mengenai pedoman pembentukan pola pikir budaya Kemenkeu Satu selaras BerAKHLAK.</li><li><strong>B</strong>: Tujuan sah mengenai penciptaan lingkungan kerja kolaboratif, produktif, dan inovatif berintegritas.</li><li><strong>D</strong>: Tujuan sah mengenai penyelarasan perilaku kerja pegawai dengan Core Values ASN BerAKHLAK.</li><li><strong>E</strong>: Tujuan sah mengenai dukungan terhadap efektivitas sistem kerja baru yang adaptif dalam birokrasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka program kerja penguatan budaya Kemenkeu Satu pada tingkat kantor wilayah yang mengawinkan kolaborasi lintas eselon dengan inovasi pelayanan publik!", "options": ["Forum sinergi bersama, integrasi loket layanan terpadu, klinik konsultasi bersama, dan kompetisi inovasi tim gabungan.", "Mewajibkan setiap unit kerja memasang pagar pembatas kawat berduri guna memisahkan ruangan antardirektorat jenderal.", "Melarang seluruh staf saling menyapa saat berpapasan di lorong kantor dinas guna menjaga kerahasiaan tugas unit kerja.", "Menetapkan aturan bahwa unit pajak tidak boleh berkomunikasi dengan unit bea cukai maupun perbendaharaan daerah dinas.", "Menghentikan seluruh layanan konsultasi masyarakat dan menggantinya dengan rekaman suara mesin penjawab telepon."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Budaya Kemenkeu Satu menuntut ekosistem kerja yang kolaboratif, produktif, dan inovatif dengan menjunjung tinggi etika; membutuhkan program nyata yang mengintegrasikan layanan dan sinergi lintas unit eselon.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penguatan budaya Kemenkeu Satu memerlukan wahana konkret yang memfasilitasi bertemunya beragam fungsi fiskal di tingkat wilayah dalam satu ekosistem pelayanan terpadu bagi masyarakat. Program integrasi yang menyatukan forum koordinasi rutin pimpinan unit, penggabungan gerai layanan perpajakan, kepabeanan, dan perbendaharaan (joint office), serta perlombaan inovasi tim gabungan lintas unit berhasil memecah sekat birokrasi sekaligus meningkatkan kepuasan pengguna layanan secara drastis. Sintesis aksi terpadu pada opsi A secara tepat merealisasikan mandat KMK 429/2022 menjadi aksi nyata birokrasi.</p><p>Jawaban yang sesuai adalah <strong>A. Forum sinergi bersama, integrasi loket layanan terpadu, klinik konsultasi bersama, dan kompetisi inovasi tim gabungan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena pemasangan pagar pembatas kawat justru mengabadikan mentalitas silo yang merusak.</li><li><strong>C</strong>: Keliru karena pelarangan tegur sapa menghancurkan hubungan harmonis dan melanggar kode etik sinergi.</li><li><strong>D</strong>: Keliru karena pemutusan komunikasi antarunit melumpuhkan efektivitas penerimaan dan perbendaharaan negara.</li><li><strong>E</strong>: Keliru karena penutupan loket interaktif menurunkan mutu kepuasan publik pemangku kepentingan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 39", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah sintesis konseptual mengenai bagaimana internalisasi Sikap Dasar afektif mampu menggerakkan Perilaku Efektif teramati dalam sistem kerja baru kementerian!", "options": ["Sikap Dasar diinternalisasi melalui ancaman fisik -> pegawai menjadi takut -> kinerja operasional terhenti total.", "Sikap Dasar disimpan sebagai rahasia pribadi -> perilaku efektif diabaikan -> birokrasi berjalan tanpa adanya pedoman.", "Sikap Dasar dihafal teksnya -> perilaku efektif digantikan mesin -> seluruh pegawai diputus hubungan kerjanya sepihak.", "Sikap Dasar dibiarkan tumbuh liar -> perilaku efektif ditentukan pasar bebas -> etika kementerian dihapuskan resmi.", "Keyakinan batin Sikap Dasar ditumbuhkan -> membentuk niat moral -> termanifestasi dalam gaya kerja teramati yang produktif."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 39", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 39</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sikap Dasar (keyakinan/mindset afektif) mendasari munculnya Perilaku Efektif (gaya kerja teramati); internalisasi nilai membentuk keyakinan diri yang mewujud dalam kebiasaan perilaku produktif sehari-hari.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Transformasi budaya yang langgeng selalu bekerja dari dalam ke luar (inside-out), di mana pembenahan alam pikir dan keyakinan batiniah (Sikap Dasar) mendahului perubahan perilaku nyata di tempat kerja. Ketika nilai-nilai luhur BerAKHLAK dan Kemenkeu telah terpatri sebagai kompas moral nurani pegawai, dorongan untuk bekerja cepat, akurat, transparan, dan kolaboratif (Perilaku Efektif) akan muncul secara sukarela dan berulang menjadi kebiasaan hidup tanpa memerlukan pengawasan fisik yang represif. Penjelasan materi membuktikan bahwa Perilaku Efektif bersumber langsung dari Sikap Dasar pegawai demi mendukung sistem kerja baru yang produktif. Maka dari itu, opsi E menyajikan sintesis kausalitas psikologis budaya yang paling sempurna.</p><p>Jawaban yang sesuai adalah <strong>E. Keyakinan batin Sikap Dasar ditumbuhkan -> membentuk niat moral -> termanifestasi dalam gaya kerja teramati yang produktif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kekerasan fisik bukanlah metode internalisasi nilai dan merusak kesehatan mental korps.</li><li><strong>B</strong>: Keliru karena pembiaran tanpa pedoman melumpuhkan akuntabilitas dan merusak kinerja organisasi.</li><li><strong>C</strong>: Keliru karena penghafalan mekanistis tanpa penghayatan nurani tidak akan mengubah karakter aparatur.</li><li><strong>D</strong>: Keliru karena penyerahan etika kepada mekanisme pasar bebas mencederai watak pelayanan publik kenegaraan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 39.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Analitis", "question": "KMK Nomor 429/KMK.01/2022 menetapkan tiga strategi utama pembudayaan Sikap Dasar dan Perilaku Efektif: Internalisasi, Institusionalisasi, dan Eksternalisasi. Manakah di antara pernyataan berikut yang secara akurat menganalisis fokus pembeda dari strategi Institusionalisasi?", "options": ["Institusionalisasi berfokus menjadikan nilai melekat dan melembaga melalui penguatan regulasi serta sistem reward and punishment.", "Institusionalisasi hanya berorientasi pada penyebaran video kampanye etika kepada masyarakat umum pembayar pajak.", "Institusionalisasi memusatkan kegiatan pada penyelenggaraan lomba menyanyi antar-kantor wilayah kementerian keuangan.", "Institusionalisasi dirancang untuk membubarkan fungsi pengawasan melekat yang selama ini diemban oleh atasan langsung.", "Institusionalisasi berfokus pada penghapusan seluruh buku panduan kode etik dan menggantinya dengan instruksi lisan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Institusionalisasi adalah kegiatan atau upaya yang bertujuan menjadikan sekumpulan nilai, sikap, dan perilaku tertentu sebagai bagian yang melekat dan melembaga dalam organisasi, melalui penguatan regulasi/kebijakan, pengintegrasian dengan sistem reward/punishment, serta upaya lainnya.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Strategi Institusionalisasi memegang peranan krusial dalam memberikan daya ikat formal dan kepastian sanksi terhadap penegakan budaya kerja agar tidak berhenti sebagai wacana moral semata. Melalui pelembagaan ke dalam peraturan kedinasan, standar operasional prosedur, indikator kinerja utama, serta sistem apresiasi dan hukuman (reward and punishment) yang tegas, nilai organisasi terpatri menjadi sistem kerja otomatis yang mengawal perilaku setiap aparatur. Teks materi KMK 429/2022 secara gamblang mendefinisikan Institusionalisasi sebagai upaya melembagakan nilai melalui penguatan kebijakan dan integrasi reward/punishment. Oleh karena itu, opsi A memberikan analisis definisi yang paling tepat dan presisi.</p><p>Jawaban yang sesuai adalah <strong>A. Institusionalisasi berfokus menjadikan nilai melekat dan melembaga melalui penguatan regulasi serta sistem reward and punishment.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena penyebaran video kepada pihak luar masyarakat merupakan domain dari strategi Eksternalisasi.</li><li><strong>C</strong>: Keliru karena perlombaan seni menyanyi bukanlah substansi pelembagaan sistemik nilai dan regulasi organisasi.</li><li><strong>D</strong>: Keliru karena institusionalisasi justru memperkuat sistem kontrol dan kepatuhan pengawasan melekat atasan.</li><li><strong>E</strong>: Keliru karena institusionalisasi menuntut regulasi tertulis yang sah dan mengikat, bukan instruksi lisan semata.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Aplikasi", "question": "Sebuah kantor wilayah kementerian keuangan hendak menerapkan strategi Institusionalisasi penguatan budaya kerja. Langkah aplikatif konkret yang paling selaras dengan mandat strategi tersebut adalah...", "options": ["Membuat spanduk ucapan selamat ulang tahun berukuran besar bagi pimpinan kantor di pinggir jalan raya umum.", "Menyelenggarakan piknik bersama seluruh pegawai ke pantai wisata setiap akhir pekan menggunakan anggaran dinas.", "Mengintegrasikan kepatuhan Sikap Dasar dan Perilaku Efektif ke dalam sistem penilaian kinerja dan pemberian penghargaan.", "Membagikan cenderamata telepon genggam pintar mewah kepada seluruh tamu yang datang mengunjungi kantor pelayanan dinas.", "Menghapus seluruh formulir laporan pelanggaran disiplin guna menjaga laporan kondusifitas unit kerja di hadapan menteri."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Penerapan strategi Institusionalisasi dilakukan melalui penguatan regulasi/kebijakan dan pengintegrasian nilai/perilaku dengan sistem reward dan punishment di lingkungan kerja.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengintegrasian kepatuhan etika ke dalam sistem penilaian kinerja berkala menjamin bahwa pencapaian hasil kerja tidak dinilai semata-mata dari angka keluaran administratif, melainkan juga dari cara dan perilaku berintegritas dalam mencapai target tersebut. Memberikan apresiasi (reward) kepada pegawai yang konsisten menunjukkan Perilaku Efektif dan menjatuhkan konsekuensi (punishment) atas pelanggaran Sikap Dasar merupakan aplikasi nyata institusionalisasi nilai ke dalam struktur operasional organisasi. Dokumen materi mencantumkan pengintegrasian sistem reward and punishment sebagai pilar utama strategi institusionalisasi. Dengan demikian, penerapan pada opsi C adalah langkah manajerial yang paling sah dan tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Mengintegrasikan kepatuhan Sikap Dasar dan Perilaku Efektif ke dalam sistem penilaian kinerja dan pemberian penghargaan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pembuatan spanduk ucapan pribadi pimpinan tidak ada kaitannya dengan pelembagaan nilai organisasi.</li><li><strong>B</strong>: Keliru karena pembiayaan rekreasi menggunakan anggaran operasional dinas melanggar etika perbendaharaan.</li><li><strong>D</strong>: Keliru karena pembagian barang mewah kepada tamu kantor merupakan pemborosan dan gratifikasi terlarang.</li><li><strong>E</strong>: Keliru karena penghapusan laporan pelanggaran merupakan pembodohan tata kelola yang merusak akuntabilitas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Aplikasi", "question": "Dalam rangka mengeksekusi strategi Eksternalisasi budaya kementerian, tindakan nyata yang paling tepat ditunjukkan oleh para pegawai di garda terdepan pelayanan publik adalah...", "options": ["Menutup gerbang kantor pelayanan rapat-rapat agar masyarakat luar tidak mengetahui budaya kerja internal kantor.", "Menolak melayani pemangku kepentingan yang belum membaca dan menghafal seluruh pasal dalam keputusan menteri.", "Meminta pemohon layanan membayar biaya sertifikasi pembudayaan sebelum dokumen perizinan diserahkan resmi.", "Mengharuskan warga masyarakat mengenakan seragam dinas pegawai kementerian saat memasuki area lobi pelayanan.", "Menjadi role model keteladanan perilaku dalam memberikan pelayanan prima yang berintegritas kepada pemangku kepentingan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Eksternalisasi bertujuan mendorong dan memastikan pemahaman Budaya Kemenkeu oleh pihak di luar kementerian melalui keteladanan perilaku pegawai dalam melayani pemangku kepentingan (role models).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Citra dan pemahaman masyarakat mengenai budaya luhur Kementerian Keuangan tidak dibangun melalui retorika iklan semata, melainkan dirasakan secara langsung melalui sentuhan keteladanan aparatur saat melayani di loket publik. Ketika petugas menunjukkan ketulusan, kesantunan, kecepatan, dan kejujuran tanpa kompromi gratifikasi, pemangku kepentingan eksternal akan secara alami memahami, menghormati, dan teredukasi oleh nilai-nilai integritas kementerian. Definisi materi secara tegas menyatakan bahwa eksternalisasi diwujudkan melalui keteladanan perilaku pegawai sebagai teladan (role models) saat memberikan layanan publik. Oleh sebab itu, keteladanan pelayanan pada opsi E adalah aplikasi eksternalisasi yang paling sempurna.</p><p>Jawaban yang sesuai adalah <strong>E. Menjadi role model keteladanan perilaku dalam memberikan pelayanan prima yang berintegritas kepada pemangku kepentingan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menutup akses informasi bertolak belakang dengan hakikat eksternalisasi yang mengedukasi publik.</li><li><strong>B</strong>: Keliru karena mempersyaratkan hafalan regulasi merupakan arogansi yang mempersulit hak pelayanan warga.</li><li><strong>C</strong>: Keliru karena pemungutan biaya sertifikasi pembudayaan merupakan tindak pidana korupsi pungutan liar.</li><li><strong>D</strong>: Keliru karena mewajibkan masyarakat mengenakan seragam dinas birokrasi melanggar kepatutan hukum.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja hanya gencar menyelenggarakan sosialisasi internalisasi nilai lewat ceramah, namun enggan menerapkan sistem sanksi bagi pegawai yang terbukti melanggar kode etik. Mengapa evaluasi terhadap kebijakan satker tersebut KELIRU?", "options": ["Kebijakan satker sangat tepat karena ceramah moral terbukti seratus persen mampu menghapus sifat tamak manusia.", "Kebijakan satker keliru karena tanpa institusionalisasi reward dan punishment, pembudayaan nilai akan mandul dan diabaikan.", "Kebijakan satker sangat efisien karena satker tidak perlu lagi mengeluarkan energi untuk menegakkan disiplin dinas.", "Kebijakan satker dapat dibenarkan sepanjang tidak ada laporan dari media massa yang menyoroti pelanggaran kantor.", "Kebijakan satker merupakan bentuk kasih sayang pimpinan yang sah dalam membiarkan penyimpangan staf bawahan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pembudayaan menuntut perpaduan seimbang antara Internalisasi (mindset) dan Institusionalisasi (regulasi & reward/punishment). Tanpa penegakan aturan dan sanksi, nilai kehilangan daya dorong formal.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Edukasi moral melalui sosialisasi dan ceramah (Internalisasi) hanyalah separuh jalan dalam rekayasa budaya organisasi; ia memerlukan ketegasan hukum dan konsekuensi nyata (Institusionalisasi) agar ditaati secara konsisten. Apabila pelanggaran kode etik dibiarkan tanpa sanksi yang tegas, para pelanggar akan merasa kebal hukum sementara pegawai yang jujur akan terdemotivasi, sehingga sosialisasi nilai hanya akan dicemooh sebagai formalitas kosong. Doktrin KMK 429/2022 mewajibkan perpaduan strategi internalisasi dengan institusionalisasi berbasis penegakan reward and punishment yang adil. Oleh karena itu, kritik evaluatif pada opsi B membuktikan secara tajam bahwa meniadakan sanksi merupakan kelemahan fatal.</p><p>Jawaban yang sesuai adalah <strong>B. Kebijakan satker keliru karena tanpa institusionalisasi reward dan punishment, pembudayaan nilai akan mandul dan diabaikan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena ceramah moral tanpa instrumen penegakan disiplin rentan menjadi kepatuhan semu di atas kertas.</li><li><strong>C</strong>: Keliru karena mengabaikan penegakan aturan bukanlah efisiensi melainkan pembiaran pembusukan organisasi.</li><li><strong>D</strong>: Keliru karena penegakan integritas harus berjalan mandiri tanpa bergantung pada viralitas sorotan media.</li><li><strong>E</strong>: Keliru karena membiarkan pelanggaran staf merupakan kelemahan kepemimpinan yang merusak wibawa hukum negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Analitis", "question": "Berdasarkan pembagian peran manajerial pada materi, bagaimanakah analisis mandat khusus yang diemban oleh Biro SDM Sekretariat Jenderal dalam arsitektur penguatan budaya kementerian?", "options": ["Biro SDM bertugas mencetak seragam batik kedinasan untuk dibagikan secara cuma-cuma kepada seluruh kementerian lain dinas.", "Biro SDM berwenang membatalkan seluruh hasil lelang pengadaan barang dan jasa pada tingkat satuan kerja operasional.", "Biro SDM memegang mandat mengambil alih seluruh fungsi loket perizinan ekspor impor kepabeanan di pelabuhan laut.", "Biro SDM mengoordinasikan internalisasi, memantau, mengukur tingkat kematangan budaya, dan melapor ke Menteri Keuangan.", "Biro SDM bertugas menetapkan tarif pajak pertambahan nilai bagi seluruh komoditas sembako masyarakat di daerah."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Biro SDM Sekretariat Jenderal melakukan koordinasi pelaksanaan internalisasi Sikap Dasar dan Perilaku Efektif pegawai, pemantauan, evaluasi, dan pengukuran tingkat kematangan Budaya Kemenkeu, serta penyampaian laporan kepada Menteri Keuangan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Biro SDM Sekretariat Jenderal memegang peranan sentral sebagai dirigen orkestrasi budaya di level kementerian yang mengintegrasikan seluruh laporan pembudayaan dari para pimpinan unit eselon satu. Mandat ini mencakup koordinasi program internalisasi lintas unit, evaluasi efektivitas strategi, pengukuran indeks tingkat kematangan budaya (culture maturity level) secara ilmiah, serta perumusan rekomendasi strategis langsung kepada Menteri Keuangan. Uraian materi secara presisi menetapkan rantai fungsi Biro SDM Setjen sebagai koordinator, evaluator kematangan budaya, dan pelapor kepada pimpinan puncak kementerian. Maka dari itu, opsi D menyajikan analisis mandat manajerial Biro SDM secara paling sahih.</p><p>Jawaban yang sesuai adalah <strong>D. Biro SDM mengoordinasikan internalisasi, memantau, mengukur tingkat kematangan budaya, dan melapor ke Menteri Keuangan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pengadaan seragam dinas berada di bawah fungsi biro perlengkapan/umum, bukan tugas inti budaya SDM.</li><li><strong>B</strong>: Keliru karena pembatalan tender lelang barang jasa merupakan kewenangan panitia pengadaan dan pejabat komitmen.</li><li><strong>C</strong>: Keliru karena loket ekspor impor kepabeanan merupakan wewenang teknis Direktorat Jenderal Bea dan Cukai.</li><li><strong>E</strong>: Keliru karena penetapan tarif perpajakan merupakan wewenang kebijakan fiskal dan perundang-undangan nasional.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Evaluatif", "question": "Seorang pimpinan Unit Jabatan Pimpinan Tinggi Madya menolak menyusun laporan pemantauan penguatan budaya unitnya kepada Biro SDM Sekretariat Jenderal dengan dalih unitnya otonom. Mengapa sikap pimpinan unit tersebut KELIRU?", "options": ["Sikap pimpinan unit keliru karena pelaporan kepada Biro SDM merupakan kewajiban regulasi untuk evaluasi terpusat kementerian.", "Sikap pimpinan unit sangat tepat karena pejabat eselon satu tidak memiliki garis koordinasi dengan sekretariat jenderal.", "Sikap pimpinan unit sangat efisien karena menghemat penggunaan kertas laporan administrasi tahunan di ruang kantor dinas kerja.", "Sikap pimpinan unit dapat diterima sepanjang unit bersangkutan mampu menduduki peringkat penerimaan pajak pertama.", "Sikap pimpinan unit mencerminkan independensi birokrasi yang sah dalam menafsirkan peraturan menteri keuangan pusat."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Materi menegaskan kewajiban: Setiap pimpinan Unit Jabatan Pimpinan Tinggi Madya melakukan penumbuhan, pemantauan, evaluasi penguatan Budaya Kemenkeu, dan menyampaikan laporan pelaksanaannya kepada Biro SDM Sekretariat Jenderal.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keberhasilan penegakan budaya 'Kementerian Keuangan Satu' menuntut kepatuhan rantai komando pelaporan yang terintegrasi demi menjamin keseragaman standar nilai di seluruh direktorat jenderal. Dalih otonomi sektoral yang menolak pelaporan kepada Biro SDM Setjen mencederai asas koordinasi kelembagaan dan menghambat pengukuran maturitas budaya kementerian secara nasional. Ketentuan KMK 429/2022 secara eksplisit mewajibkan seluruh pimpinan JPT Madya melaporkan pelaksanaan pembudayaan kepada Biro SDM Setjen secara berkala. Oleh sebab itu, evaluasi pada opsi A secara tepat membuktikan bahwa penolakan pelaporan tersebut adalah kekeliruan administratif dan organisasional yang nyata.</p><p>Jawaban yang sesuai adalah <strong>A. Sikap pimpinan unit keliru karena pelaporan kepada Biro SDM merupakan kewajiban regulasi untuk evaluasi terpusat kementerian.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena Sekretariat Jenderal memegang fungsi koordinasi pembinaan aparatur seluruh eselon satu.</li><li><strong>C</strong>: Keliru karena laporan pemantauan dapat disampaikan secara digital tanpa alasan pemborosan kertas fisik.</li><li><strong>D</strong>: Keliru karena keunggulan penerimaan tidak menggugurkan kewajiban kepatuhan terhadap regulasi budaya menteri.</li><li><strong>E</strong>: Keliru karena independensi unit tidak membenarkan pengingkaran terhadap keputusan resmi menteri keuangan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan kegiatan atau upaya yang termasuk ke dalam strategi Internalisasi Sikap Dasar dan Perilaku Efektif sebagaimana diatur dalam KMK Nomor 429/KMK.01/2022?", "options": ["Penyelenggaraan kegiatan sosialisasi nilai dan etika secara fisik melalui tatap muka di aula ruang kantor kedinasan.", "Pelaksanaan sosialisasi nilai secara elektronik melalui video interaktif, podcast kedinasan, dan media digital.", "Penjatuhan hukuman disiplin pemotongan tunjangan kinerja sebesar lima puluh persen kepada pegawai yang melanggar.", "Penyelenggaraan proses pembelajaran terstruktur melalui diklat, lokakarya, dan program edukasi berkelanjutan pegawai.", "Pelaksanaan forum diskusi kelompok terarah (focus group discussion) mengenai implementasi perilaku kerja efektif."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Internalisasi adalah upaya membentuk keyakinan/mindset diri agar terwujud dalam sikap/perilaku positif, melalui sosialisasi fisik/elektronik, proses pembelajaran, focus group discussion, serta upaya lainnya. Penjatuhan hukuman (punishment) masuk ke Institusionalisasi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Strategi Internalisasi berfokus pada pendekatan edukatif dan persuasif guna membangun kesadaran nalar dan membentuk keyakinan moral aparatur dari dalam sanubari melalui sosialisasi, pembelajaran, dan diskusi kelompok (FGD). Sebaliknya, penjatuhan sanksi formal, pemotongan tunjangan, dan penegakan hukum disiplin merupakan instrumen koersif yang masuk ke dalam domain strategi Institusionalisasi (sistem reward and punishment). Penjelasan materi secara presisi membedakan instrumen edukasi internalisasi dari instrumen penegakan regulasi institusionalisasi. Oleh karena itu, penjatuhan hukuman pemotongan tunjangan pada opsi C jelas bukan merupakan bagian dari strategi Internalisasi melainkan Institusionalisasi.</p><p>Jawaban yang sesuai adalah <strong>C. Penjatuhan hukuman disiplin pemotongan tunjangan kinerja sebesar lima puluh persen kepada pegawai yang melanggar.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Bentuk kegiatan internalisasi sah melalui sosialisasi fisik tatap muka yang tercantum dalam teks aturan.</li><li><strong>B</strong>: Bentuk kegiatan internalisasi sah melalui media sosialisasi elektronik digital sesuai materi regulasi.</li><li><strong>D</strong>: Bentuk kegiatan internalisasi sah melalui proses pembelajaran terstruktur yang tercantum dalam aturan.</li><li><strong>E</strong>: Bentuk kegiatan internalisasi sah melalui focus group discussion (FGD) pembentukan keyakinan mindset.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Analitis", "question": "Uraian materi menguraikan alur bertingkat pembudayaan: dari Pimpinan JPT Madya melaporkan ke Biro SDM, hingga Biro SDM melaporkan kepada Menteri Keuangan. Bagaimanakah korelasi sistemik dari alur pelaporan berjenjang tersebut?", "options": ["Alur tersebut bertujuan memperpanjang jalur birokrasi agar Menteri Keuangan tidak pernah mengetahui masalah pegawai.", "Alur tersebut mewajibkan Menteri Keuangan menandatangani surat peringatan disiplin bagi setiap keterlambatan staf.", "Alur tersebut dirancang untuk menghapus kewenangan manajerial para pimpinan unit eselon dua di seluruh Indonesia.", "Alur tersebut membatasi akses masyarakat pembayar pajak dalam mengajukan permohonan keterbukaan informasi dinas.", "Alur berjenjang menjamin akuntabilitas data kematangan budaya tersaring sistematis sebagai bahan kebijakan strategis Menkeu."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Alur pelaporan berjenjang: Pimpinan JPT Madya melaporkan ke Biro SDM Setjen -> Biro SDM mengukur tingkat kematangan budaya dan menyampaikan laporan komprehensif kepada Menteri Keuangan untuk pengambilan keputusan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Mekanisme pelaporan berjenjang dirancang untuk memastikan bahwa data pelaksanaan budaya dari ratusan satuan kerja operasional dihimpun, dikonsolidasi, dan dianalisis secara saintifik oleh unit pengelola SDM sebelum disajikan ke meja pengambil kebijakan tertinggi. Penyaringan bertingkat oleh Biro SDM Setjen menghasilkan indeks tingkat kematangan budaya (culture maturity level) yang komprehensif, sehingga Menteri Keuangan memperoleh gambaran utuh mengenai iklim integritas dan efektivitas reformasi birokrasi di kementeriannya. Alur ini merefleksikan tata kelola pemerintahan berbasis bukti (evidence-based policymaking) yang akuntabel. Karena itulah, opsi E memberikan analisis sistemik yang paling tepat dan bernas.</p><p>Jawaban yang sesuai adalah <strong>E. Alur berjenjang menjamin akuntabilitas data kematangan budaya tersaring sistematis sebagai bahan kebijakan strategis Menkeu.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena alur pelaporan bertujuan menyajikan sintesis data objektif bagi menteri, bukan menyembunyikan masalah.</li><li><strong>B</strong>: Keliru karena sanksi keterlambatan staf diatur secara berjenjang oleh pejabat pembina kepegawaian di daerah.</li><li><strong>C</strong>: Keliru karena alur koordinasi budaya justru memperkuat peran kepemimpinan pimpinan unit di seluruh tingkatan.</li><li><strong>D</strong>: Keliru karena pelaporan budaya internal kementerian tidak mengurangi hak keterbukaan informasi publik warga.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka metodologi pengukuran tingkat kematangan Budaya Kemenkeu pada tingkat satuan kerja yang aplikatif dan objektif bagi Biro SDM!", "options": ["Menentukan tingkat kematangan berdasarkan banyaknya jumlah bingkai foto pimpinan satker yang dipajang di dinding kantor dinas.", "Survei persepsi perilaku efektif, observasi kepatuhan tata tertib, audit kasus integritas UKI, dan indeks kepuasan publik.", "Mengukur kematangan budaya semata-mata dari kecepatan satker menghabiskan seluruh alokasi anggaran belanja kantor.", "Menetapkan kematangan budaya berdasarkan hasil undian lotre kupon yang dicabut secara acak oleh panitia kantor daerah.", "Mengharuskan setiap pegawai membayar uang mahar sertifikasi budaya kepada panitia penilai sebelum audit dimulai dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Pengukuran tingkat kematangan Budaya Kemenkeu oleh Biro SDM Setjen memerlukan instrumen objektif yang memadukan internalisasi, kepatuhan perilaku, penegakan regulasi, dan kepuasan pelayanan pemangku kepentingan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengukuran maturitas budaya organisasi publik memerlukan metodologi saintifik yang mengombinasikan data kuantitatif dan kualitatif secara berimbang dari berbagai sudut pandang (triangulasi data). Memadukan survei persepsi pegawai atas penghayatan Sikap Dasar, uji petik observasi pelaksanaan Perilaku Efektif di ruang kerja, catatan rekam jejak pelanggaran etik dari UKI dan Inspektorat Jenderal, serta survei kepuasan masyarakat pengguna layanan menjamin hasil penilaian kematangan budaya merefleksikan kondisi riil di lapangan tanpa bias subjektif. Sintesis instrumen pengukuran terpadu pada opsi B menyajikan kerangka penilaian yang paling valid dan akuntabel.</p><p>Jawaban yang sesuai adalah <strong>B. Survei persepsi perilaku efektif, observasi kepatuhan tata tertib, audit kasus integritas UKI, dan indeks kepuasan publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena jumlah foto pimpinan di dinding hanyalah formalitas visual kultus individu nir-substansi.</li><li><strong>C</strong>: Keliru karena percepatan penyerapan belanja tanpa kualitas output bukanlah indikator budaya berintegritas.</li><li><strong>D</strong>: Keliru karena penentuan acak undian lotre merusak asas objektivitas dan integritas metodologi penilaian.</li><li><strong>E</strong>: Keliru karena pungutan uang mahar sertifikasi budaya merupakan tindak pidana korupsi pemerasan jabatan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 40", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah rencana aksi tahunan penguatan budaya pada kantor pelayanan operasional yang menyinergikan strategi Internalisasi, Institusionalisasi, dan Eksternalisasi secara berkesinambungan!", "options": ["Meniadakan seluruh jam kerja pelayanan loket selama enam bulan penuh guna menyelenggarakan retret budaya di luar negeri.", "Menghukum staf dengan pemotongan gaji tanpa aturan -> menghapus buku kode etik -> memboikot seluruh permohonan warga.", "Menyerahkan seluruh fungsi kepegawaian kantor dinas kepada yayasan swasta asing tanpa keterlibatan biro SDM pusat.", "FGD mingguan Sikap Dasar (Internalisasi), KPI integritas & reward (Institusionalisasi), dan duta layanan publik (Eksternalisasi).", "Memasang pengeras suara di koridor kantor yang memutar rekaman instruksi disiplin tanpa henti selama 24 jam setiap hari."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 40", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 40</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sinergi 3 strategi pembudayaan KMK 429/2022: Internalisasi (FGD/pembelajaran pembentuk mindset), Institusionalisasi (regulasi, KPI, sistem reward/punishment), dan Eksternalisasi (keteladanan role model pelayanan ke publik).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Rencana aksi pembudayaan yang berhasil harus mampu merajut ketiga pilar strategi KMK 429/2022 menjadi siklus pembiasaan yang saling menguatkan sepanjang tahun anggaran. Strategi Internalisasi dieksekusi melalui diskusi terarah (FGD) berkala untuk menyegarkan komitmen nurani; strategi Institusionalisasi ditegakkan melalui penyisipan perilaku efektif ke dalam kontrak kinerja individu dan pemberian penghargaan bagi aparatur teladan; sedangkan strategi Eksternalisasi ditampilkan melalui penugasan duta layanan yang menjadi teladan integritas di hadapan masyarakat luas. Sintesis rencana aksi terpadu pada opsi D merupakan cetak biru operasional budaya kerja yang paling komprehensif dan aplikatif.</p><p>Jawaban yang sesuai adalah <strong>D. FGD mingguan Sikap Dasar (Internalisasi), KPI integritas & reward (Institusionalisasi), dan duta layanan publik (Eksternalisasi).</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penutupan loket layanan publik demi retret melanggar kewajiban konstitusional aparatur sipil negara.</li><li><strong>B</strong>: Keliru karena penghukuman sewenang-wenang dan pemboikotan layanan adalah kejahatan perusakan birokrasi negara.</li><li><strong>C</strong>: Keliru karena menyerahkan pengelolaan kepegawaian kepada yayasan swasta asing melanggar kedaulatan negara.</li><li><strong>E</strong>: Keliru karena pemutaran suara bising 24 jam merupakan polusi suara yang menyiksa psikologis pegawai.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 40.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Aplikasi", "question": "Ketika bertugas lembur sendirian di ruang kasir tanpa pengawasan atasan maupun kamera pengawas, seorang bendahara penerimaan tetap mencatat setiap rupiah penerimaan negara secara akurat. Tindakan bendahara tersebut merupakan aplikasi Perilaku Efektif apa?", "options": ["Menunjukkan perilaku disiplin diri, memegang teguh tanggung jawab, dan taat aturan meski tanpa pengawasan.", "Menerapkan perilaku pura-pura jujur di depan pimpinan guna mendapatkan promosi kenaikan pangkat jabatan.", "Menyembunyikan sisa uang kas lebih untuk dibagikan secara rahasia kepada rekan satu seksi pada esok hari kantor.", "Meminta bagian potongan honor jasa kasir secara langsung dari setiap setoran penerimaan kas daerah dinas.", "Melimpahkan seluruh tanggung jawab pembukuan kas kepada petugas kebersihan gedung kantor yang melintas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Integritas (selaras Akuntabel & Loyal): Menunjukkan perilaku disiplin diri, memegang teguh tanggung jawab, dan taat aturan meski tanpa pengawasan dengan penuh kesadaran, serta rela berkorban.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Integritas moral yang sejati diuji ketika seseorang berada dalam situasi bebas tanpa pengawasan fisik dari manusia lain, di mana kesadaran batiniah bertindak sebagai hakim tunggal yang mengawal kejujuran perilaku. Sikap bendahara yang tetap membukukan setiap rupiah uang negara secara presisi membuktikan adanya kedisiplinan diri yang murni dan kepatuhan sukarela pada sumpah jabatan aparatur pengelola perbendaharaan negara. Panduan Perilaku Efektif KMK 429/2022 secara eksplisit merumuskan tindakan taat aturan meski tanpa pengawasan sebagai manifestasi nilai Integritas yang selaras dengan nilai Akuntabel dan Loyal. Oleh karena itu, opsi A mendefinisikan aplikasi perilaku efektif tersebut secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>A. Menunjukkan perilaku disiplin diri, memegang teguh tanggung jawab, dan taat aturan meski tanpa pengawasan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena kepura-puraan di depan pimpinan mencerminkan kemunafikan yang merusak integritas nurani.</li><li><strong>C</strong>: Keliru karena menggelapkan selisih uang kas negara merupakan tindak pidana korupsi perbendaharaan.</li><li><strong>D</strong>: Keliru karena memotong uang setoran penerimaan negara merupakan pungutan liar dan kejahatan jabatan.</li><li><strong>E</strong>: Keliru karena melimpahkan wewenang kasir kepada pihak non-otoritas melanggar tata tertib dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Analitis", "question": "Pada penyelarasan nilai Akuntabel dan Loyal dengan nilai Integritas, Sikap Dasar dirumuskan sebagai senantiasa amanah, jujur, disiplin, konsisten, dapat dipercaya, dan militan dalam bekerja. Bagaimanakah analisis makna 'militan dalam bekerja' dalam konteks pengabdian aparatur sipil negara?", "options": ["Militan dalam bekerja bermakna aparatur diwajibkan membawa senjata api laras panjang saat bekerja di ruang kantor.", "Militan dalam bekerja berarti menolak seluruh instruksi menteri yang tidak sesuai dengan pandangan politik staf.", "Militan dalam bekerja merefleksikan kegigihan pantang menyerah, ketahanan mental, dan dedikasi total bagi negara.", "Militan dalam bekerja menuntut pegawai bekerja selama 24 jam sehari tanpa hak istirahat makan dan tidur siang.", "Militan dalam bekerja membenarkan penggunaan kekerasan fisik kepada wajib pajak yang terlambat membayar denda."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sikap Dasar Integritas (Akuntabel & Loyal): senantiasa amanah, jujur, disiplin, konsisten, dapat dipercaya, militan dalam bekerja demi menjaga kedaulatan keuangan dan kemajuan bangsa.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Konsep 'militan dalam bekerja' bagi aparatur sipil negara bukanlah terminologi militeristik bersenjata, melainkan metafora etos perjuangan yang menggambarkan daya juang tinggi, loyalitas konstitusional tanpa pamrih, dan keteguhan prinsip dalam menjaga kedaulatan fiskal Republik Indonesia. Jiwa militansi birokrasi ini mendorong pegawai tetap gigih menyelesaikan amanah perbendaharaan negara dalam situasi krisis atau tekanan beban kerja berat dengan pantang mengorbankan integritas moral. Penjelasan Sikap Dasar KMK 429/2022 menempatkan militansi kerja sebagai pilar dedikasi aparatur pengelola keuangan negara. Maka dari itu, opsi C memberikan analisis makna filosofis yang paling tepat dan bermartabat.</p><p>Jawaban yang sesuai adalah <strong>C. Militan dalam bekerja merefleksikan kegigihan pantang menyerah, ketahanan mental, dan dedikasi total bagi negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena aparatur sipil negara bertugas melayani secara sipil tanpa kepemilikan senjata api bebas.</li><li><strong>B</strong>: Keliru karena pembangkangan terhadap arahan sah menteri mencederai asas loyalitas aparatur sipil negara.</li><li><strong>D</strong>: Keliru karena militansi kerja tidak meniadakan hak biologis kesehatan dan keselamatan kerja pegawai.</li><li><strong>E</strong>: Keliru karena kekerasan fisik melanggar hukum pidana serta mencoreng wibawa kemanusiaan birokrasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat struktural memanfaatkan laptop dinas dan printer kantor untuk mencetak ribuan lembar brosur promosi bisnis properti pribadi keluarganya. Mengapa tindakan pejabat tersebut KELIRU?", "options": ["Tindakan pejabat sangat terpuji karena bisnis properti keluarga dapat menopang stabilitas makroekonomi daerah.", "Tindakan pejabat keliru karena melanggar kewajiban bertanggung jawab dalam penggunaan Barang Milik Negara.", "Tindakan pejabat dapat dibenarkan sepanjang tinta printer kantor diganti dengan tinta buatan sendiri di rumah.", "Tindakan pejabat sangat efisien dalam rangka menguji batas ketahanan mesin cetak dokumen kantor pelayanan dinas.", "Tindakan pejabat merupakan hak prerogatif pimpinan yang sah dalam memanfaatkan seluruh inventaris negara."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Integritas butir kelima mewajibkan pegawai: memiliki kesadaran tentang menjaga kerahasiaan, keamanan data, dan informasi organisasi serta bertanggung jawab dalam penggunaan Barang Milik Negara (BMN).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Barang Milik Negara (BMN) dibiayai dari uang pajak rakyat dan diadakan secara eksklusif untuk menunjang kelancaran penyelenggaraan tugas kenegaraan dan pelayanan publik, bukan untuk memfasilitasi akumulasi kekayaan privat pegawai. Menyalahgunakan aset operasional kantor demi kepentingan bisnis komersial keluarga merupakan bentuk korupsi fasilitas kedinasan yang mengikis integritas dan merugikan keuangan instansi. Ketentuan Perilaku Efektif nilai Integritas secara eksplisit mewajibkan tanggung jawab penuh dalam pemanfaatan BMN sesuai peruntukan sah. Oleh sebab itu, kritik evaluatif pada opsi B secara tepat membuktikan bahwa perbuatan tersebut adalah pelanggaran kode perilaku.</p><p>Jawaban yang sesuai adalah <strong>B. Tindakan pejabat keliru karena melanggar kewajiban bertanggung jawab dalam penggunaan Barang Milik Negara.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena dalih ekonomi makro tidak dapat melegitimasi penyelewengan aset inventaris negara.</li><li><strong>C</strong>: Keliru karena penggantian tinta tidak menghapus status pelanggaran penyalahgunaan aset perangkat keras BMN.</li><li><strong>D</strong>: Keliru karena pengujian ketahanan mesin dinas dilakukan melalui pemeliharaan teknis resmi, bukan bisnis privat.</li><li><strong>E</strong>: Keliru karena jabatan struktural membawa amanah perwalian aset publik, bukan hak kepemilikan pribadi mutlak.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Aplikasi", "question": "Setelah mengikuti pelatihan teknis analisis data makroekonomi, seorang staf fungsional mengunggah materi rangkuman dan kode analisis ke portal sistem manajemen pengetahuan (KMS) kantor serta membimbing rekan-rekannya. Tindakan tersebut merupakan perwujudan Perilaku Efektif apa?", "options": ["Upaya memonopoli keahlian teknis agar rekan kerja lain merasa rendah diri di hadapan pimpinan kantor dinas.", "Tindakan melanggar hak cipta pengajar pelatihan demi mengejar popularitas semu di kalangan pegawai muda kantor.", "Penerapan strategi persaingan bebas birokrasi guna menyingkirkan pegawai senior yang lambat mempelajari komputer.", "Tindakan membuang-buang waktu kerja dinas yang seharusnya dialokasikan untuk mengobrol santai di kantin kantor.", "Kegigihan belajar dan mengembangkan pola pikir termasuk memanfaatkan sistem manajemen pengetahuan organisasi."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Profesionalisme (Kompeten): Menunjukkan kemauan, kemampuan, dan kegigihan untuk belajar dan mengembangkan pola pikir termasuk memanfaatkan sistem manajemen pengetahuan serta membantu orang lain untuk belajar.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Berbagi pengetahuan melalui platform Knowledge Management System (KMS) dan mengedukasi rekan sejawat merupakan perwujudan sejati dari budaya organisasi pemelajar (learning organization) yang profesional. Tindakan ini mentransformasikan kompetensi individual menjadi keunggulan kolektif satuan kerja, sehingga kualitas hasil analisis institusi meningkat secara berkelanjutan. Rincian Perilaku Efektif Kompeten/Profesionalisme secara spesifik mengamanatkan aparatur untuk gigih belajar, memanfaatkan KMS, dan gemar menolong orang lain belajar. Dengan demikian, dedikasi berbagi ilmu pada opsi E secara akurat mengaplikasikan butir perilaku efektif tersebut.</p><p>Jawaban yang sesuai adalah <strong>E. Kegigihan belajar dan mengembangkan pola pikir termasuk memanfaatkan sistem manajemen pengetahuan organisasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena berbagi ilmu bertujuan memberdayakan seluruh tim, bukan merendahkan kompetensi rekan.</li><li><strong>B</strong>: Keliru karena pengunggahan resume edukasi kedinasan pada KMS resmi kementerian merupakan praktik sah.</li><li><strong>C</strong>: Keliru karena profesionalisme berorientasi pada kolaborasi peningkatan mutu, bukan persaingan destruktif.</li><li><strong>D</strong>: Keliru karena transfer pengetahuan adalah investasi intelektual yang sangat bernilai tambah bagi dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Analitis", "question": "Perilaku Efektif nilai Profesionalisme butir ketiga mewajibkan aparatur: menunjukkan prakarsa dalam merencanakan dan mencapai sasaran kerja dengan memperhitungkan risiko berdasarkan data dan fakta. Bagaimanakah keterkaitan logis antara mitigasi risiko berbasis data dengan keberhasilan sasaran kinerja?", "options": ["Mitigasi risiko berbasis data bertujuan memastikan anggaran kantor dapat dihabiskan tanpa perlu membuat kuitansi sah.", "Mitigasi risiko berbasis data dirancang untuk membatasi ruang inisiatif staf agar tidak menghasilkan ide-ide baru.", "Mitigasi risiko berbasis data mewajibkan pimpinan menghapus seluruh target sasaran kerja tahunan kementerian.", "Analisis data objektif memetakan potensi hambatan sejak dini sehingga langkah mitigasi dapat disusun presisi.", "Mitigasi risiko berbasis data membebaskan aparatur dari kewajiban mematuhi standar operasional prosedur dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Profesionalisme butir ketiga menuntut prakarsa perencanaan berbasis data dan fakta serta perhitungan risiko yang matang demi menjamin ketercapaian target mutu secara presisi.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Perencanaan kerja yang hanya bertumpu pada asumsi intuitif atau rutinitas masa lalu sangat rentan mengalami kegagalan fatal saat menghadapi dinamika ketidakpastian ekonomi dan fiskal. Dengan mendasarkan prakarsa pada data empiris yang sahih dan pemetaan risiko yang komprehensif, aparatur mampu mengidentifikasi titik-titik rawan kegagalan sebelum terjadi, sehingga strategi alternatif dapat disiapkan secara matang. Butir ketiga perilaku efektif profesionalisme secara presisi merangkai prakarsa, analisis data fakta, dan mitigasi risiko sebagai pilar pencapaian target. Oleh karenanya, opsi D memberikan analisis keterkaitan logis perencanaan berbasis data secara paling akurat.</p><p>Jawaban yang sesuai adalah <strong>D. Analisis data objektif memetakan potensi hambatan sejak dini sehingga langkah mitigasi dapat disusun presisi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penyerapan anggaran tetap terikat mutlak pada pertanggungjawaban bukti kuitansi sah.</li><li><strong>B</strong>: Keliru karena perhitungan risiko justru menjadi kompas pengaman bagi lahirnya inovasi kerja yang terukur.</li><li><strong>C</strong>: Keliru karena mitigasi risiko bertujuan mengamankan ketercapaian sasaran, bukan menghapus target kerja.</li><li><strong>E</strong>: Keliru karena manajemen risiko justru memperkuat kepatuhan terhadap SOP dan tata kelola yang baik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Evaluatif", "question": "Seorang staf verifikator perbendaharaan mengejar rekor menyelesaikan seratus berkas surat perintah membayar dalam satu jam dengan cara menandatangani dokumen tanpa membaca isinya, sehingga memicu kekeliruan transfer dana. Mengapa pendekatan staf tersebut KELIRU?", "options": ["Pendekatan staf keliru karena profesionalisme menuntut keseimbangan antara kecepatan dan akurasi kualitas.", "Pendekatan staf sangat terpuji karena kecepatan administratif merupakan satu-satunya ukuran kinerja kementerian.", "Pendekatan staf dapat dibenarkan sepanjang bank persepsi bersedia menanggung kerugian salah transfer kas dinas.", "Pendekatan staf mencerminkan ketangkasan kerja modern yang harus diadopsi oleh seluruh jajaran bendahara negara.", "Pendekatan staf sangat efisien karena satker berhasil mencatatkan rekor waktu tercepat pada aplikasi kinerja."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Profesionalisme butir keempat menegaskan kewajiban: memperhatikan kecepatan dan akurasi untuk memperoleh hasil kinerja dengan kualitas terbaik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kecepatan kerja tanpa dibarengi dengan ketelitian dan akurasi verifikasi material merupakan kecerobohan berbahaya yang meruntuhkan keandalan sistem perbendaharaan negara. Menyelesaikan dokumen dalam jumlah banyak secara membabi buta tanpa pengujian data menimbulkan risiko fatal kebocoran kas negara dan pelanggaran hukum perbendaharaan. Butir keempat perilaku efektif profesionalisme secara eksplisit menuntut perpaduan dwitunggal antara aspek kecepatan (speed) dan aspek akurasi (accuracy) demi menghasilkan kualitas keluaran terbaik. Oleh karena itu, evaluasi pada opsi A secara tepat membuktikan bahwa mengorbankan akurasi demi kecepatan semu adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>A. Pendekatan staf keliru karena profesionalisme menuntut keseimbangan antara kecepatan dan akurasi kualitas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena kecepatan yang menghasilkan kesalahan salah transfer merusak akuntabilitas keuangan publik.</li><li><strong>C</strong>: Keliru karena tanggung jawab verifikasi perbendaharaan melekat pada pejabat penguji, bukan bank persepsi.</li><li><strong>D</strong>: Keliru karena penandatanganan buta tanpa membaca isi berkas adalah kelalaian tugas berat, bukan ketangkasan.</li><li><strong>E</strong>: Keliru karena rekor kecepatan administratif tidak bermakna ketika menghasilkan kerugian keuangan negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan Perilaku Efektif yang mencerminkan nilai Integritas (selaras Akuntabel dan Loyal) sebagaimana diatur dalam Keputusan Menteri Keuangan Nomor 429/KMK.01/2022?", "options": ["Menerapkan budaya kerja transparan, sesuai perkataan dan perbuatan serta menjaga nama baik individu dan institusi.", "Menerapkan perilaku jujur dalam tugas, memegang teguh kebenaran, dan berani mengemukakan fakta dengan pantas.", "Menuntut pemberian persenan uang suap dari setiap vendor rekanan sebagai syarat kelulusan berkas verifikasi dinas.", "Berupaya menghindari konflik kepentingan dan menjunjung tinggi kode etik serta tidak menyalahgunakan wewenang.", "Melaksanakan tugas dan tanggung jawab pekerjaan dengan berdedikasi penuh semangat demi membangun bangsa negara."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Integritas: transparan, jujur/fakta pantas, disiplin tanpa pengawasan, hindari konflik kepentingan/tidak salah gunakan wewenang, jaga rahasia & BMN, dedikasi membangun bangsa.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Meminta atau memeras bagian komisi uang suap dari rekanan penyedia jasa merupakan tindak pidana korupsi yang mencoreng marwah institusi pengelola fiskal negara dan menghancurkan integritas aparatur sipil negara. Perbuatan melawan hukum tersebut merupakan antitesis total dari nilai Integritas, Akuntabel, dan Loyal yang mengamanatkan kejujuran mutlak dan larangan penyalahgunaan wewenang jabatan. Butir-butir resmi Perilaku Efektif nilai Integritas secara konsisten memerintahkan penghindaran konflik kepentingan dan pengawalan kode etik. Dengan demikian, pemerasan uang suap pada opsi C jelas merupakan kejahatan jabatan yang sama sekali bukan perilaku efektif nilai integritas.</p><p>Jawaban yang sesuai adalah <strong>C. Menuntut pemberian persenan uang suap dari setiap vendor rekanan sebagai syarat kelulusan berkas verifikasi dinas.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Perilaku efektif integritas sah mengenai transparansi perkataan dan perbuatan sesuai butir pertama aturan.</li><li><strong>B</strong>: Perilaku efektif integritas sah mengenai keberanian menyampaikan fakta pantas sesuai butir kedua regulasi.</li><li><strong>D</strong>: Perilaku efektif integritas sah mengenai larangan konflik kepentingan dan penyalahgunaan wewenang dinas.</li><li><strong>E</strong>: Perilaku efektif integritas sah mengenai dedikasi penuh semangat membangun bangsa sesuai butir keenam.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Aplikasi", "question": "Ketika menemukan anomali penggelembungan anggaran pada draf pengadaan seksi lain, seorang staf muda ingin menyampaikan kebenaran tersebut secara etis. Berdasarkan butir kedua Perilaku Efektif nilai Integritas, cara penyampaian yang paling tepat adalah...", "options": ["Menyebarkan foto dokumen anomali tersebut ke akun gosip media sosial dengan membubuhkan fitnah pribadi atasan.", "Mengemukakan fakta temuan secara jujur dengan cara yang pantas, berbasis bukti data, melalui saluran resmi kedinasan.", "Meneriaki kepala seksi pengadaan di lorong kantor pelayanan saat jam ramai kunjungan masyarakat pengguna layanan.", "Memeras panitia pengadaan agar memberikan uang tutup mulut sebesar lima juta rupiah kepada staf bersangkutan.", "Mendiamkan anomali penggelembungan dana tersebut demi menjaga hubungan pertemanan akrab dengan staf pengadaan kantor."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Integritas butir kedua: Menerapkan perilaku jujur dalam pelaksanaan tugas, memegang teguh kebenaran, dan berani mengemukakan fakta dengan pantas pada kondisi yang tepat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keberanian moral menegakkan kebenaran harus diimbangi dengan kebijaksanaan tata krama dan kepatuhan terhadap saluran komunikasi kedinasan yang sah agar solusi substantif dapat dicapai tanpa menimbulkan kegaduhan destruktif. Mengemukakan fakta anomali anggaran secara tenang, objektif, didukung bukti kertas kerja yang valid, dan disampaikan secara pantas kepada pimpinan atau Unit Kepatuhan Internal merupakan perwujudan ksatria aparatur berintegritas. Rumusan perilaku efektif butir kedua secara tegas memadukan unsur 'berani mengemukakan fakta' dengan 'cara yang pantas pada kondisi yang tepat'. Oleh sebab itu, pelaporan terukur pada opsi B adalah aplikasi integritas yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>B. Mengemukakan fakta temuan secara jujur dengan cara yang pantas, berbasis bukti data, melalui saluran resmi kedinasan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena membocorkan dokumen ke akun gosip melanggar rahasia jabatan dan etika media sosial.</li><li><strong>C</strong>: Keliru karena berteriak di ruang publik merusak ketertiban ruang pelayanan dan melanggar kesantunan dinas.</li><li><strong>D</strong>: Keliru karena meminta uang tutup mulut merupakan kejahatan pemerasan dan korupsi penerimaan gratifikasi.</li><li><strong>E</strong>: Keliru karena mendiamkan kecurangan anggaran demi pertemanan merupakan bentuk pembiaran korupsi fatal.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka program Knowledge Sharing mingguan di tingkat seksi kantor yang mengoptimalkan sistem manajemen pengetahuan sesuai nilai Profesionalisme!", "options": ["Mewajibkan pegawai menghafal kamus bahasa asing tebal tanpa ada kaitannya dengan tugas operasional kementerian.", "Menyuruh seluruh staf junior membersihkan kendaraan dinas pejabat setiap hari jumat pagi sebelum jam pelayanan.", "Mengganti seluruh jam pelayanan publik dengan acara nonton bersama film bioskop komersial di aula ruang kantor.", "Sesi bedah regulasi baru, simulasi kasus pelayanan, penyusunan ringkasan teknis, dan pengunggahan ke repositori KMS.", "Mewajibkan pegawai membayar uang iuran mingguan kepada pimpinan seksi guna membeli makanan ringan rapat dinas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Profesionalisme mendorong pemanfaatan Knowledge Management System (KMS), kegigihan belajar, dan saling membantu belajar demi peningkatan kompetensi kerja tuntas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengembangan kompetensi aparatur yang berkesinambungan membutuhkan ekosistem transfer pengetahuan yang terstruktur, praktis, dan terdokumentasi rapi dalam basis data institusi. Penyelenggaraan sesi bedah aturan baru yang dipadukan dengan simulasi pemecahan masalah riil pelayanan, pembuatan panduan ringkas, serta pengunggahan arsip digital ke repositori KMS memastikan seluruh insan unit kerja dapat mengakses ilmu pengetahuan kapan pun dibutuhkan. Sintesis kerangka program edukasi pada opsi D secara tepat mengoperasionalkan mandat perilaku efektif kompeten dan profesionalisme ke dalam aksi nyata satuan kerja.</p><p>Jawaban yang sesuai adalah <strong>D. Sesi bedah regulasi baru, simulasi kasus pelayanan, penyusunan ringkasan teknis, dan pengunggahan ke repositori KMS.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penghafalan kamus tanpa relevansi tugas operasional membuang waktu dan energi kerja pegawai.</li><li><strong>B</strong>: Keliru karena pembersihan kendaraan pribadi pejabat menyalahgunakan tenaga aparatur di luar tugas dinas.</li><li><strong>C</strong>: Keliru karena penutupan loket layanan publik demi hiburan film komersial melanggar hak masyarakat pengguna.</li><li><strong>E</strong>: Keliru karena pungutan iuran wajib tanpa dasar hukum merupakan bentuk pungutan liar di lingkungan kerja.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 41", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah mekanisme pengendalian intern pengamanan data dan Barang Milik Negara (BMN) pada satuan kerja guna mewujudkan perilaku efektif akuntabel!", "options": ["Membiarkan seluruh kata sandi peladen komputer tertulis pada secarik kertas di pintu masuk lobi depan kantor dinas.", "Menjual seluruh perangkat komputer kantor yang baru dibeli kepada pedagang pasar loak demi mengejar efisiensi.", "Mengizinkan seluruh keluarga staf membawa pulang proyektor dan peladen komputer dinas untuk keperluan hiburan.", "Melarang seluruh staf menyentuh komputer dinas dan mengharuskan pencatatan anggaran kasir memakai buku tulis.", "Penerapan hak akses data berjenjang, enkripsi dokumen, inventarisasi fisik BMN berkala, dan penegakan pakta BMN."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 41", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 41</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Integritas butir kelima menuntut kesadaran menjaga kerahasiaan, keamanan data/informasi, dan tanggung jawab penuh dalam penggunaan Barang Milik Negara.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengamanan data fiskal yang sensitif dan aset fisik BMN menuntut sistem pertahanan berlapis yang mengombinasikan tata kelola keamanan siber dengan pengawasan fisik inventaris negara. Penerapan pembagian hak akses pengguna komputer berdasarkan wewenang jabatan, enkripsi lalu lintas dokumen digital rahasia, audit fisik aset BMN secara berkala, serta penandatanganan pakta tanggung jawab pemegang aset menjamin integritas perbendaharaan negara tetap terlindungi dari ancaman kebocoran maupun penyelewengan. Sintesis kerangka pengendalian pada opsi E menyajikan arsitektur keamanan data dan BMN yang paling kokoh dan akuntabel.</p><p>Jawaban yang sesuai adalah <strong>E. Penerapan hak akses data berjenjang, enkripsi dokumen, inventarisasi fisik BMN berkala, dan penegakan pakta BMN.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena membiarkan kata sandi di area publik merupakan kecerobohan fatal keamanan sistem siber.</li><li><strong>B</strong>: Keliru karena penjualan aset negara secara ilegal merupakan tindak pidana penggelapan dan korupsi aset BMN.</li><li><strong>C</strong>: Keliru karena peminjaman BMN untuk hiburan pribadi keluarga melanggar larangan penggunaan aset dinas.</li><li><strong>D</strong>: Keliru karena pelarangan komputer mencerminkan kemunduran teknologi primitif yang merusak produktivitas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 41.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Analitis", "question": "Pada penyelarasan nilai Harmonis dan Kolaboratif dengan nilai Sinergi, Sikap Dasar dirumuskan sebagai: senantiasa solid, proaktif, berkolaborasi, dan humanis. Bagaimanakah korelasi logis sikap 'humanis' dalam memperkuat kolaborasi kerja lintas unit?", "options": ["Sikap humanis mewajibkan pimpinan memberikan pinjaman dana tunai pribadi tanpa batas kepada seluruh bawahan.", "Sikap humanis menuntut agar seluruh pegawai kementerian dibebaskan dari kewajiban mematuhi jam kerja kantor dinas.", "Sikap humanis bermakna bahwa setiap konflik penugasan dinas harus diselesaikan melalui pemungutan suara umum.", "Sikap humanis menempatkan empati dan penghargaan martabat manusia sebagai jembatan pembangun rasa saling percaya.", "Sikap humanis bertujuan menghapus batas kewenangan hukum formal antar-direktorat jenderal di kementerian negara."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sikap Dasar Sinergi (Harmonis & Kolaboratif): senantiasa solid, proaktif, berkolaborasi, dan humanis; memperlakukan rekan dan mitra dengan empati dan penghargaan kemanusiaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kolaborasi birokrasi bukanlah transaksi mekanis antar-mesin, melainkan interaksi antar-manusia yang sarat dengan dinamika psikologis, emosi, dan kebutuhan akan rasa aman. Pendekatan humanis yang mengedepankan empati, kesediaan mendengarkan dengan tulus, serta penghormatan terhadap harkat kemanusiaan rekan kerja mampu mencairkan ketegangan ego sektoral dan melahirkan modal sosial berupa rasa saling percaya yang kokoh. Uraian materi KMK 429/2022 menempatkan sikap humanis berdampingan erat dengan sikap proaktif dan solid demi menciptakan sinergi berkualitas tinggi. Oleh sebab itu, opsi D menyajikan analisis sosiologis sikap humanis secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>D. Sikap humanis menempatkan empati dan penghargaan martabat manusia sebagai jembatan pembangun rasa saling percaya.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena sikap humanis berkaitan dengan etika hubungan kemanusiaan, bukan pemberian utang privat.</li><li><strong>B</strong>: Keliru karena ketaatan pada jam kerja kedinasan tetap merupakan kewajiban disiplin mutlak aparatur negara.</li><li><strong>C</strong>: Keliru karena penyelesaian masalah kerja harus berlandaskan regulasi dan SOP, bukan semata voting terbuka.</li><li><strong>E</strong>: Keliru karena koordinasi humanis tetap menghormati batas yurisdiksi dan kewenangan hukum masing-masing unit.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Aplikasi", "question": "Dalam sebuah gugus tugas penyusunan profil risiko fiskal daerah, terdapat perdebatan tajam akibat perbedaan latar belakang keahlian antara analis pajak dan analis perbendaharaan. Berdasarkan butir kelima Perilaku Efektif nilai Sinergi, sikap yang harus diambil tim adalah...", "options": ["Membubarkan gugus tugas tersebut dan membiarkan laporan profil risiko fiskal daerah tidak terselesaikan selamanya.", "Mampu mengelola perbedaan sebagai peluang untuk memperkaya analisis dan menghasilkan solusi terbaik bersama.", "Meminta salah satu perwakilan analis keluar dari keanggotaan tim kerja demi memenangkan pendapat sepihak saja.", "Mengabaikan seluruh data statistik perpajakan dan hanya menggunakan catatan transaksi kas perbendaharaan kantor.", "Menyerahkan penyusunan draf laporan kepada kantor konsultan swasta dengan membebankan biaya anggaran dinas."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Sinergi butir kelima menegaskan kemampuan pegawai untuk: Mampu mengelola perbedaan sebagai peluang untuk memberikan solusi dan hasil terbaik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Keberagaman perspektif keilmuan dalam tim kerja lintas fungsi bukanlah ancaman perpecahan, melainkan aset intelektual yang sangat berharga untuk menghasilkan analisis kebijakan yang multidimensional dan komprehensif. Menyatukan sudut pandang perpajakan dan perbendaharaan melalui dialog konstruktif akan menutup titik buta (blind spots) dalam mitigasi risiko fiskal daerah, sehingga produk akhir menjadi jauh lebih akurat dan solutif. Butir kelima Perilaku Efektif nilai Sinergi secara gamblang mengamanatkan aparatur untuk mengelola perbedaan sudut pandang sebagai batu loncatan menuju solusi terbaik. Maka dari itu, tindakan integratif pada opsi B adalah aplikasi perilaku efektif yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>B. Mampu mengelola perbedaan sebagai peluang untuk memperkaya analisis dan menghasilkan solusi terbaik bersama.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena membubarkan tim akibat perbedaan pendapat mencerminkan keputusasaan manajerial fatal.</li><li><strong>C</strong>: Keliru karena mengusir anggota tim yang berbeda pandangan merusak asas inklusivitas dan kolaborasi.</li><li><strong>D</strong>: Keliru karena membuang data perpajakan menghasilkan analisis sepihak yang bias dan tidak akurat.</li><li><strong>E</strong>: Keliru karena melempar tugas pokok kepada pihak luar swasta merupakan pemborosan dan lari dari amanah.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat fungsional membagikan data estimasi defisit anggaran mentah yang belum divalidasi ke grup koordinasi instansi luar sehingga memicu kepanikan pasar finansial. Mengapa tindakan pejabat tersebut KELIRU?", "options": ["Tindakan pejabat sangat terpuji karena transparansi data mentah merupakan bentuk kebebasan informasi mutlak.", "Tindakan pejabat dapat dibenarkan sepanjang pasar finansial berhasil melakukan pemulihan indeks secara mandiri.", "Tindakan pejabat sangat bijak dalam rangka menguji kecepatan respons investor saham dalam menanggapi krisis.", "Tindakan pejabat mencerminkan kepeloporan keterbukaan birokrasi yang harus ditiru oleh kementerian lainnya.", "Tindakan pejabat keliru karena koordinasi sinergi mewajibkan berbagi data yang telah dipastikan keakuratannya."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Sinergi butir kedua mewajibkan: Bersikap proaktif dalam membangun koordinasi efektif termasuk berbagi data/informasi yang telah dipastikan keakuratannya untuk memberikan solusi terbaik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penyebaran data keuangan negara yang masih mentah, belum teruji, dan belum terekonsiliasi ke ruang publik atau instansi eksternal merupakan kecerobohan fatal yang membahayakan stabilitas moneter dan persepsi pasar atas tata kelola pemerintah. Keterbukaan informasi dan koordinasi sinergi harus selalu berlandaskan prinsip kehati-hatian akuntansi dan verifikasi kebenaran materiil agar informasi yang dibagikan benar-benar menjadi rujukan solusi yang kredibel. Panduan Perilaku Efektif nilai Sinergi secara kategoris menggariskan bahwa data kedinasan yang dibagikan wajib telah dipastikan keakuratannya terlebih dahulu. Oleh sebab itu, evaluasi pada opsi E membuktikan bahwa perbuatan tersebut adalah pelanggaran berat kode perilaku.</p><p>Jawaban yang sesuai adalah <strong>E. Tindakan pejabat keliru karena koordinasi sinergi mewajibkan berbagi data yang telah dipastikan keakuratannya.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena transparansi data fiskal wajib melewati prosedur validasi resmi demi akuntabilitas negara.</li><li><strong>B</strong>: Keliru karena pemulihan pasar finansial tidak menghapus status kelalaian fatal pejabat pembocor data.</li><li><strong>C</strong>: Keliru karena pasar finansial dan kepercayaan investor bukanlah sarana kelinci percobaan uji kepanikan.</li><li><strong>D</strong>: Keliru karena penyebaran informasi palsu atau belum teruji bertolak belakang dengan kepeloporan positif.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Aplikasi", "question": "Seorang pelaku usaha mikro datang ke kantor pelayanan perbendaharaan dan kebingungan mengisi formulir digital pencairan dana hibah pemerintah. Berdasarkan butir pertama Perilaku Efektif nilai Pelayanan, tindakan petugas yang paling tepat adalah...", "options": ["Memberikan layanan yang memudahkan, mendampingi pengisian dengan ramah, dan tanggap menuntaskan kebutuhan.", "Menyuruh pelaku usaha tersebut pulang ke rumah dan melarangnya datang kembali sebelum mahir teknologi komputer.", "Meminta imbalan uang tunai sebesar dua ratus ribu rupiah sebagai upah jasa pengisian formulir digital kantor.", "Membentak pelaku usaha di depan antrean loket karena dianggap memperlambat catatan waktu pelayanan petugas.", "Menyobek berkas permohonan hibah milik pelaku usaha dan membuangnya ke tempat sampah ruang tunggu kantor."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Pelayanan (Berorientasi Pelayanan): Memberikan layanan yang adil, memudahkan, dan tanggap dalam menindaklanjuti kebutuhan pemangku kepentingan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Hakikat utama dari transformasi digital pelayanan publik adalah untuk memudahkan dan membahagiakan masyarakat, bukan untuk menciptakan barikade teknologis baru yang menyingkirkan pelaku usaha kecil yang belum melek teknologi. Sikap petugas yang berinisiatif mendampingi dengan ramah, memandu pengisian data digital secara sabar, dan memberikan solusi konkret mencerminkan keluhuran etos melayani sepenuh hati. Rumusan Perilaku Efektif nilai Pelayanan butir pertama secara tegas mewajibkan aparatur memberikan layanan yang memudahkan dan tanggap terhadap kebutuhan stakeholder. Dengan demikian, tindakan pendampingan solutif pada opsi A adalah aplikasi pelayanan prima yang paling sempurna.</p><p>Jawaban yang sesuai adalah <strong>A. Memberikan layanan yang memudahkan, mendampingi pengisian dengan ramah, dan tanggap menuntaskan kebutuhan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena mengusir masyarakat kecil yang butuh bantuan melanggar hak pelayanan publik warga negara.</li><li><strong>C</strong>: Keliru karena memungut biaya jasa pendampingan merupakan tindak pidana korupsi pungutan liar loket.</li><li><strong>D</strong>: Keliru karena membentak pemohon mencerminkan kezaliman birokrasi yang melanggar kode etik kesopanan.</li><li><strong>E</strong>: Keliru karena merusak berkas permohonan warga negara merupakan tindak pidana perusakan dokumen resmi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Analitis", "question": "Pada penyelarasan nilai Berorientasi Pelayanan dengan nilai Pelayanan, Sikap Dasar dirumuskan sebagai: senantiasa komunikatif, respektif, responsif, cekatan, dan solutif. Bagaimanakah keterkaitan logis sikap 'respektif' dalam menumbuhkan kepuasan pemangku kepentingan?", "options": ["Sikap respektif bermakna petugas wajib membungkukkan badan hingga menyentuh lantai setiap kali ada tamu dinas.", "Sikap respektif menuntut agar seluruh permohonan izin ekspor impor disetujui tanpa perlu melewati verifikasi audit.", "Sikap respektif menumbuhkan rasa dihargai pada pengguna layanan sehingga terbangun hubungan kemitraan positif.", "Sikap respektif mewajibkan kantor pelayanan memberikan hidangan makanan prasmanan mewah kepada setiap pengunjung.", "Sikap respektif bertujuan menghapus seluruh persyaratan dokumen identitas diri pemohon layanan perizinan."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sikap Dasar Pelayanan: senantiasa komunikatif, respektif, responsif, cekatan, dan solutif; sikap respektif mencerminkan penghormatan tulus kepada martabat pengguna layanan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kepuasan masyarakat pengguna layanan publik tidak semata-mata ditentukan oleh cepatnya penyelesaian berkas fisik, melainkan sangat dipengaruhi oleh pengalaman psikologis bagaimana mereka diperlakukan oleh petugas di ruang pelayanan. Sikap respektif yang memancarkan rasa hormat yang tulus, mendengarkan tanpa memotong pembicaraan, dan menghargai hak martabat pemohon melahirkan rasa dihargai yang mendalam pada diri warga negara. Uraian materi menempatkan sikap respektif berdampingan dengan sikap responsif dan solutif sebagai pilar pelayanan terbaik. Oleh karenanya, opsi C memberikan analisis kausalitas psikologis yang paling tepat dan meyakinkan.</p><p>Jawaban yang sesuai adalah <strong>C. Sikap respektif menumbuhkan rasa dihargai pada pengguna layanan sehingga terbangun hubungan kemitraan positif.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kesopanan pelayanan tidak diwujudkan melalui gestur fisik berlebihan yang merendahkan diri.</li><li><strong>B</strong>: Keliru karena penghormatan kepada pengguna layanan tidak boleh mengorbankan kepatuhan verifikasi aturan.</li><li><strong>D</strong>: Keliru karena kepuasan layanan publik bersumber pada kepastian prosedur, bukan jamuan makan mewah.</li><li><strong>E</strong>: Keliru karena verifikasi identitas diri merupakan instrumen wajib akuntabilitas hukum administrasi negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Evaluatif", "question": "Sebuah seksi pelayanan menolak memanfaatkan aplikasi digital pengarsipan baru yang telah ditetapkan kantor pusat dan bersikukuh memakai buku besar tulis manual dengan alasan tradisi kerja. Mengapa sikap seksi tersebut KELIRU?", "options": ["Sikap seksi sangat tepat karena buku tulis manual terbukti seratus persen aman dari bahaya serangan gempa bumi.", "Sikap seksi keliru karena nilai adaptif menuntut fleksibilitas, keterbukaan pada inovasi, dan kemajuan teknologi.", "Sikap seksi sangat bijak dalam rangka melestarikan pabrik kertas lokal agar tidak mengalami penurunan omzet bisnis.", "Sikap seksi dapat dibenarkan sepanjang kepala seksi bersangkutan memiliki tulisan tangan kaligrafi yang indah.", "Sikap seksi mencerminkan keteguhan memegang tradisi luhur masa lalu yang harus diapresiasi oleh menteri keuangan."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Adaptif/Kesempurnaan mewajibkan: Memeriksa kembali dan memperbarui informasi secara rutin, termasuk mengikuti perkembangan teknologi, serta bersikap fleksibel, adaptif, dan terbuka terhadap usulan perubahan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Inersia birokrasi dan penolakan terhadap modernisasi sistem digital dengan berlindung di balik alasan tradisi merupakan bentuk pembangkangan terhadap efisiensi yang memperlambat kinerja kementerian. Di era revolusi teknologi informasi, ketidakmampuan beradaptasi dengan aplikasi digital pengarsipan menimbulkan risiko kehilangan data fisik, keterlambatan pelaporan, dan inefisiensi biaya operasional yang merugikan keuangan negara. Landasan Perilaku Efektif nilai Adaptif secara tegas mewajibkan aparatur bersikap fleksibel, adaptif, dan aktif mengikuti perkembangan teknologi baru demi kesempurnaan proses kerja. Maka dari itu, penilaian pada opsi B membuktikan secara tajam bahwa resistensi tersebut adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>B. Sikap seksi keliru karena nilai adaptif menuntut fleksibilitas, keterbukaan pada inovasi, dan kemajuan teknologi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena arsip fisik buku manual justru sangat rentan hancur terbakar, basah, dan lapuk dimakan usia.</li><li><strong>C</strong>: Keliru karena tujuan tata kelola birokrasi adalah efisiensi pelayanan negara, bukan mensubsidi pabrik kertas.</li><li><strong>D</strong>: Keliru karena keindahan tulisan tangan tidak sebanding dengan kecepatan pencarian data arsip digital modern.</li><li><strong>E</strong>: Keliru karena tradisi birokrasi yang inefisien wajib ditinggalkan demi reformasi sistem yang produktif.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan butir Perilaku Efektif yang mencerminkan nilai Pelayanan (selaras Berorientasi Pelayanan) menurut Keputusan Menteri Keuangan Nomor 429/KMK.01/2022?", "options": ["Memberikan layanan yang adil, memudahkan, dan tanggap dalam menindaklanjuti kebutuhan pemangku kepentingan.", "Memberikan pelayanan prima secara akurat, tepat waktu, dan berdasarkan kompetensi yang dimiliki dan ditingkatkan.", "Bersikap responsif, cekatan dalam bertindak, dan senantiasa berfokus pada solusi terbaik bagi pengguna layanan dinas.", "Mempersulit alur birokrasi dengan menambah syarat-syarat fiktif yang tidak tercantum dalam standar operasional sah.", "Menerima masukan, melakukan evaluasi, dan melaksanakan perbaikan berkelanjutan demi layanan yang berkualitas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Pelayanan: layanan adil memudahkan tanggap, prima akurat tepat waktu berbasis kompetensi, responsif cekatan fokus solusi, terima masukan evaluasi perbaikan berkelanjutan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menambah-nambah persyaratan fiktif yang tidak berdasar hukum di luar standar operasional prosedur merupakan praktik maladministrasi penyalahgunaan wewenang yang sengaja diciptakan untuk memicu suap atau pemerasan kepada masyarakat. Perilaku menyimpang tersebut bertolak belakang secara diametral dengan esensi nilai Pelayanan yang mengamanatkan kemudahan, keadilan, dan ketepatan waktu bagi pemangku kepentingan. Teks resmi KMK 429/2022 secara konsisten mendorong penyederhanaan alur layanan dan perbaikan berkesinambungan. Oleh sebab itu, tindakan mempersulit prosedur pada opsi D jelas merupakan perbuatan terlarang yang sama sekali bukan butir perilaku efektif nilai pelayanan.</p><p>Jawaban yang sesuai adalah <strong>D. Mempersulit alur birokrasi dengan menambah syarat-syarat fiktif yang tidak tercantum dalam standar operasional sah.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Perilaku efektif pelayanan sah mengenai layanan adil, memudahkan, dan tanggap sesuai butir pertama aturan.</li><li><strong>B</strong>: Perilaku efektif pelayanan sah mengenai layanan prima akurat tepat waktu sesuai butir kedua regulasi.</li><li><strong>C</strong>: Perilaku efektif pelayanan sah mengenai sikap responsif, cekatan, dan fokus solusi sesuai materi regulasi.</li><li><strong>E</strong>: Perilaku efektif pelayanan sah mengenai keterbukaan evaluasi dan perbaikan berkelanjutan sesuai aturan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Aplikasi", "question": "Ketika menghadapi beban lonjakan verifikasi laporan tahunan yang meningkat tiga kali lipat, seorang kepala seksi mengapresiasi ide otomatisasi bot komputer yang diajukan stafnya untuk mempercepat proses. Tindakan kepala seksi tersebut merupakan aplikasi Perilaku Efektif apa?", "options": ["Tindakan melarikan diri dari tanggung jawab pimpinan untuk memeriksa berkas laporan secara manual satu per satu.", "Upaya memanjakan staf bawahan agar tidak perlu bekerja keras dalam mengabdi kepada bangsa dan negara dinas.", "Penerapan strategi pemborosan anggaran kantor guna membeli lisensi perangkat lunak luar negeri yang mahal.", "Tindakan menyerahkan kerahasiaan data keuangan kementerian kepada pengembang teknologi kecerdasan buatan luar dinas.", "Memanfaatkan situasi tantangan dan mengapresiasi kreativitas untuk mengembangkan proses kerja menuju kesempurnaan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Kesempurnaan (Adaptif) butir pertama: Memanfaatkan situasi tantangan dan mengapresiasi kreativitas untuk mengembangkan proses kerja menuju kesempurnaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kepemimpinan yang adaptif memandang krisis lonjakan beban kerja bukan sebagai hambatan yang melumpuhkan, melainkan sebagai pemicu (catalyst) untuk berinovasi dan merekayasa ulang proses bisnis agar lebih ramping dan modern. Mengapresiasi dan mengadopsi ide otomatisasi digital dari bawahan membuktikan kematangan pimpinan dalam menghargai kreativitas tim demi mendongkrak kapasitas layanan organisasi publik. Butir pertama Perilaku Efektif Adaptif/Kesempurnaan secara presisi mengamanatkan pemanfaatan tantangan dan apresiasi kreativitas untuk penyempurnaan proses kerja. Dengan demikian, respons pimpinan pada opsi E secara akurat mengaplikasikan butir perilaku efektif tersebut.</p><p>Jawaban yang sesuai adalah <strong>E. Memanfaatkan situasi tantangan dan mengapresiasi kreativitas untuk mengembangkan proses kerja menuju kesempurnaan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pemanfaatan otomasi digital bertujuan meningkatkan akurasi kontrol, bukan melarikan diri.</li><li><strong>B</strong>: Keliru karena otomatisasi membebaskan staf dari beban mekanis repetitif untuk fokus pada analisis analitis.</li><li><strong>C</strong>: Keliru karena pengembangan bot internal staf justru menghemat anggaran pengadaan perangkat lunak vendor.</li><li><strong>D</strong>: Keliru karena otomatisasi internal yang dirancang staf diawasi secara ketat dalam infrastruktur aman kantor.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah protokol koordinasi penanganan darurat rekonsiliasi data fiskal antara seksi penerimaan dan seksi perbendaharaan berbasis nilai Sinergi yang transparan!", "options": ["Pertemuan klarifikasi data bersama, verifikasi bukti transaksi sah, penyusunan berita acara rekonsiliasi, dan solusi koreksi.", "Masing-masing seksi saling mengunci basis data komputer dan menolak berbicara satu sama lain selama satu minggu kerja.", "Menyelesaikan selisih rekonsiliasi dengan memalsukan angka pembukuan pada lembar kas akhir tanpa adanya bukti setor.", "Menjatuhkan sanksi denda uang tunai kepada seksi yang mencatatkan angka lebih rendah tanpa melakukan telaah data.", "Menyerahkan penyelesaian selisih pembukuan kas negara kepada dukun peramal angka di sekitar area gedung kantor."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Sinergi menuntut kolaborasi harmonis diawali sikap transparan dan terbuka, proaktif berbagi data terverifikasi, dan menyelesaikan masalah bersama demi hasil terbaik.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Penanganan selisih data antarunit dalam tata kelola perbendaharaan negara memerlukan mekanisme resolusi yang objektif, transparan, dan berlandaskan bukti dokumen yang sah (source documents). Alur kerja yang mengintegrasikan pertemuan klarifikasi terbuka, pencocokan bukti transaksi, penyusunan berita acara rekonsiliasi resmi, serta perumusan jurnal koreksi yang akuntabel berhasil menuntaskan anomali tanpa memicu konflik personal antarunit kerja. Sintesis protokol koordinasi pada opsi A secara sempurna merefleksikan nilai Sinergi dan Kolaboratif yang diamanatkan dalam KMK 429/2022.</p><p>Jawaban yang sesuai adalah <strong>A. Pertemuan klarifikasi data bersama, verifikasi bukti transaksi sah, penyusunan berita acara rekonsiliasi, dan solusi koreksi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena penguncian akses dan pemutusan komunikasi merusak tata kelola perbendaharaan negara.</li><li><strong>C</strong>: Keliru karena manipulasi angka tanpa bukti transaksi sah merupakan kejahatan pemalsuan laporan keuangan.</li><li><strong>D</strong>: Keliru karena penjatuhan sanksi denda sepihak tanpa telaah audit melanggar keadilan administrasi kedinasan.</li><li><strong>E</strong>: Keliru karena menyerahkan akuntansi negara kepada peramal adalah tindakan irasional yang merusak wibawa institusi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 42", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah kerangka manajemen umpan balik (feedback loop) pelayanan publik pada unit kantor terpadu yang menjamin perbaikan mutu berkelanjutan!", "options": ["Menyediakan kotak saran fisik namun mengunci gemboknya secara permanen dan membuang anak kuncinya ke dalam sungai.", "Merekam seluruh identitas warga pengkritik untuk dimasukkan ke dalam daftar hitam penolakan pelayanan seumur hidup.", "Kanal survei kepuasan digital, analisis keluhan mingguan, tindak lanjut perbaikan SOP, dan publikasi transparansi evaluasi.", "Mewajibkan warga membayar tarif uang retribusi pengaduan sebelum keluhannya boleh didengarkan oleh petugas loket dinas.", "Mengalihkan seluruh nomor saluran bantuan telepon kantor pelayanan ke sambungan faksimile yang tidak aktif dinas kantor."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 42", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 42</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Pelayanan butir keempat: Menerima masukan, melakukan evaluasi, dan melaksanakan perbaikan secara berkelanjutan untuk memberikan layanan yang semakin berkualitas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pengelolaan kualitas pelayanan publik modern mensyaratkan adanya mekanisme penangkapan aspirasi masyarakat yang terintegrasi langsung ke dalam siklus pengambilan keputusan perbaikan sistem kerja. Menyediakan instrumen survei kepuasan pelanggan secara digital, menelaah keluhan mingguan dalam forum manajerial, merevisi standar prosedur yang terbukti menghambat, serta mempublikasikan hasil evaluasi secara transparan membuktikan ketulusan institusi dalam berorientasi pada kepuasan pengguna. Sintesis kerangka manajemen pada opsi C secara paripurna mewujudkan mandat Perilaku Efektif nilai Pelayanan KMK 429/2022.</p><p>Jawaban yang sesuai adalah <strong>C. Kanal survei kepuasan digital, analisis keluhan mingguan, tindak lanjut perbaikan SOP, dan publikasi transparansi evaluasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penyediaan kotak saran palsu yang terkunci merupakan kemunafikan birokrasi pembodohan publik.</li><li><strong>B</strong>: Keliru karena memasukkan warga pengkritik ke daftar hitam merupakan bentuk intimidasi jabatan yang melanggar hukum.</li><li><strong>D</strong>: Keliru karena pungutan tarif pengaduan merupakan pungutan liar yang melanggar hak partisipasi masyarakat.</li><li><strong>E</strong>: Keliru karena memutus saluran telepon pengaduan menabrak asas keterbukaan dan akuntabilitas pelayanan publik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 42.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Analitis", "question": "Materi pada halaman 43 menguraikan perilaku efektif: membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus. Bagaimanakah korelasi budaya analitika data dengan continuous improvement tata kelola kementerian?", "options": ["Analitika data hanya bertujuan mempermudah pimpinan unit kerja untuk memotong tunjangan lembur seluruh bawahan.", "Analisis data empiris memberikan bukti objektif mengenai titik inefisiensi sehingga perbaikan tepat sasaran.", "Pemanfaatan data ditujukan untuk menghapus kewajiban pegawai dalam mematuhi norma etika kesopanan di kantor.", "Analitika data membebaskan aparatur kementerian dari kewajiban menyusun laporan pertanggungjawaban anggaran dinas.", "Budaya data dirancang agar seluruh arsip dokumen negara dapat diperjualbelikan secara bebas kepada pihak swasta."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Kesempurnaan/Adaptif: Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus (continuous improvement) berbasis bukti nyata.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Perbaikan tata kelola birokrasi yang berkelanjutan tidak dapat mengandalkan perasaan subjektif atau tebakan spekulatif, melainkan harus bertumpu pada bukti analitis data riil di lapangan. Dengan mengkaji data operasional—seperti durasi siklus layanan, frekuensi kesalahan dokumen, dan tren penerimaan negara—aparatur dapat mendeteksi akar masalah (root causes) inefisiensi secara presisi dan merancang intervensi perbaikan yang tepat sasaran. Teks materi halaman 43 secara eksplisit mengaitkan pemanfaatan data dengan perbaikan tugas yang berkesinambungan. Maka dari itu, opsi B menyajikan analisis korelasi ilmiah budaya analitika data secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>B. Analisis data empiris memberikan bukti objektif mengenai titik inefisiensi sehingga perbaikan tepat sasaran.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena tujuan analisis data adalah optimasi proses bisnis, bukan instrumen pemotongan hak pegawai.</li><li><strong>C</strong>: Keliru karena profesionalisme analitika data tetap wajib menjunjung tinggi etika dan integritas kedinasan.</li><li><strong>D</strong>: Keliru karena pemanfaatan data justru memperkuat akuntabilitas laporan pertanggungjawaban anggaran dinas.</li><li><strong>E</strong>: Keliru karena data fiskal adalah rahasia negara Republik Indonesia yang dilarang keras diperjualbelikan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Aplikasi", "question": "Seorang pejabat perencana anggaran diwajibkan memiliki visi yang maju agar mampu menyusun rencana yang relevan dan matang. Bentuk aplikasi nyata dari perilaku memiliki visi yang maju tersebut adalah...", "options": ["Menyalin secara bulat-bulat dokumen rencana anggaran lima tahun lalu tanpa memeriksa perubahan kondisi fiskal saat ini.", "Membuat proyeksi anggaran fiktif setinggi-tingginya agar sisa dana operasional kantor dapat dibagikan kepada staf seksi.", "Menolak menyusun rencana kerja tahunan dengan alasan masa depan perekonomian negara tidak dapat diprediksi manusia.", "Mengantisipasi dinamika tren ekonomi masa depan, merancang target mitigasi realistis, dan memeriksa kematangan rencana.", "Menyerahkan seluruh wewenang perencanaan belanja satuan kerja kepada pihak ketiga konsultan swasta asing tanpa telaah."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif nilai Kesempurnaan/Adaptif: Memiliki visi yang maju agar mampu menyusun rencana yang relevan dan matang, serta memeriksa hasil pekerjaan yang dilakukan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Memiliki visi yang maju (forward-looking vision) menuntut aparatur perencana untuk tidak terjebak dalam perangkap rutinitas administratif masa lalu, melainkan proaktif membaca sinyal perubahan tren ekonomi, teknologi, dan kebutuhan publik ke depan. Dengan mengantisipasi potensi gejolak fiskal, merumuskan target kinerja yang matang dan terukur, serta memvalidasi kesiapan implementasinya, perencanaan anggaran yang dihasilkan akan relevan dan memiliki daya tahan tinggi. Ketentuan perilaku efektif halaman 43 secara spesifik mengamanatkan aparatur memiliki visi maju dalam menyusun dan memeriksa rencana kerja. Oleh sebab itu, penerapan berwawasan masa depan pada opsi D adalah aplikasi yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>D. Mengantisipasi dinamika tren ekonomi masa depan, merancang target mitigasi realistis, dan memeriksa kematangan rencana.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menyalin rencana lama membuktikan ketiadaan visi dan mengabaikan dinamika fiskal riil.</li><li><strong>B</strong>: Keliru karena memalsukan proyeksi anggaran demi bonus privat merupakan tindak pidana korupsi perbendaharaan.</li><li><strong>C</strong>: Keliru karena menolak merencanakan tugas adalah bentuk kelalaian jabatan yang melanggar disiplin PNS.</li><li><strong>E</strong>: Keliru karena melempar wewenang perencanaan kepada pihak asing mengabaikan akuntabilitas kedaulatan fiskal.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Evaluatif", "question": "Seorang pimpinan unit kerja menetapkan kebijakan penghentian loket konsultasi tatap muka semata-mata berdasarkan firasat pribadinya tanpa pernah membaca dan menganalisis data kepuasan pengguna layanan. Mengapa keputusan pimpinan tersebut KELIRU?", "options": ["Keputusan pimpinan keliru karena perbaikan pekerjaan wajib berlandaskan membaca dan menganalisis data empiris riil.", "Keputusan pimpinan sangat tepat karena firasat batiniah seorang pejabat struktural selalu melampaui data statistik.", "Keputusan pimpinan dapat dibenarkan sepanjang anggaran operasional loket dapat dialihkan untuk belanja kendaraan dinas.", "Keputusan pimpinan mencerminkan ketegasan kepemimpinan otentik yang tidak boleh diintervensi oleh aspirasi masyarakat.", "Keputusan pimpinan sangat efisien karena satker berhasil menghemat tagihan listrik ruang tunggu pelayanan kantor dinas."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif halaman 43 mewajibkan: Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus; keputusan manajerial harus berbasis bukti (evidence-based).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Mengambil keputusan strategis yang berdampak luas pada hak publik hanya berdasarkan firasat subjektif tanpa telaah data merupakan praktik birokrasi serampangan yang melanggar asas profesionalisme dan rasionalitas tata kelola modern. Penghentian layanan tanpa dasar kajian data empiris memicu ketidakpuasan masyarakat, memutus akses konsultasi wajib pajak, dan berpotensi menurunkan kepatuhan fiskal secara nasional. Materi halaman 43 secara tegas menggariskan kewajiban membaca, menganalisis, dan memanfaatkan data sebagai fondasi penyempurnaan pekerjaan kedinasan. Oleh karena itu, evaluasi pada opsi A secara tepat membuktikan bahwa pengambilan keputusan nir-data tersebut adalah kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>A. Keputusan pimpinan keliru karena perbaikan pekerjaan wajib berlandaskan membaca dan menganalisis data empiris riil.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena firasat subjektif tanpa data ilmiah sangat rentan menghasilkan keputusan sesat yang merugikan publik.</li><li><strong>C</strong>: Keliru karena pengalihan anggaran pelayanan publik untuk belanja mobil pejabat melanggar etika anggaran.</li><li><strong>D</strong>: Keliru karena ketegasan kepemimpinan modern diukur dari akuntabilitas ilmiah, bukan kesewenang-wenangan.</li><li><strong>E</strong>: Keliru karena penghematan listrik minor tidak sebanding dengan hancurnya mutu pelayanan publik kementerian.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Analitis", "question": "Materi mencantumkan perilaku efektif: mendorong partisipasi aktif untuk mencari peluang perbaikan, mengembangkan dan mengimplementasikan cara-cara baru/inovatif dalam rangka perbaikan sistem secara komprehensif. Mengapa perbaikan sistem harus berorientasi 'komprehensif'?", "options": ["Agar kementerian dapat membatasi inovasi hanya pada perbaikan dekorasi tanaman hias di halaman depan kantor.", "Karena perbaikan komprehensif bertujuan menghapus seluruh fungsi regulasi perbendaharaan dan kepabeanan negara.", "Agar seluruh anggaran inovasi kementerian dapat disalurkan secara tunai kepada pengembang aplikasi swasta daerah.", "Karena perbaikan yang komprehensif membebaskan seluruh pegawai dari kewajiban mematuhi kode etik integritas dinas.", "Agar inovasi tidak bersifat tambal sulam parsial melainkan menyentuh akar proses bisnis secara menyeluruh dan langgeng."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif Kesempurnaan menuntut inovasi cara-cara baru dalam rangka perbaikan sistem secara komprehensif guna menghasilkan dampak transformasi yang menyeluruh, terintegrasi, dan berkelanjutan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Perbaikan yang bersifat parsial, sektoral, dan tambal sulam sering kali hanya menyelesaikan gejala di permukaan (symptom) sementara akar masalah struktural dalam sistem kerja tetap terabaikan dan memicu inefisiensi baru di unit lain. Pendekatan perbaikan komprehensif memastikan bahwa inovasi tata kelola menelaah keseluruhan rantai proses bisnis—mulai dari regulasi hulu, integrasi sistem teknologi, kompetensi pelaksana, hingga evaluasi kepuasan hilir—sehingga transformasi berjalan harmonis dan berkelanjutan. Teks materi halaman 43 secara spesifik mengamanatkan pengembangan inovasi demi perbaikan sistem yang komprehensif. Oleh sebab itu, opsi E menyajikan analisis urgensi inovasi menyeluruh secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>E. Agar inovasi tidak bersifat tambal sulam parsial melainkan menyentuh akar proses bisnis secara menyeluruh dan langgeng.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena inovasi komprehensif menyasar sistem proses bisnis substantif, bukan semata dekorasi tanaman.</li><li><strong>B</strong>: Keliru karena perbaikan sistem justru memperkuat kepatuhan dan keandalan regulasi perbendaharaan negara.</li><li><strong>C</strong>: Keliru karena inovasi birokrasi mengedepankan kemandirian dan efisiensi anggaran negara, bukan bagi-bagi dana.</li><li><strong>D</strong>: Keliru karena seluruh bentuk inovasi operasional wajib tunduk dan menjunjung tinggi kode etik integritas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Aplikasi", "question": "Seorang staf pemeriksa pajak baru saja merampungkan draf laporan hasil pemeriksaan wajib pajak yang tebal. Sebelum menyerahkan draf tersebut kepada atasannya, tindakan aplikasi yang mencerminkan perilaku efektif memeriksa hasil pekerjaan adalah...", "options": ["Langsung mengirimkan draf tersebut ke percetakan umum tanpa memeriksa kebenaran angka kalkulasi penetapan pajak.", "Menghapus lembar kertas kerja analisis demi menjaga agar draf laporan terlihat ringkas dan mudah dibawa pulang staf.", "Memeriksa kembali akurasi dasar hukum, konsistensi angka kalkulasi, serta kelengkapan bukti pendukung secara mandiri.", "Menyuruh petugas kebersihan kantor menandatangani lembar persetujuan akhir laporan hasil pemeriksaan dinas.", "Mengunggah draf laporan pemeriksaan pajak tersebut ke media sosial untuk meminta koreksi dari warganet internet dinas."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif halaman 43 butir ketiga mewajibkan: ...serta memeriksa hasil pekerjaan yang dilakukan secara teliti, akurat, dan bertanggung jawab sebelum diserahkan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kualitas profesionalisme aparatur tecermin dari kebiasaan melakukan pengujian kendali mutu mandiri (self-quality control) atas setiap produk kerja yang dihasilkannya sebelum diserahkan ke jenjang hierarki berikutnya. Memeriksa kembali konsistensi hitungan numerik, ketepatan klausul dasar hukum yang dirujuk, serta validitas bukti lampiran memitigasi risiko kekeliruan fatal yang dapat memicu sengketa hukum di pengadilan pajak. Teks materi halaman 43 secara tegas mewajibkan aparatur memeriksa hasil pekerjaan yang telah dilakukan. Oleh karena itu, verifikasi mandiri yang cermat pada opsi C adalah aplikasi perilaku efektif yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Memeriksa kembali akurasi dasar hukum, konsistensi angka kalkulasi, serta kelengkapan bukti pendukung secara mandiri.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena menyerahkan dokumen tanpa verifikasi kalkulasi angka berisiko memicu kesalahan penetapan pajak.</li><li><strong>B</strong>: Keliru karena menghapus kertas kerja melanggar standar audit perpajakan dan merusak integritas arsip bukti.</li><li><strong>D</strong>: Keliru karena pengesahan laporan pemeriksaan adalah wewenang pejabat fungsional pemeriksa resmi negara.</li><li><strong>E</strong>: Keliru karena mengunggah data rahasia wajib pajak ke media sosial melanggar hukum pidana kerahasiaan jabatan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat administrator mengabaikan seluruh usulan perbaikan sistem pelayanan yang diajukan dalam kotak saran dan menyatakan bahwa sistem kantornya telah sempurna sehingga tidak butuh inovasi apa pun. Mengapa sikap pejabat tersebut KELIRU?", "options": ["Sikap pejabat sangat tepat karena sistem pelayanan birokrasi pemerintahan bersifat statis abadi sepanjang masa.", "Sikap pejabat keliru karena nilai kesempurnaan menuntut pencarian peluang perbaikan terus-menerus tanpa henti.", "Sikap pejabat dapat dibenarkan sepanjang anggaran operasional tahunan unit kerja bersangkutan habis terserap penuh.", "Sikap pejabat mencerminkan kearifan lokal yang mengutamakan kenyamanan bekerja tanpa perlu ada tekanan inovasi.", "Sikap pejabat sangat bijaksana demi menghemat waktu rapat staf agar dapat dipergunakan untuk rekreasi bersama."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Nilai Kesempurnaan dan Perilaku Efektif halaman 43 mewajibkan: mendorong partisipasi aktif untuk mencari peluang perbaikan terus-menerus; kesempurnaan bukanlah titik statis melainkan proses dinamis tiada henti.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menganggap suatu sistem birokrasi telah sempurna dan menolak masukan perbaikan merupakan ilusi arogansi (complacency trap) yang menjadi awal kebangkrutan mutu pelayanan publik. Tuntutan masyarakat, regulasi ekonomi, dan perkembangan teknologi informasi bergerak sangat cepat, sehingga organisasi yang menolak berinovasi akan segera tertinggal, menjadi usang, dan gagal menjawab ekspektasi publik. Panduan Perilaku Efektif halaman 43 secara kategoris memerintahkan pencarian peluang perbaikan dan penerapan cara baru secara berkelanjutan. Maka dari itu, evaluasi pada opsi B secara tepat membuktikan bahwa menolak perbaikan adalah pelanggaran terhadap esensi nilai Kesempurnaan.</p><p>Jawaban yang sesuai adalah <strong>B. Sikap pejabat keliru karena nilai kesempurnaan menuntut pencarian peluang perbaikan terus-menerus tanpa henti.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena sistem birokrasi modern bersifat adaptif dinamis dalam merespons kebutuhan zaman.</li><li><strong>C</strong>: Keliru karena penyerapan anggaran tanpa perbaikan mutu layanan bukanlah indikator keunggulan tata kelola.</li><li><strong>D</strong>: Keliru karena zona nyaman yang menolak inovasi mematikan daya saing dan merugikan kemaslahatan publik.</li><li><strong>E</strong>: Keliru karena waktu kerja dinas wajib dioptimalkan untuk peningkatan kinerja, bukan rekreasi bersama.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan Perilaku Efektif yang tercantum pada halaman 43 materi modul penguatan budaya Kementerian Keuangan?", "options": ["Mendorong partisipasi aktif untuk mencari peluang perbaikan dalam rangka perbaikan sistem komprehensif.", "Mengembangkan dan mengimplementasikan cara-cara baru atau inovatif guna menyempurnakan proses kerja dinas.", "Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus.", "Memiliki visi yang maju agar mampu menyusun rencana yang relevan dan matang, serta memeriksa hasil kerja.", "Menghentikan seluruh pemanfaatan teknologi informasi dan kembali menerapkan sistem kerja manual abad pertengahan."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Halaman 43 memuat perilaku efektif: (1) mendorong partisipasi aktif cari peluang perbaikan & implementasikan cara baru inovatif perbaikan sistem komprehensif; (2) baca, analisis, manfaatkan data guna perbaikan berkelanjutan; (3) visi maju susun rencana matang & periksa hasil kerja.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Seluruh butir Perilaku Efektif pada halaman 43 berorientasi pada kemajuan, adopsi inovasi teknologi modern, analitika data empiris, dan perencanaan berwawasan masa depan demi mengejar kesempurnaan kinerja institusi. Gagasan untuk menghentikan pemanfaatan teknologi informasi dan memundurkan sistem kerja ke era manual kuno bertolak belakang secara frontal dengan semangat nilai Adaptif dan Kesempurnaan. Teks materi halaman 43 secara jelas mendorong penerapan metode baru yang inovatif dan terukur. Oleh sebab itu, klausul kembali ke sistem manual kuno pada opsi E jelas bukan merupakan perilaku efektif yang tercantum dalam materi melainkan kemunduran destruktif.</p><p>Jawaban yang sesuai adalah <strong>E. Menghentikan seluruh pemanfaatan teknologi informasi dan kembali menerapkan sistem kerja manual abad pertengahan.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Perilaku efektif sah mengenai dorongan partisipasi mencari peluang perbaikan sistem komprehensif.</li><li><strong>B</strong>: Perilaku efektif sah mengenai implementasi cara-cara baru yang inovatif sesuai teks halaman 43.</li><li><strong>C</strong>: Perilaku efektif sah mengenai analitika data untuk perbaikan pekerjaan berkelanjutan di halaman 43.</li><li><strong>D</strong>: Perilaku efektif sah mengenai kepemilikan visi maju dalam menyusun dan memeriksa rencana kerja.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Aplikasi", "question": "Ketika melihat antrean pengesahan dokumen kepabeanan kerap menumpuk pada hari selasa, seorang analis data mengkaji riwayat transaksi tiga bulan terakhir dan menemukan kemacetan disebabkan oleh penumpukan berkas verifikasi kontainer cair. Tindakan pemanfaatan data ini merupakan aplikasi dari perilaku...", "options": ["Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus.", "Mencari-cari kesalahan seksi lain agar unit analis data mendapatkan penghargaan pegawai teladan dari pimpinan.", "Menyebarkan rahasia kepabeanan importir ke media massa demi mendapatkan popularitas di ruang publik daring.", "Meminta uang suap percepatan verifikasi kontainer cair kepada importir bersangkutan melalui saluran telepon.", "Menutup sistem pelayanan kepabeanan setiap hari selasa agar pegawai dapat beristirahat tanpa adanya gangguan."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif halaman 43: Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus (continuous improvement).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pemanfaatan data transaksi historis untuk mengidentifikasi titik kemacetan (bottleneck) operasional merupakan aplikasi konkret dari budaya kerja berbasis analitika data yang diamanatkan dalam materi. Dengan menemukan penyebab spesifik penumpukan berkas pada komoditas kontainer cair, pimpinan unit dapat mengambil tindakan manajerial yang tepat sasaran—seperti menambah personel verifikator khusus cairan pada hari selasa—sehingga kelancaran arus barang ekspor impor terjamin. Tindakan analis tersebut mengaplikasikan secara sempurna butir perilaku efektif membaca, menganalisis, dan memanfaatkan data. Oleh sebab itu, opsi A merupakan jawaban yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>A. Membaca, menganalisis, dan memanfaatkan data dan informasi guna perbaikan pekerjaan secara terus menerus.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena analisis data ditujukan untuk perbaikan sistem organisasi, bukan mencari kesalahan rekan kerja.</li><li><strong>C</strong>: Keliru karena membocorkan data importir melanggar kerahasiaan jabatan dan hukum kepabeanan nasional.</li><li><strong>D</strong>: Keliru karena meminta suap merupakan tindak pidana korupsi pemerasan jabatan yang haram.</li><li><strong>E</strong>: Keliru karena penutupan loket secara sepihak menelantarkan kewajiban pelayanan publik negara.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah siklus perbaikan sistem pelayanan (Continuous Improvement Cycle) berbasis data pada satuan kerja yang mengintegrasikan ketiga butir Perilaku Efektif pada halaman 43!", "options": ["Mengabaikan data -> membuat aturan baru tanpa uji coba -> menghapus seluruh sistem lama -> menyalahkan bawahan.", "Mewajibkan pegawai lembur tanpa henti -> melarang evaluasi -> menghapus kotak saran -> membatasi akses warga.", "Analisis data operasional (Data) -> Rancang inovasi sistemik (Inovasi) -> Rencana matang & telaah hasil (Visi & Periksa).", "Membeli perangkat lunak asing mahal -> menyerahkan wewenang ke swasta -> memecat seluruh staf -> menutup kantor.", "Mengundi acak solusi perbaikan -> membiarkan masalah menumpuk -> memalsukan angka kepuasan -> lapor sempurna."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Sintesis 3 butir halaman 43: (1) membaca/analisis data; (2) partisipasi aktif inovasi cara baru perbaikan sistem komprehensif; (3) visi maju rencana matang dan periksa hasil pekerjaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Ketiga butir Perilaku Efektif pada halaman 43 membentuk suatu siklus penyempurnaan mutu yang utuh dan saling melengkapi (Plan-Do-Check-Act). Tahap awal dimulai dari pengkajian data empiris untuk mendeteksi peluang perbaikan; dilanjutkan dengan partisipasi aktif seluruh pegawai dalam merancang dan mengimplementasikan cara kerja baru yang inovatif secara sistemik; lalu dituntaskan dengan perencanaan visioner yang matang serta pengendalian mutu mandiri melalui pemeriksaan hasil kerja secara ketat. Sintesis alur kerja bertingkat pada opsi C secara paripurna memadukan ketiga pilar perilaku efektif tersebut menjadi metodologi manajemen mutu yang andal.</p><p>Jawaban yang sesuai adalah <strong>C. Analisis data operasional (Data) -> Rancang inovasi sistemik (Inovasi) -> Rencana matang & telaah hasil (Visi & Periksa).</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena mengabaikan data dan melempar kesalahan pada bawahan merusak tata kelola organisasi.</li><li><strong>B</strong>: Keliru karena eksploitasi jam kerja tanpa evaluasi melanggar hak pegawai dan menurunkan produktivitas.</li><li><strong>D</strong>: Keliru karena privatisasi tanpa kontrol dan penutupan kantor melanggar undang-undang pelayanan publik.</li><li><strong>E</strong>: Keliru karena pengundian acak dan pemalsuan laporan merupakan kejahatan penipuan administratif dinas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 43", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah rencana strategis berwawasan ke depan (forward-looking plan) pada tingkat kantor pelayanan fiskal guna mengantisipasi era otomatisasi perpajakan global!", "options": ["Memboikot seluruh kebijakan perpajakan internasional dan melarang warga negara menggunakan internet perbankan.", "Menghancurkan peladen komputer kantor pelayanan agar wajib pajak kembali mengantre manual di loket fisik.", "Menetapkan denda pajak seratus kali lipat secara sepihak kepada seluruh pelaku usaha digital luar negeri.", "Peningkatan literasi data staf, adopsi sistem kecerdasan analitis, evaluasi kepatuhan berkala, dan mitigasi risiko siber.", "Menyerahkan seluruh basis data penerimaan perpajakan negara kepada agen perbankan komersial luar negeri."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 43", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 43</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Perilaku Efektif halaman 43 menuntut aparatur memiliki visi maju dalam menyusun rencana yang relevan dan matang, memanfaatkan inovasi cara baru, serta memeriksa dan memitigasi risiko pekerjaan secara komprehensif.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Menghadapi era disrupsi digital dan otomatisasi sistem keuangan global, kantor pelayanan fiskal dituntut memiliki perencanaan strategis jangka panjang yang adaptif dan berwawasan visioner. Rencana strategis yang komprehensif memadukan peningkatan kompetensi literasi data aparatur (up-skilling), pemanfaatan analitika data canggih untuk mendeteksi potensi pajak baru, mekanisme evaluasi berkala kepatuhan wajib pajak, serta pembentengan infrastruktur siber dari ancaman peretasan. Sintesis perencanaan visioner pada opsi D merefleksikan kepemilikan visi maju dan inovasi sistemik yang diamanatkan dalam materi halaman 43.</p><p>Jawaban yang sesuai adalah <strong>D. Peningkatan literasi data staf, adopsi sistem kecerdasan analitis, evaluasi kepatuhan berkala, dan mitigasi risiko siber.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena pemboikotan sistem internasional mencerminkan sikap isolasionis yang mematikan perekonomian.</li><li><strong>B</strong>: Keliru karena perusakan infrastruktur komputer dinas adalah tindakan kriminal perusakan aset negara BMN.</li><li><strong>C</strong>: Keliru karena pengenaan denda sepihak tanpa undang-undang melanggar asas legalitas perpajakan kenegaraan.</li><li><strong>E</strong>: Keliru karena penyerahan basis data penerimaan negara kepada pihak luar melanggar kedaulatan fiskal bangsa.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 43.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Analitis", "question": "Berdasarkan Tabel 3 Surat Edaran Nomor SE-15/MK.1/2022, kelompok sasaran pertama adalah Mahasiswa PKN STAN dan CPNS/Pelaksana kurang dari satu tahun dengan target kematangan minimal 'sadar pentingnya Sikap Dasar dan Perilaku Efektif' (aware the values). Mengapa target tingkat kematangan pada fase ini difokuskan pada tahap kesadaran (awareness)?", "options": ["Karena mahasiswa STAN dan CPNS dilarang mematuhi kode etik sebelum diangkat menjadi pejabat struktural eselon dinas.", "Karena kementerian beranggapan bahwa CPNS tidak memiliki kemampuan intelektual untuk memahami nilai integritas.", "Karena fase pengenalan awal bertujuan meletakkan fondasi kognitif dan afektif sebelum dituntut pembiasaan penuh.", "Karena mahasiswa STAN dan CPNS dibebaskan dari seluruh bentuk sanksi disiplin selama masa percobaan satu tahun.", "Karena target kesadaran merupakan syarat administratif formal agar anggaran beasiswa STAN dapat dicairkan bank."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/MK.1/2022 menetapkan sasaran Mahasiswa PKN STAN dan CPNS/Pelaksana < 1 tahun dengan target minimal: Sadar pentingnya Sikap Dasar dan Perilaku Efektif (aware the values) sebagai tahap fondasi awal pembudayaan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Dalam hierarki maturitas budaya organisasi, tahap kesadaran (awareness) merupakan langkah pembuka yang paling esensial sebelum seseorang melangkah ke tahap pemahaman mendalam (understanding), penerapan penuh (implementing), hingga kepemilikan nilai (owning). Bagi mahasiswa kedinasan dan pegawai baru yang baru memasuki lingkungan birokrasi, penanaman doktrin nilai difokuskan untuk membuka kesadaran nalar dan nurani mereka mengenai mengapa integritas dan profesionalisme sangat vital bagi kedaulatan keuangan negara. Landasan regulasi SE-15/2022 secara presisi menetapkan target 'aware the values' bagi kelompok pemula sebagai landasan pijak pembentukan karakter aparatur. Oleh karenanya, opsi C menyajikan analisis pedagogis dan psikologis yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Karena fase pengenalan awal bertujuan meletakkan fondasi kognitif dan afektif sebelum dituntut pembiasaan penuh.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kepatuhan etika mengikat seluruh insan kementerian sejak hari pertama masuk gerbang dinas.</li><li><strong>B</strong>: Keliru karena CPNS merupakan bibit unggul pilihan yang memiliki kapasitas intelektual tinggi untuk dibina.</li><li><strong>D</strong>: Keliru karena masa percobaan CPNS justru diawasi secara sangat ketat terhadap potensi pelanggaran disiplin.</li><li><strong>E</strong>: Keliru karena pembudayaan nilai berakar pada pembentukan karakter moral korps, bukan formalitas beasiswa.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Aplikasi", "question": "Sebuah satuan kerja menerima lima orang CPNS pelaksana baru yang masa kerjanya kurang dari satu tahun. Berdasarkan Tabel 3 SE-15/MK.1/2022, strategi Internalisasi pembudayaan yang wajib diselenggarakan satker bagi CPNS tersebut adalah...", "options": ["Menugaskan CPNS menjaga gerbang parkir kantor selama dua puluh empat jam sehari tanpa pergantian shift dinas.", "Menyuruh CPNS membelikan makanan santap siang untuk seluruh pegawai senior menggunakan uang gaji pribadi CPNS.", "Melarang CPNS berbicara dan mengajukan pertanyaan selama enam bulan pertama masa kerja di kantor pelayanan.", "Membebankan seluruh pekerjaan penyusunan laporan keuangan tahunan kementerian yang rumit kepada staf CPNS baru.", "Melaksanakan Program Habituasi Budaya dan penguatan budaya melalui pelatihan dasar pegawai baru kementerian."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/MK.1/2022: Strategi Internalisasi untuk Mahasiswa STAN dan CPNS/Pelaksana < 1 tahun meliputi: (1) Penguatan budaya dalam kurikulum STAN; (2) Program Habituasi Budaya; (3) Penguatan budaya melalui pelatihan dasar CPNS/pegawai baru Kemenkeu.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Masa awal penugasan sebagai calon pegawai negeri sipil merupakan periode emas dalam pembentukan etos dan karakter kerja aparatur melalui pembiasaan perilaku positif secara intensif dan terbimbing. Program Habituasi Budaya dan penguatan nilai dalam pelatihan dasar (Latsar) CPNS membekali aparatur muda pemahaman konkret bagaimana menerapkan Sikap Dasar dan Perilaku Efektif dalam tugas operasional sehari-hari. Dokumen Tabel 3 SE-15/2022 secara eksplisit menetapkan program habituasi budaya dan pelatihan dasar sebagai menu utama strategi internalisasi kelompok sasaran ini. Oleh karena itu, pelaksanaan program habituasi pada opsi E adalah aplikasi regulasi yang paling tepat.</p><p>Jawaban yang sesuai adalah <strong>E. Melaksanakan Program Habituasi Budaya dan penguatan budaya melalui pelatihan dasar pegawai baru kementerian.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penugasan penjagaan parkir berlebihan merupakan eksploitasi di luar pembinaan kompetensi dinas.</li><li><strong>B</strong>: Keliru karena pemalakan uang gaji CPNS oleh senior adalah perpeloncoan tercela yang melanggar kode etik.</li><li><strong>C</strong>: Keliru karena membungkam CPNS bertentangan dengan budaya komunikasi terbuka dan organisasi pemelajar.</li><li><strong>D</strong>: Keliru karena pelimpahan tugas kompleks kepada CPNS tanpa bimbingan melanggar prinsip pembagian wewenang.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Analitis", "question": "Dalam strategi Institusionalisasi bagi mahasiswa PKN STAN dan CPNS, SE-15/MK.1/2022 mengamanatkan penyisipan budaya ke dalam kurikulum PKN STAN dan materi pelatihan dasar CPNS. Mengapa pelembagaan kurikulum tersebut diposisikan sebagai langkah yang sangat strategis?", "options": ["Karena kurikulum akademis merupakan satu-satunya cara untuk menghapus seluruh mata kuliah teknis akuntansi dinas.", "Karena internalisasi nilai sejak bangku pendidikan membentuk DNA integritas sebelum mahasiswa terjun ke dunia kerja.", "Agar mahasiswa STAN dapat ditugaskan menarik pajak secara langsung dari masyarakat saat masih berstatus pelajar.", "Karena kementerian berencana mengubah politeknik kedinasan menjadi lembaga pembiayaan perbankan komersial swasta.", "Agar seluruh tenaga pengajar di PKN STAN dibebaskan dari kewajiban mematuhi kode etik dan disiplin aparatur."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Institusionalisasi pada kelompok sasaran STAN/CPNS: memasukkan budaya dalam kurikulum PKN STAN dan materi pelatihan dasar CPNS guna melembagakan nilai-nilai organisasi sejak tahap pembentukan awal.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pencegahan tindak pidana korupsi dan pembentukan aparatur yang berintegritas tinggi paling efektif dilakukan pada fase formatif sebelum seseorang memegang wewenang kekuasaan dan jabatan publik. Memasukkan nilai-nilai BerAKHLAK dan Nilai-Nilai Kementerian Keuangan ke dalam kurikulum pembelajaran institusi kedinasan STAN menanamkan 'DNA integritas' dan kompas moral ke dalam alam bawah sadar calon aparatur sejak dini. Landasan SE-15/2022 menempatkan kurikulum kedinasan sebagai instrumen institusionalisasi hulu yang paling fundamental. Oleh sebab itu, opsi B menyajikan analisis strategis mengenai pembentukan karakter di bangku pendidikan secara paling akurat.</p><p>Jawaban yang sesuai adalah <strong>B. Karena internalisasi nilai sejak bangku pendidikan membentuk DNA integritas sebelum mahasiswa terjun ke dunia kerja.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena penguatan nilai tidak menghapus mata kuliah akuntansi teknis melainkan melandasinya dengan etika.</li><li><strong>C</strong>: Keliru karena penarikan pajak merupakan wewenang aparatur resmi yang telah dilantik dan disumpah negara.</li><li><strong>D</strong>: Keliru karena PKN STAN tetap berstatus lembaga pendidikan tinggi vokasi kedinasan pencetak aparatur negara.</li><li><strong>E</strong>: Keliru karena dosen dan pengajar STAN wajib menjadi role model keteladanan penegakan kode etik aparatur.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Evaluatif", "question": "Sebuah satuan kerja memutuskan tidak mengikutsertakan pegawai baru dalam Program Habituasi Budaya dengan alasan CPNS hanya perlu fokus bekerja menuntaskan berkas arsip gudang kantor. Mengapa kebijakan satuan kerja tersebut KELIRU?", "options": ["Kebijakan satker sangat tepat karena CPNS baru tidak memerlukan pembinaan moral selama memiliki ijazah sarjana.", "Kebijakan satker sangat efisien karena satker dapat menghemat anggaran jamuan konsumsi pelatihan pegawai dinas.", "Kebijakan satker dapat dibenarkan sepanjang berkas arsip gudang kantor berhasil ditata rapi dalam kurun sebulan.", "Kebijakan satker keliru karena habituasi budaya merupakan mandat SE-15/2022 untuk menumbuhkan kesadaran nilai.", "Kebijakan satker mencerminkan kemandirian unit operasional yang sah dalam membatasi hak pembinaan pegawai."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Surat Edaran Nomor SE-15/MK.1/2022 mewajibkan pelaksanaan strategi pembudayaan termasuk Program Habituasi Budaya bagi CPNS/Pelaksana < 1 tahun guna menumbuhkan kesadaran Sikap Dasar dan Perilaku Efektif (aware the values).</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Mengabaikan pembinaan budaya bagi aparatur baru demi mengejar penuntasan tugas manual gudang merupakan miopia manajerial yang sangat merugikan masa depan kelembagaan kementerian. Tanpa habituasi nilai yang terarah, pegawai baru akan rentan terkontaminasi oleh kebiasaan buruk lingkungan kerja lama, salah menafsirkan etika kedinasan, dan kehilangan kompas moral dalam menolak gratifikasi saat memegang wewenang nanti. Tabel 3 SE-15/2022 secara tegas mewajibkan penyelenggaraan Program Habituasi Budaya sebagai instrumen pencapaian target kematangan 'aware the values'. Maka dari itu, penilaian pada opsi D secara tepat membuktikan bahwa membatalkan habituasi adalah kekeliruan fatal terhadap regulasi menteri.</p><p>Jawaban yang sesuai adalah <strong>D. Kebijakan satker keliru karena habituasi budaya merupakan mandat SE-15/2022 untuk menumbuhkan kesadaran nilai.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena ijazah akademis formal tidak pernah menjamin kekebalan alami moralitas tanpa pembinaan nilai.</li><li><strong>B</strong>: Keliru karena memangkas pembinaan karakter aparatur demi efisiensi konsumsi merupakan kerugian sistemik.</li><li><strong>C</strong>: Keliru karena penataan arsip fisik tidak boleh mengorbankan hak pembinaan integritas dasar pegawai baru.</li><li><strong>E</strong>: Keliru karena pimpinan satker tidak berwenang menganulir surat edaran resmi menteri keuangan pusat.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Aplikasi", "question": "Berdasarkan Tabel 3 SE-15/MK.1/2022, bentuk kegiatan Eksternalisasi yang ditetapkan untuk mahasiswa PKN STAN dan CPNS/pelaksana kurang dari satu tahun adalah...", "options": ["Kompetisi atau tugas desain grafis atau video terkait budaya sebagai bahan sosialisasi kepada pihak eksternal.", "Penugasan CPNS untuk melakukan inspeksi mendadak ke kantor perusahaan swasta tanpa surat penugasan resmi dinas.", "Mewajibkan mahasiswa STAN menggelar unjuk rasa di jalan raya umum guna menuntut kenaikan anggaran beasiswa.", "Menjual kaos oblong dan suvenir kementerian kepada warga masyarakat di pasar malam guna menambah kas satker.", "Menyebarkan identitas data pribadi seluruh wajib pajak ke media sosial sebagai bukti keterbukaan birokrasi."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/MK.1/2022 kolom Eksternalisasi sasaran Mahasiswa STAN & CPNS: Kompetisi/tugas desain grafis atau video terkait budaya sebagai bahan sosialisasi kepada pihak-pihak eksternal.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Pemberian tugas kreatif berbasis media digital—seperti lomba perancangan infografis dan pembuatan video pendek bertema budaya integritas—memanfaatkan keunggulan literasi digital generasi muda aparatur untuk mengedukasi masyarakat luas. Melalui karya visual yang menarik dan edukatif, pesan-pesan luhur nilai BerAKHLAK dan Kemenkeu Satu dapat tersampaikan kepada para pemangku kepentingan eksternal secara segar, komunikatif, dan mudah dipahami. Rincian tabel resmi SE-15/2022 secara spesifik mencantumkan kompetisi/tugas desain grafis atau video sebagai bentuk eksternalisasi bagi kelompok sasaran ini. Dengan demikian, kegiatan kreatif pada opsi A adalah aplikasi regulasi yang paling sahih.</p><p>Jawaban yang sesuai adalah <strong>A. Kompetisi atau tugas desain grafis atau video terkait budaya sebagai bahan sosialisasi kepada pihak eksternal.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena sidak tanpa surat tugas sah merupakan tindakan sewenang-wenang yang melanggar hukum pidana.</li><li><strong>C</strong>: Keliru karena unjuk rasa liar bertentangan dengan etika disiplin aparatur sipil negara dan mahasiswa kedinasan.</li><li><strong>D</strong>: Keliru karena berdagang suvenir di pasar malam bukanlah bentuk eksternalisasi nilai melainkan komersialisasi liar.</li><li><strong>E</strong>: Keliru karena membocorkan data pribadi wajib pajak melanggar undang-undang kerahasiaan jabatan perbendaharaan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Analitis", "question": "Surat Edaran Nomor SE-15/MK.1/2022 diterbitkan sebagai panduan pelaksanaan penguatan budaya di lingkungan kementerian. Bagaimanakah korelasi terbitnya SE-15/MK.1/2022 terhadap keberhasilan peningkatan kinerja pegawai dalam mendukung tugas fungsi Kemenkeu?", "options": ["SE-15/2022 mewajibkan kementerian membatasi penyerapan anggaran perbendaharaan hanya sebesar sepuluh persen.", "SE-15/2022 dirancang untuk menghapus kewajiban pegawai kementerian dalam menyusun laporan sasaran kinerja dinas.", "Penguatan budaya melalui Sikap Dasar dan Perilaku Efektif mendorong etos kerja unggul penopang kinerja organisasi.", "SE-15/2022 membebaskan pimpinan unit kerja dari kewajiban memantau dan mengevaluasi perilaku kerja staf bawahan.", "SE-15/2022 mewajibkan penggantian seluruh komputer kantor dengan mesin ketik manual demi melatih otot tangan."], "answer": 2, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>SE-15/MK.1/2022 menegaskan bahwa pelaksanaan Sikap Dasar dan Perilaku Efektif dibutuhkan demi penguatan budaya organisasi guna mendorong peningkatan kinerja pegawai dalam mendukung pelaksanaan tugas dan fungsi Kementerian Keuangan.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Budaya kerja bukanlah entitas terisolasi yang terpisah dari pencapaian kinerja, melainkan penggerak utama (engine driver) yang menentukan kecepatan, ketepatan, dan keandalan aparatur dalam mengeksekusi target organisasi. Ketika Sikap Dasar (mindset integritas) dan Perilaku Efektif (disiplin, akurat, kolaboratif, solutif) telah membudaya dalam rutinitas kerja sehari-hari, inefisiensi birokrasi terpangkas dan kebocoran anggaran terminimalisasi, sehingga kinerja institusi kementerian melonjak secara berkelanjutan. Penjelasan teks SE-15/2022 secara gamblang mengaitkan penguatan budaya dengan peningkatan kinerja pegawai penopang tugas fiskal negara. Oleh sebab itu, opsi C menyajikan analisis korelasi kausalitas budaya dan kinerja secara paling tepat.</p><p>Jawaban yang sesuai adalah <strong>C. Penguatan budaya melalui Sikap Dasar dan Perilaku Efektif mendorong etos kerja unggul penopang kinerja organisasi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena kementerian bertugas mengoptimalkan penyerapan anggaran negara secara berkualitas dan hemat.</li><li><strong>B</strong>: Keliru karena penyusunan sasaran kinerja pegawai tetap wajib dilaksanakan sesuai regulasi aparatur sipil negara.</li><li><strong>D</strong>: Keliru karena SE-15 justru memberikan panduan bagi pimpinan unit untuk aktif membina dan memantau budaya staf.</li><li><strong>E</strong>: Keliru karena modernisasi kementerian mendorong adopsi teknologi digital mutakhir, bukan kembali ke mesin ketik.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Evaluatif", "question": "Seorang pejabat administrator menganggap bahwa kompetisi video kreatif budaya bagi mahasiswa PKN STAN dan CPNS hanyalah kegiatan bermain media sosial yang membuang waktu dan biaya negara. Mengapa anggapan pejabat tersebut KELIRU?", "options": ["Anggapan pejabat keliru karena kompetisi kreatif adalah instrumen eksternalisasi modern untuk edukasi nilai ke publik.", "Anggapan pejabat sangat benar karena mahasiswa STAN seharusnya hanya diwajibkan menghafal seluruh undang-undang.", "Anggapan pejabat dapat dibenarkan sepanjang dana hadiah kompetisi dialihkan untuk membeli cinderamata pimpinan.", "Anggapan pejabat mencerminkan kearifan birokrasi kuno yang sah dalam menolak pemanfaatan media visual digital.", "Anggapan pejabat sangat bijak demi menjaga agar mahasiswa kedinasan tidak memiliki keterampilan teknologi komputer."], "answer": 0, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/MK.1/2022 menetapkan tugas desain grafis dan video kreatif budaya sebagai instrumen strategis Eksternalisasi guna menyosialisasikan nilai-nilai kementerian kepada pihak eksternal/masyarakat.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Memandang pembuatan konten visual kreatif sebagai kesia-siaan membuktikan ketertinggalan wawasan dalam memahami dinamika komunikasi publik kontemporer. Di era siber, pesan etika antikorupsi dan budaya integritas jauh lebih cepat dipahami dan menyentuh kesadaran masyarakat melalui medium video pendek yang estetik dan persuasif dibandingkan melalui lembaran regulasi kaku. Tabel 3 SE-15/2022 secara resmi memposisikan kompetisi desain grafis dan video sebagai sarana eksternalisasi budaya yang menghubungkan aparatur muda dengan pemangku kepentingan publik. Maka dari itu, penilaian pada opsi A secara tepat membuktikan bahwa anggapan pejabat tersebut merupakan kekeliruan fatal.</p><p>Jawaban yang sesuai adalah <strong>A. Anggapan pejabat keliru karena kompetisi kreatif adalah instrumen eksternalisasi modern untuk edukasi nilai ke publik.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>B</strong>: Keliru karena pendidikan kedinasan modern menuntut perpaduan penguasaan hukum dan keterampilan komunikasi publik.</li><li><strong>C</strong>: Keliru karena pengalihan dana kompetisi untuk cinderamata pejabat melanggar etika tata kelola anggaran.</li><li><strong>D</strong>: Keliru karena menolak media visual digital mencerminkan kejumudan yang memutus komunikasi kementerian dari rakyat.</li><li><strong>E</strong>: Keliru karena aparatur pengelola keuangan modern wajib menguasai keterampilan teknologi informasi mutakhir.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Analitis", "question": "Manakah di antara pernyataan berikut yang BUKAN merupakan strategi yang tercantum dalam Tabel 3 SE-15/MK.1/2022 untuk sasaran Mahasiswa PKN STAN dan CPNS/Pelaksana kurang dari satu tahun?", "options": ["Penguatan budaya organisasi ke dalam kurikulum pembelajaran mahasiswa Politeknik Keuangan Negara STAN.", "Penjatuhan hukuman pemotongan hak pensiun seumur hidup bagi mahasiswa tingkat satu yang terlambat apel pagi.", "Penyelenggaraan Program Habituasi Budaya yang terencana dan sistematis bagi calon aparatur sipil negara baru.", "Penguatan budaya melalui pelatihan dasar (latsar) Calon Pegawai Negeri Sipil atau pegawai baru Kementerian Keuangan.", "Kompetisi atau tugas desain grafis atau video terkait budaya sebagai bahan sosialisasi kepada pihak eksternal."], "answer": 1, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/2022 untuk mahasiswa STAN & CPNS < 1 tahun memuat: kurikulum STAN, habituasi budaya, latsar CPNS, materi kurikulum STAN/Latsar, dan kompetisi desain grafis/video eksternal. Tidak ada sanksi pemotongan hak pensiun.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Tabel 3 SE-15/MK.1/2022 untuk kelompok sasaran pemula (mahasiswa STAN dan CPNS baru) memuat strategi pembinaan yang bersifat edukatif, pembiasaan (habituasi), dan edukasi kreatif ke publik guna mencapai tingkat kematangan 'aware the values'. Mahasiswa tingkat satu bahkan belum berstatus sebagai pegawai negeri sipil tetap sehingga tidak memiliki hak pensiun, dan penjatuhan sanksi pemotongan pensiun seumur hidup atas keterlambatan apel merupakan klausa fiktif yang kejam dan melanggar hukum. Teks materi resmi mencantumkan kurikulum STAN, program habituasi, materi latsar, dan tugas video eksternal. Oleh sebab itu, klausul hukuman pensiun pada opsi B jelas merupakan pernyataan yang sama sekali bukan strategi yang diatur dalam tabel tersebut.</p><p>Jawaban yang sesuai adalah <strong>B. Penjatuhan hukuman pemotongan hak pensiun seumur hidup bagi mahasiswa tingkat satu yang terlambat apel pagi.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Strategi internalisasi sah mengenai kurikulum PKN STAN yang tercantum dalam Tabel 3 aturan.</li><li><strong>C</strong>: Strategi internalisasi sah mengenai Program Habituasi Budaya yang tercantum secara eksplisit dalam tabel.</li><li><strong>D</strong>: Strategi internalisasi sah mengenai pelatihan dasar CPNS yang tercantum secara eksplisit dalam aturan.</li><li><strong>E</strong>: Strategi eksternalisasi sah mengenai kompetisi tugas desain grafis/video yang tercantum dalam materi regulasi.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah modul Program Habituasi Budaya terpadu selama masa orientasi CPNS di kantor pelayanan yang mengoperasionalkan target 'aware the values' secara efektif!", "options": ["CPNS disuruh berlari mengelilingi lapangan upacara selama 12 jam setiap hari tanpa diberikan materi kode etik dinas kantor.", "CPNS dibebaskan dari seluruh aturan kantor dan diizinkan tidak masuk kerja selama enam bulan masa orientasi baru.", "CPNS diwajibkan membayar uang kas orientasi sebesar satu juta rupiah per minggu kepada panitia pegawai senior kantor.", "Mentoring nilai oleh senior teladan, jurnal refleksi harian perilaku efektif, studi kasus etika, dan evaluasi berkala.", "CPNS ditugaskan menggantikan seluruh pejabat eselon tiga dalam menandatangani berkas keputusan pencairan dana kas."], "answer": 3, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Program Habituasi Budaya bagi CPNS bertujuan menumbuhkan kesadaran Sikap Dasar dan Perilaku Efektif (aware the values) melalui pembiasaan terstruktur, bimbingan, dan evaluasi berkala.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Program Habituasi Budaya yang berdaya ubah tinggi menuntut adanya perpaduan antara pendampingan keteladanan (mentoring) dari aparatur senior berintegritas, latihan refleksi diri harian atas penerapan Perilaku Efektif, pembedahan dilema etika riil di loket pelayanan, serta evaluasi kematangan sikap secara berkala. Melalui pembiasaan yang terpantau dan bermartabat ini, para CPNS akan secara sadar menginternalisasi nilai Integritas, Profesionalisme, Sinergi, Pelayanan, dan Kesempurnaan ke dalam jati diri kedinasan mereka. Sintesis rancangan modul orientasi pada opsi D merupakan cetak biru habituasi budaya yang paling edukatif, saintifik, dan akuntabel.</p><p>Jawaban yang sesuai adalah <strong>D. Mentoring nilai oleh senior teladan, jurnal refleksi harian perilaku efektif, studi kasus etika, dan evaluasi berkala.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena hukuman fisik lari lapangan bukanlah metode habituasi nilai melainkan kekerasan nir-substansi.</li><li><strong>B</strong>: Keliru karena membiarkan CPNS membolos melanggar disiplin jam kerja dan merusak mentalitas aparatur.</li><li><strong>C</strong>: Keliru karena pemungutan uang orientasi merupakan pungutan liar dan pemerasan jabatan yang melanggar hukum.</li><li><strong>E</strong>: Keliru karena penyerahan wewenang eselon tiga kepada CPNS baru melanggar hukum tata kelola perbendaharaan.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}, {"category": "TSKKWK", "sub": "Nilai-Nilai Kemenkeu • Hlm. 44", "difficulty": "HOTS • Kreasi", "question": "Rancanglah sebuah panduan kompetisi video pendek penguatan budaya bagi mahasiswa kedinasan PKN STAN yang efektif sebagai instrumen eksternalisasi nilai ke masyarakat!", "options": ["Video wajib memuat konten tarian vulgar modern tanpa menyertakan pesan nilai etika maupun pelayanan publik kenegaraan.", "Video harus mengkritik dan mencela lembaga peradilan negara dengan kata-kata provokatif pemecah belah bangsa.", "Video difokuskan untuk mempromosikan produk rokok komersial swasta dengan menggunakan latar belakang gedung kampus.", "Video dilarang diunggah ke internet dan hanya boleh disimpan di dalam cakram disket magnetik ruang arsip kampus.", "Tema integritas pelayanan, durasi edukatif 2 menit, format media sosial populer, dan uji orisinalitas tanpa hoax."], "answer": 4, "source": "Nilai-Nilai Kementerian Keuangan, halaman 44", "explanation": "<div class=\"learn-box lesson-card\"><div class=\"learn-title\">📚 Rangkuman Belajar • Halaman 44</div><div class=\"lesson-section\"><div class=\"lesson-kicker\">01 · Konsep inti</div><p>Tabel 3 SE-15/MK.1/2022 menetapkan tugas/kompetisi video kreatif budaya bagi mahasiswa STAN/CPNS sebagai instrumen Eksternalisasi sosialisasi nilai kepada pihak eksternal/masyarakat luas.</p></div><div class=\"lesson-section lesson-reason\"><div class=\"lesson-kicker\">02 · Mengapa jawaban ini benar?</div><p>Kompetisi video pendek eksternalisasi budaya yang berhasil harus memiliki panduan teknis yang jelas agar pesan moral yang disampaikan tepat sasaran, estetik, dan berdaya jangkau luas di media sosial. Kriteria yang menetapkan tema sentral integritas dan pelayanan publik tanpa pungli, pembatasan durasi yang padat pesan (micro-learning 2 menit), pengemasan dalam format vertikal populer yang ramah generasi muda, serta penyaringan orisinalitas konten bebas hoaks menjamin karya mahasiswa STAN mampu mengedukasi masyarakat secara viral dan bermartabat. Sintesis petunjuk teknis pada opsi E secara paripurna mengoperasionalkan strategi eksternalisasi SE-15/2022.</p><p>Jawaban yang sesuai adalah <strong>E. Tema integritas pelayanan, durasi edukatif 2 menit, format media sosial populer, dan uji orisinalitas tanpa hoax.</strong>.</p></div><div class=\"lesson-section\"><div class=\"lesson-kicker\">03 · Cara membedakan pilihan</div><p><strong>Pembeda dan Catatan Pengecoh:</strong></p><ul style=\"margin:6px 0 0;padding-left:20px;line-height:1.6\"><li><strong>A</strong>: Keliru karena konten vulgar merusak kesopanan norma kesusilaan dan mencoreng marwah institusi kedinasan.</li><li><strong>B</strong>: Keliru karena konten provokatif pemecah belah melanggar kode etik sinergi persatuan dan kesatuan bangsa.</li><li><strong>C</strong>: Keliru karena promosi produk rokok melanggar etika kesehatan dan menyalahgunakan fasilitas gedung kampus.</li><li><strong>D</strong>: Keliru karena pelarangan publikasi internet bertolak belakang dengan hakikat eksternalisasi kepada publik luas.</li></ul></div><div class=\"lesson-source\">📖 Referensi: Nilai-Nilai Kementerian Keuangan • halaman 44.</div></div>"}];
let current=0;const answers=new Array(questions.length).fill(null);const letters=["A","B","C","D","E"];let seconds=65*60;let submitted=false;


// Anotasi hanya dalam pembahasan. Satu set coretan untuk setiap nomor soal.
const ANNO_KEY='stangolden_kemenkeu_p04_review_annot_v1_user_<?= (int)$USER->id ?>';
let reviewAnnoStore={};
// Data anotasi dimuat dari Moodle agar bisa dibuka dari perangkat berbeda.
let reviewAnnoActive=null,reviewAnnoTool='pen',reviewAnnoDrawing=false,reviewAnnoStroke=null;
const raSaveTimers={};
const raSavePending={};
let raServerReady=false;
async function raLoadServer(){
 try {
   const r=await fetch(`${LEADERBOARD_ENDPOINT}?action=anno_load`,{credentials:'same-origin',cache:'no-store'});
   const data=await r.json();
   if(!r.ok||!data.success)throw new Error(data.message||'Gagal memuat anotasi');
   reviewAnnoStore=data.annotations||{};
   raServerReady=true;
   // Gambar coretan yang sudah tersimpan SECARA OTOMATIS, tanpa menekan
   // tombol Coret/Anotasi. Canvas tetap pasif agar halaman mudah discroll.
   raRestoreAnnotations();
 }catch(e){console.error('Anotasi server:',e);alert('Anotasi belum dapat dimuat dari server. Coba buka ulang pembahasan.');}
}
async function raSendSave(i){
 if(!raServerReady)return;
 const b=new URLSearchParams();b.set('action','anno_save');b.set('sesskey',MOODLE_SESSKEY);
 b.set('question',String(i));b.set('strokesjson',JSON.stringify(raStrokes(i)));
 try {const r=await fetch(LEADERBOARD_ENDPOINT,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:b.toString()});
 const d=await r.json();if(!r.ok||!d.success)throw new Error(d.message||'Gagal menyimpan');}
 catch(e){console.error('Gagal menyimpan anotasi nomor',i+1,e);alert('Coretan nomor '+(i+1)+' belum tersimpan. Periksa koneksi dan coba coret lagi.');}
}
function raSave(i){clearTimeout(raSaveTimers[i]);raSaveTimers[i]=setTimeout(()=>{delete raSaveTimers[i];raSavePending[i]=raSendSave(i).finally(()=>{delete raSavePending[i];});},350);}

// Coretan dibuka otomatis saat review ditampilkan. Canvas yang belum
// terlihat baru diinisialisasi saat masuk viewport (hemat memori untuk 100 soal).
let raReviewObserver=null;
function raRestoreAnnotations(){
 if(raReviewObserver){raReviewObserver.disconnect();raReviewObserver=null;}
 const saved=Object.keys(reviewAnnoStore).filter(k=>Array.isArray(reviewAnnoStore[k]) && reviewAnnoStore[k].length>0);
 const makeVisible=(i)=>{
   const c=raCanvas(i);
   if(!c)return;
   if(!c.dataset.initialized)raInit(i);
   else raResize(i);
 };
 if(typeof IntersectionObserver==='undefined'){
   saved.forEach(k=>makeVisible(Number(k)));
 }else{
   raReviewObserver=new IntersectionObserver(entries=>{
     entries.forEach(entry=>{
       if(!entry.isIntersecting)return;
       const i=Number(entry.target.dataset.question);
       makeVisible(i);
       raReviewObserver.unobserve(entry.target);
     });
   },{rootMargin:'280px 0px'});
   saved.forEach(k=>{
     const c=raCanvas(Number(k));
     if(c)raReviewObserver.observe(c);
   });
 }
 document.querySelectorAll('.review-annotation-canvas[data-initialized]').forEach(c=>raResize(Number(c.dataset.question)));
}
function raStrokes(i){return reviewAnnoStore[String(i)]||(reviewAnnoStore[String(i)]=[]);}
function raCard(i){return document.getElementById('reviewQuestion-'+i);}
function raCanvas(i){return document.getElementById('reviewAnnotationCanvas-'+i);}
function raResize(i){
 const canvas=raCanvas(i),card=raCard(i);if(!canvas||!card||!canvas.dataset.initialized)return;
 const rect=card.getBoundingClientRect(),scale=Math.min(devicePixelRatio||1,2);
 if(!rect.width||!rect.height)return;
 const w=Math.round(rect.width*scale),h=Math.round(rect.height*scale);
 if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
 raRedraw(i);
}
function raRedraw(i){
 const canvas=raCanvas(i);if(!canvas||!canvas.width)return;
 const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;
 ctx.clearRect(0,0,w,h);
 for(const stroke of raStrokes(i)){
  const pts=stroke.points||[];if(!pts.length)continue;
  ctx.save();ctx.lineCap='round';ctx.lineJoin='round';
  ctx.globalCompositeOperation=stroke.tool==='eraser'?'destination-out':'source-over';
  ctx.globalAlpha=stroke.tool==='marker'?.38:1;
  ctx.strokeStyle=stroke.tool==='marker'?'#ffcd22':'#e43d65';
  ctx.lineWidth=(stroke.tool==='eraser'?26:stroke.tool==='marker'?18:3.5)*(w/Math.max(canvas.getBoundingClientRect().width,1));
  ctx.beginPath();ctx.moveTo(pts[0][0]*w,pts[0][1]*h);
  if(pts.length===1)ctx.lineTo(pts[0][0]*w+.2,pts[0][1]*h+.2);
  for(let j=1;j<pts.length;j++)ctx.lineTo(pts[j][0]*w,pts[j][1]*h);
  ctx.stroke();ctx.restore();
 }
}
function raInit(i){
 const canvas=raCanvas(i);if(!canvas||canvas.dataset.initialized)return;
 canvas.dataset.initialized='1';
 canvas.addEventListener('pointerdown',e=>{
  if(reviewAnnoActive!==i||!raServerReady)return;
  e.preventDefault();reviewAnnoDrawing=true;
  const r=canvas.getBoundingClientRect();
  reviewAnnoStroke={tool:reviewAnnoTool,points:[[Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]]};
  raStrokes(i).push(reviewAnnoStroke);
  try{canvas.setPointerCapture(e.pointerId);}catch(_){}raRedraw(i);
 });
 canvas.addEventListener('pointermove',e=>{
  if(!reviewAnnoDrawing||reviewAnnoActive!==i||!reviewAnnoStroke)return;
  e.preventDefault();const r=canvas.getBoundingClientRect();
  reviewAnnoStroke.points.push([Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))]);
  raRedraw(i);
 });
 const finish=()=>{if(reviewAnnoDrawing){reviewAnnoDrawing=false;reviewAnnoStroke=null;raSave(i);raToolbar(i);}};
 canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('lostpointercapture',finish);
 raResize(i);
}
function raToolbar(i){
 const card=raCard(i);if(!card)return;
 const on=reviewAnnoActive===i;card.classList.toggle('annotating',on);
 const toolbar=card.querySelector('.review-annotation-toolbar');
 const buttons=toolbar.querySelectorAll('button');
 buttons[0].textContent=on?'✅ Selesai mencoret':'✏️ Coret / Anotasi';buttons[0].classList.toggle('active',on);
 for(let j=1;j<=3;j++){buttons[j].disabled=!on;buttons[j].classList.toggle('active',on&&reviewAnnoTool===['pen','marker','eraser'][j-1]);}
 buttons[4].disabled=!on||!raStrokes(i).length;
 buttons[5].disabled=!on||!raStrokes(i).length;
 toolbar.querySelector('small').textContent=on?'Coret dengan mouse atau jari. Tekan Selesai mencoret agar halaman dapat digulir seperti biasa.':'Alat anotasi khusus pembahasan. Coretan tersimpan pada akun Stangolden dan dapat dibuka lintas perangkat.';
}
function raToggle(i){
 reviewAnnoDrawing=false;reviewAnnoStroke=null;
 const prior=reviewAnnoActive;reviewAnnoActive=prior===i?null:i;
 if(prior!==null&&prior!==i)raToolbar(prior);
 if(reviewAnnoActive===i){if(!raServerReady){alert('Menunggu data anotasi dari server. Silakan coba lagi.');reviewAnnoActive=null;}else raInit(i);}
 raToolbar(i);
}
function raTool(i,t){if(reviewAnnoActive!==i)return;reviewAnnoTool=t;raToolbar(i);}
function raUndo(i){if(reviewAnnoActive!==i)return;raStrokes(i).pop();raSave(i);raRedraw(i);raToolbar(i);}
function raClear(i){if(reviewAnnoActive!==i||!confirm('Hapus semua coretan pada pembahasan soal ini?'))return;reviewAnnoStore[String(i)]=[];raSave(i);raRedraw(i);raToolbar(i);}
function raButtons(i){return `<div class="review-annotation-toolbar">
 <button type="button" onclick="raToggle(${i})">✏️ Coret / Anotasi</button>
 <button type="button" onclick="raTool(${i},'pen')" disabled>✍️ Pena</button>
 <button type="button" onclick="raTool(${i},'marker')" disabled>🖍️ Stabilo</button>
 <button type="button" onclick="raTool(${i},'eraser')" disabled>⌫ Penghapus</button>
 <button type="button" onclick="raUndo(${i})" disabled>↶ Urungkan</button>
 <button type="button" onclick="raClear(${i})" disabled>🗑️ Hapus coretan</button>
 <small>Alat anotasi khusus pembahasan. Coretan tersimpan pada akun Stangolden dan dapat dibuka lintas perangkat.</small>
 </div>`;}
if(typeof ResizeObserver!=='undefined'){
 window.addEventListener('DOMContentLoaded',()=>{
